css:
@keyframes dbp-burnup-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbp-burnup-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbp-burnup-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbp-burnup-fade { from { opacity: 0; } }
@keyframes dbp-burnup-pop { from { opacity: 0; transform: scale(0.3); } }

.dbp-burnup {
  /* re-theme with these four */
  --dbp-burnup-bg: oklch(0.2 0.008 75);
  --dbp-burnup-ink: oklch(0.95 0.012 90);
  --dbp-burnup-done: oklch(0.88 0.18 122);
  --dbp-burnup-scope: oklch(0.77 0.15 52);
  /* derived */
  --dbp-burnup-panel: color-mix(in oklch, var(--dbp-burnup-bg), var(--dbp-burnup-ink) 4.5%);
  --dbp-burnup-raised: color-mix(in oklch, var(--dbp-burnup-bg), var(--dbp-burnup-ink) 9%);
  --dbp-burnup-line: color-mix(in oklch, var(--dbp-burnup-ink) 10%, transparent);
  --dbp-burnup-line-2: color-mix(in oklch, var(--dbp-burnup-ink) 20%, transparent);
  --dbp-burnup-muted: color-mix(in oklch, var(--dbp-burnup-ink) 62%, var(--dbp-burnup-bg));
  --dbp-burnup-faint: color-mix(in oklch, var(--dbp-burnup-ink) 38%, var(--dbp-burnup-bg));
  --dbp-burnup-bad: oklch(0.7 0.17 28);
  --dbp-burnup-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-burnup-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-burnup-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-burnup-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-burnup-bg);
  color: var(--dbp-burnup-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-burnup-done);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-burnup-done); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-burnup-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-burnup-muted); }
  .dbp-burnup-num { text-align: right; }

  .dbp-burnup-app {
    display: grid; height: 100%;
    grid-template-columns: 200px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side top" "side main";
  }

  /* ---------- sidebar ---------- */
  .dbp-burnup-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; border-right: 1px solid var(--dbp-burnup-line); background: color-mix(in oklch, var(--dbp-burnup-bg), black 18%); }
  .dbp-burnup-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-burnup-brand svg { width: 30px; height: 30px; padding: 5px; flex: none; border-radius: 8px; background: var(--dbp-burnup-done); fill: none; stroke: var(--dbp-burnup-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-burnup-brand span { display: grid; line-height: 1.2; }
  .dbp-burnup-brand b { font-weight: 720; letter-spacing: -0.01em; }
  .dbp-burnup-brand small { font-size: 11px; color: var(--dbp-burnup-muted); }
  .dbp-burnup-nav { display: grid; gap: 2px; }
  .dbp-burnup-navbtn { position: relative; width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-burnup-muted); font-weight: 560; transition: background-color 160ms, color 160ms; }
  .dbp-burnup-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-burnup-navbtn:hover { color: var(--dbp-burnup-ink); background: var(--dbp-burnup-line); }
  .dbp-burnup-navbtn[aria-current="page"] { color: var(--dbp-burnup-ink); background: var(--dbp-burnup-raised); }
  .dbp-burnup-navbtn[aria-current="page"]::before { content: ""; position: absolute; left: -12px; top: 8px; bottom: 8px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbp-burnup-done); }
  .dbp-burnup-navbtn[aria-current="page"] svg { color: var(--dbp-burnup-done); }
  .dbp-burnup-goal { margin-top: auto; display: grid; gap: 8px; padding: 14px 8px 0; border-top: 1px solid var(--dbp-burnup-line); }
  .dbp-burnup-goal p { font-size: 12.5px; line-height: 1.45; color: color-mix(in oklch, var(--dbp-burnup-ink) 85%, var(--dbp-burnup-bg)); }
  .dbp-burnup-team { display: flex; padding-left: 6px; }
  .dbp-burnup-team span { width: 26px; height: 26px; margin-left: -4px; display: grid; place-items: center; border-radius: 50%; font: 650 9.5px/1 system-ui, sans-serif; color: var(--dbp-burnup-bg); background: oklch(0.82 0.08 calc(var(--h) * 1deg)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--dbp-burnup-bg), black 18%); }

  /* ---------- top bar ---------- */
  .dbp-burnup-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; border-bottom: 1px solid var(--dbp-burnup-line); }
  .dbp-burnup-title { display: grid; gap: 3px; min-width: 0; }
  .dbp-burnup-h { font-size: clamp(18px, 0.9rem + 0.9cqi, 26px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.1; }
  .dbp-burnup-h em { font-style: normal; color: var(--dbp-burnup-muted); font-weight: 500; }
  .dbp-burnup-tools { display: flex; flex-wrap: wrap; gap: 8px; }
  .dbp-burnup-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: color-mix(in oklch, var(--dbp-burnup-bg), black 22%); box-shadow: inset 0 0 0 1px var(--dbp-burnup-line); }
  .dbp-burnup-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbp-burnup-muted); transition: color 150ms, background-color 150ms, transform 300ms var(--dbp-burnup-spring); }
  .dbp-burnup-seg[data-group="sprint"] button { font-family: var(--dbp-burnup-mono); font-size: 11.5px; }
  .dbp-burnup-seg button:hover { color: var(--dbp-burnup-ink); }
  .dbp-burnup-seg button:active { transform: scale(0.94); }
  .dbp-burnup-seg button[aria-checked="true"] { color: var(--dbp-burnup-bg); background: var(--dbp-burnup-ink); }

  /* ---------- main ---------- */
  .dbp-burnup-main { grid-area: main; min-height: 0; overflow: auto; padding: 14px 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dbp-burnup-line-2) transparent; }
  .dbp-burnup-view { min-height: 100%; }
  .dbp-burnup-view > * { animation: dbp-burnup-rise 520ms var(--dbp-burnup-ease) both; animation-delay: calc(var(--i, 0) * 60ms); }
  .dbp-burnup-vchart { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 292px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "kpi kpi" "chart led"; height: 100%; }
  .dbp-burnup-panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbp-burnup-panel); box-shadow: inset 0 0 0 1px var(--dbp-burnup-line); }
  .dbp-burnup-full { height: 100%; }
  .dbp-burnup-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 12px 14px 8px; }
  .dbp-burnup-ph h3 { font-size: 13px; font-weight: 650; letter-spacing: -0.005em; margin-right: auto; }
  .dbp-burnup-scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbp-burnup-line-2) transparent; }

  /* ---------- KPIs ---------- */
  .dbp-burnup-kpis { grid-area: kpi; --i: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--dbp-burnup-line); box-shadow: inset 0 0 0 1px var(--dbp-burnup-line); }
  .dbp-burnup-kpi { display: grid; gap: 1px; padding: 10px 14px 11px; background: var(--dbp-burnup-panel); min-width: 0; }
  .dbp-burnup-kpi b { font: 650 clamp(17px, 0.8rem + 0.9cqi, 23px)/1.15 var(--dbp-burnup-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbp-burnup-kpi b small { font-size: 0.55em; font-weight: 500; letter-spacing: 0; color: var(--dbp-burnup-muted); margin-left: 3px; }
  .dbp-burnup-kpi span { font-size: 11px; color: var(--dbp-burnup-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbp-burnup-kpi[data-k="added"] b { color: var(--dbp-burnup-scope); }
  .dbp-burnup-kpi[data-k="done"] b { color: var(--dbp-burnup-done); }
  .dbp-burnup-kpi[data-k="rem"] b[data-warn] { color: var(--dbp-burnup-bad); }

  /* ---------- chart ---------- */
  .dbp-burnup-chartp { grid-area: chart; --i: 1; }
  .dbp-burnup-legend { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dbp-burnup-muted); }
  .dbp-burnup-legend span { display: inline-flex; align-items: center; gap: 6px; }
  .dbp-burnup-legend i { width: 14px; height: 0; border-top: 2px solid var(--c); }
  .dbp-burnup-legend i[data-dash] { border-top-style: dashed; }
  .dbp-burnup-plot { position: relative; flex: 1; min-height: 200px; margin: 0 6px; touch-action: pan-y; }
  .dbp-burnup-plot:focus-visible { outline-offset: -2px; }
  .dbp-burnup-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; font: 10.5px var(--dbp-burnup-mono); }
  .dbp-burnup-svg stop { stop-color: var(--dbp-burnup-done); }
  .dbp-burnup-svg .dbp-burnup-gl { stroke: var(--dbp-burnup-line); stroke-width: 1; shape-rendering: crispEdges; }
  .dbp-burnup-svg .dbp-burnup-gl0 { stroke: var(--dbp-burnup-line-2); }
  .dbp-burnup-svg text { fill: var(--dbp-burnup-faint); font-variant-numeric: tabular-nums; }
  .dbp-burnup-svg .dbp-burnup-wk { fill: color-mix(in oklch, var(--dbp-burnup-ink) 2.5%, transparent); }
  .dbp-burnup-svg .dbp-burnup-wkl { fill: var(--dbp-burnup-faint); font: 600 9.5px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; }
  .dbp-burnup-grid, .dbp-burnup-xaxis { animation: dbp-burnup-fade 600ms ease-out both; }
  .dbp-burnup-area { animation: dbp-burnup-wipe 1100ms var(--dbp-burnup-ease) 120ms both; }
  .dbp-burnup-ideal { fill: none; stroke: var(--dbp-burnup-faint); stroke-width: 1.25; stroke-dasharray: 2 4; stroke-linecap: round; animation: dbp-burnup-fade 600ms 200ms both; }
  .dbp-burnup-pline, .dbp-burnup-sline { fill: none; stroke-width: 2.25; stroke-linejoin: round; stroke-linecap: round; }
  .dbp-burnup-pline { stroke: var(--dbp-burnup-scope); }
  .dbp-burnup-sline { stroke: var(--dbp-burnup-done); }
  .dbp-burnup-draw { stroke-dasharray: 1; animation: dbp-burnup-draw 1100ms var(--dbp-burnup-ease) 120ms both; }
  .dbp-burnup-proj { fill: none; stroke-width: 1.6; stroke-dasharray: 5 4; stroke-linecap: round; opacity: 0.8; animation: dbp-burnup-fade 500ms 1000ms both; }
  .dbp-burnup-proj[data-k="p"] { stroke: var(--dbp-burnup-scope); }
  .dbp-burnup-proj[data-k="s"] { stroke: var(--dbp-burnup-done); }
  .dbp-burnup-today line { stroke: var(--dbp-burnup-ink); stroke-width: 1; stroke-dasharray: 1 3; }
  .dbp-burnup-today rect { fill: var(--dbp-burnup-ink); }
  .dbp-burnup-today text { fill: var(--dbp-burnup-bg); font: 700 9px system-ui, sans-serif; letter-spacing: 0.08em; }
  .dbp-burnup-today { animation: dbp-burnup-fade 500ms 900ms both; }
  .dbp-burnup-marks { animation: dbp-burnup-fade 1ms 1000ms both; }
  .dbp-burnup-mk { transform-box: fill-box; transform-origin: center; animation: dbp-burnup-pop 520ms var(--dbp-burnup-spring) both; animation-delay: calc(1000ms + var(--i) * 70ms); cursor: pointer; }
  &[data-ready] .dbp-burnup-marks { animation: none; }
  &[data-ready] .dbp-burnup-mk { animation-delay: calc(80ms + var(--i) * 50ms); }
  .dbp-burnup-mk circle { fill: var(--dbp-burnup-bg); stroke: var(--dbp-burnup-scope); stroke-width: 1.75; transition: r 220ms var(--dbp-burnup-spring), fill 150ms; }
  .dbp-burnup-mk[data-neg] circle { stroke: var(--dbp-burnup-muted); }
  .dbp-burnup-mk path { stroke: var(--dbp-burnup-scope); stroke-width: 1.6; stroke-linecap: round; }
  .dbp-burnup-mk[data-neg] path { stroke: var(--dbp-burnup-muted); }
  .dbp-burnup-mk[data-on] circle { fill: var(--dbp-burnup-scope); r: 8.5; }
  .dbp-burnup-mk[data-on] path { stroke: var(--dbp-burnup-bg); }
  .dbp-burnup-mk[data-neg][data-on] circle { fill: var(--dbp-burnup-muted); }
  .dbp-burnup-xh line { stroke: var(--dbp-burnup-ink); stroke-opacity: 0.35; stroke-width: 1; }
  .dbp-burnup-xh circle { stroke: var(--dbp-burnup-bg); stroke-width: 2; }
  .dbp-burnup-xh { transition: opacity 150ms; }
  .dbp-burnup-xh[data-off] { opacity: 0; }
  .dbp-burnup-endl { font: 650 11px var(--dbp-burnup-mono); }
  .dbp-burnup-endl[data-k="p"] { fill: var(--dbp-burnup-scope); }
  .dbp-burnup-endl[data-k="s"] { fill: var(--dbp-burnup-done); }

  .dbp-burnup-tip {
    position: absolute; top: 8px; left: 0; z-index: 3; min-width: 188px; max-width: 250px; pointer-events: none;
    padding: 9px 11px 10px; border-radius: 10px; background: color-mix(in oklch, var(--dbp-burnup-bg), black 30%);
    box-shadow: 0 0 0 1px var(--dbp-burnup-line-2), 0 12px 28px -8px black; font-size: 12px;
    transition: opacity 140ms, translate 220ms var(--dbp-burnup-ease);
    @starting-style { opacity: 0; translate: 0 4px; }
  }
  .dbp-burnup-tip h4 { margin: 0 0 6px; font-size: 11px; font-weight: 650; letter-spacing: 0.04em; color: var(--dbp-burnup-muted); text-transform: uppercase; }
  .dbp-burnup-tip dl { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: 3px 14px; }
  .dbp-burnup-tip dt { display: flex; align-items: center; gap: 6px; color: var(--dbp-burnup-muted); }
  .dbp-burnup-tip dt i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  .dbp-burnup-tip dd { margin: 0; text-align: right; font: 600 12px var(--dbp-burnup-mono); font-variant-numeric: tabular-nums; }
  .dbp-burnup-tip ul { margin-top: 7px; padding-top: 7px; border-top: 1px solid var(--dbp-burnup-line); display: grid; gap: 3px; }
  .dbp-burnup-tip li { display: grid; grid-template-columns: 30px 1fr; gap: 6px; font-size: 11.5px; line-height: 1.3; color: color-mix(in oklch, var(--dbp-burnup-ink) 85%, transparent); }
  .dbp-burnup-tip li b { font: 650 11px var(--dbp-burnup-mono); color: var(--dbp-burnup-scope); }
  .dbp-burnup-tip li b[data-neg] { color: var(--dbp-burnup-muted); }
  .dbp-burnup-forecast { padding: 4px 16px 12px; font-size: 12px; color: var(--dbp-burnup-muted); }
  .dbp-burnup-forecast b { color: var(--dbp-burnup-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  .dbp-burnup-forecast b[data-bad] { color: var(--dbp-burnup-bad); }

  /* ---------- ledger panel ---------- */
  .dbp-burnup-ledgerp { grid-area: led; --i: 2; }
  .dbp-burnup-net { font: 600 11.5px var(--dbp-burnup-mono); color: var(--dbp-burnup-muted); font-variant-numeric: tabular-nums; }
  .dbp-burnup-events { flex: 1; min-height: 0; overflow: auto; padding: 0 8px 10px; scrollbar-width: thin; scrollbar-color: var(--dbp-burnup-line-2) transparent; }
  .dbp-burnup-ev { --c: var(--dbp-burnup-scope); position: relative; display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 8px 9px 10px; border-radius: 9px; cursor: pointer; transition: background-color 150ms; animation: dbp-burnup-rise 460ms var(--dbp-burnup-ease) both; animation-delay: calc(300ms + var(--i) * 45ms); }
  .dbp-burnup-ev[data-neg] { --c: var(--dbp-burnup-muted); }
  .dbp-burnup-ev + .dbp-burnup-ev::before { content: ""; position: absolute; left: 10px; right: 8px; top: 0; border-top: 1px solid var(--dbp-burnup-line); }
  .dbp-burnup-ev:hover { background: var(--dbp-burnup-line); }
  .dbp-burnup-ev[aria-selected="true"] { background: color-mix(in oklch, var(--c) 16%, transparent); }
  .dbp-burnup-ev[aria-selected="true"]::before, .dbp-burnup-ev[aria-selected="true"] + .dbp-burnup-ev::before { opacity: 0; }
  .dbp-burnup-ev:focus-visible { outline-offset: -2px; }
  .dbp-burnup-evd { grid-row: span 2; display: grid; align-content: start; font: 600 10.5px/1.3 var(--dbp-burnup-mono); color: var(--dbp-burnup-muted); text-transform: uppercase; }
  .dbp-burnup-evd b { font-size: 15px; color: var(--dbp-burnup-ink); font-weight: 650; }
  .dbp-burnup-evt { font-weight: 560; line-height: 1.3; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .dbp-burnup-evx { font: 700 12.5px var(--dbp-burnup-mono); color: var(--c); font-variant-numeric: tabular-nums; }
  .dbp-burnup-evm { grid-column: 2 / -1; display: flex; flex-wrap: wrap; gap: 4px 8px; align-items: center; font-size: 11px; color: var(--dbp-burnup-muted); }
  .dbp-burnup-evm code { font: 11px var(--dbp-burnup-mono); color: var(--dbp-burnup-faint); }
  .dbp-burnup-pill { display: inline-block; padding: 1px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 600; color: var(--c, var(--dbp-burnup-muted)); background: color-mix(in oklch, var(--c, var(--dbp-burnup-muted)) 15%, transparent); white-space: nowrap; }
  .dbp-burnup-empty { padding: 24px 12px; text-align: center; color: var(--dbp-burnup-faint); font-size: 12px; }

  /* ---------- tables ---------- */
  .dbp-burnup-chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .dbp-burnup-chip { height: 26px; padding: 0 10px; display: inline-flex; align-items: center; gap: 6px; border-radius: 99px; font-size: 12px; font-weight: 560; color: var(--dbp-burnup-muted); box-shadow: inset 0 0 0 1px var(--dbp-burnup-line-2); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbp-burnup-chip i { font: 600 10.5px var(--dbp-burnup-mono); font-style: normal; color: var(--dbp-burnup-faint); }
  .dbp-burnup-chip:hover { color: var(--dbp-burnup-ink); }
  .dbp-burnup-chip[aria-pressed="true"] { color: var(--dbp-burnup-bg); background: var(--dbp-burnup-ink); box-shadow: none; }
  .dbp-burnup-chip[aria-pressed="true"] i { color: color-mix(in oklch, var(--dbp-burnup-bg) 60%, transparent); }
  .dbp-burnup-selsum { font-size: 11.5px; color: var(--dbp-burnup-muted); font-variant-numeric: tabular-nums; }
  .dbp-burnup-table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px; }
  .dbp-burnup-table th { position: sticky; top: 0; z-index: 1; padding: 8px 12px; text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: 0.07em; text-transform: uppercase; color: var(--dbp-burnup-faint); background: var(--dbp-burnup-panel); border-bottom: 1px solid var(--dbp-burnup-line-2); white-space: nowrap; }
  .dbp-burnup-table th button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; }
  .dbp-burnup-table th button::after { content: ""; width: 6px; height: 6px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; transform: rotate(45deg) scale(0.8); opacity: 0; transition: transform 200ms var(--dbp-burnup-ease), opacity 150ms; }
  .dbp-burnup-table th[aria-sort="ascending"] button::after { opacity: 1; transform: rotate(-135deg) scale(0.8) translate(-2px, -2px); }
  .dbp-burnup-table th[aria-sort="descending"] button::after { opacity: 1; }
  .dbp-burnup-table th[aria-sort="ascending"], .dbp-burnup-table th[aria-sort="descending"] { color: var(--dbp-burnup-ink); }
  .dbp-burnup-table td { padding: 9px 12px; border-bottom: 1px solid var(--dbp-burnup-line); vertical-align: top; }
  .dbp-burnup-table td.dbp-burnup-num { font-family: var(--dbp-burnup-mono); font-variant-numeric: tabular-nums; }
  .dbp-burnup-table code { font: 11.5px var(--dbp-burnup-mono); color: var(--dbp-burnup-muted); }
