const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const uid = 'dbp-burnup-' + Math.random().toString(36).slice(2, 8);
const rng = seed => () => { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

/* ---------- data ----------
   Every number on screen is summed from the issue list below. An issue carries the
   day it entered the sprint (0 = committed at planning), the day it was removed and
   the day it was finished. Scope(d) and done(d) are recomputed from that for every
   view, unit and chart type, so the KPIs, the chart, the ledger and the table agree. */
const PEOPLE = [['Ines Varga', 28], ['Kwame Asante', 145], ['Mei Lindqvist', 205], ['Tomasz Brühl', 70], ['Sunniva Haugen', 320], ['Ravi Menon', 255]];
const REASON = {
  incident: ['Incident', 'var(--dbp-burnup-bad)'],
  carry: ['Carry-over', 'color-mix(in oklch, var(--dbp-burnup-scope), var(--dbp-burnup-done))'],
  stakeholder: ['Stakeholder', 'var(--dbp-burnup-scope)'],
  split: ['Split', 'color-mix(in oklch, var(--dbp-burnup-done), var(--dbp-burnup-ink) 45%)'],
  qa: ['Found in QA', 'oklch(0.76 0.12 300)'],
  moved: ['Moved out', 'var(--dbp-burnup-muted)'],
  descoped: ['Descoped', 'var(--dbp-burnup-muted)']
};
const TYPE = { story: ['Story', 'var(--dbp-burnup-done)'], bug: ['Bug', 'var(--dbp-burnup-bad)'], task: ['Task', 'var(--dbp-burnup-muted)'], spike: ['Spike', 'var(--dbp-burnup-scope)'] };
const STATUS = { done: 'Done', progress: 'In progress', todo: 'To do', spill: 'Spilled', removed: 'Removed' };

const SPRINTS = [
  { n: 38, name: 'Ledger v2 schema', start: '2026-08-17', key: 1201, seed: 694, ratio: 0.9, today: 10,
    goal: 'Ship the v2 ledger schema behind a dual-write flag with zero balance drift for 72 hours.',
    planned: [['Define v2 ledger entry schema', 'story', 5], ['Dual-write adapter for ledger postings', 'story', 8], ['Idempotency keys on the posting API', 'story', 5], ['Backfill job for historical balances', 'story', 8], ['Drift report: v1 vs v2 balances', 'story', 3], ['Store fees as signed minor units', 'task', 3], ['Partition entries by settlement month', 'task', 5], ['Alert when dual-write mismatch > 0.01%', 'task', 2], ['Load test posting API at 3k rps', 'spike', 3], ['Archive v1 entries to cold storage', 'story', 5], ['Read path behind the v2 flag', 'story', 5], ['Minor-unit table for 41 currencies', 'task', 2], ['Audit trail for manual adjustments', 'story', 3], ['Write up the ledger invariants', 'task', 1]],
    adds: [[2, 'Hotfix: duplicate fee on split tenders', 'bug', 3, 'incident', 'On-call rotation'], [4, 'Month-end export for the Finance close', 'story', 5, 'stakeholder', 'Odile Marchetti, Finance'], [7, 'Throttle backfill to 400 rows/s', 'task', 2, 'split', 'Split from the backfill job']],
    removes: [[6, 9, 'moved', 'Cold tier not provisioned yet']] },
  { n: 39, name: 'Refund rails', start: '2026-08-31', key: 1241, seed: 726, ratio: 0.86, today: 10,
    goal: 'Partial and full refunds post to the ledger and reach card networks without manual steps.',
    planned: [['Refund state machine with partial amounts', 'story', 8], ['Reverse ledger postings on refund', 'story', 5], ['Card-network refund adapter', 'story', 8], ['Refund webhooks for merchants', 'story', 5], ['Retry policy with exponential backoff', 'task', 3], ['Refund limits per merchant tier', 'story', 3], ['Dashboard: refunds pending over 48 h', 'task', 2], ['Contract tests against the acquirer sandbox', 'task', 3], ['Currency mismatch on refunds', 'bug', 2], ['Refund reason codes', 'task', 1], ['Instant refunds via push-to-card', 'spike', 3], ['Idempotent refund creation', 'story', 3], ['Runbook for stuck refunds', 'task', 2]],
    adds: [[1, 'Drift report: edge cases from S38', 'story', 3, 'carry', 'Carried from S38'], [3, 'Rounding on JPY partial refunds', 'bug', 2, 'qa', 'Lena Park, QA'], [5, 'Refund memo field for merchants', 'story', 3, 'stakeholder', 'Merchant success'], [8, 'Hotfix: webhook signature on retries', 'bug', 2, 'incident', 'On-call rotation']],
    removes: [[4, 10, 'descoped', 'Acquirer API not generally available']] },
  { n: 40, name: 'Payout batching', start: '2026-09-14', key: 1288, seed: 578, ratio: 0.82, today: 10,
    goal: 'Merchants receive one netted payout per settlement window instead of one per charge.',
    planned: [['Batch payouts by settlement window', 'story', 8], ['Net fees against payouts', 'story', 5], ['Payout holds for risk review', 'story', 5], ['SEPA bank file generator', 'story', 8], ['Payout status webhooks', 'story', 3], ['Archive v1 entries to cold storage', 'story', 5], ['Payout preview API', 'story', 3], ['Holiday calendar for 14 banking regions', 'task', 3], ['Alert on bank file rejection', 'task', 2], ['Reconcile bank statements', 'story', 5], ['Load test a 40k-payout batch', 'spike', 3], ['Payout lifecycle docs', 'task', 1]],
    adds: [[2, 'Hotfix: payout duplicated on retry', 'bug', 3, 'incident', 'On-call rotation'], [3, 'SEPA file schema validation', 'task', 3, 'split', 'Split from the bank file generator'], [6, 'Payout fee breakdown export', 'story', 3, 'stakeholder', 'Odile Marchetti, Finance'], [6, 'Cut-off time wrong in Europe/Lisbon', 'bug', 2, 'qa', 'Lena Park, QA']],
    removes: [[5, 10, 'moved', 'Staging capacity booked by Risk'], [8, 6, 'descoped', 'Product dropped preview for v1']] },
  { n: 41, name: 'Ledger cutover', start: '2026-09-28', key: 1330, seed: 520, ratio: 0.8, today: 5,
    goal: 'All reads and writes run on the v2 ledger, with a rehearsed rollback and v1 frozen.',
    planned: [['Cut reads over to the v2 ledger', 'story', 8], ['Freeze v1 writes behind a kill switch', 'story', 5], ['Final backfill and checksum', 'task', 5], ['Shadow-compare balances for 24 h', 'task', 3], ['Rollback rehearsal in staging', 'task', 3], ['Remove the dual-write adapter', 'story', 5], ['Point reporting views at v2', 'story', 5], ['Migrate merchant statements', 'story', 8], ['Load test a 40k-payout batch', 'spike', 3], ['Status page copy for the cutover', 'task', 1], ['Decommission v1 replicas', 'task', 3]],
    adds: [[1, 'SEPA file schema validation', 'task', 3, 'carry', 'Carried from S40'], [2, 'v2 balance off by FX rounding', 'bug', 2, 'qa', 'Shadow compare'], [4, 'Freeze-window sign-off pack', 'story', 3, 'stakeholder', 'Odile Marchetti, Finance'], [5, 'Hotfix: statement PDF timezone', 'bug', 1, 'incident', 'On-call rotation']],
    removes: [[3, 10, 'moved', 'Kept for rollback until S42']] }
];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const workdays = iso => {
  const [y, m, d] = iso.split('-').map(Number), out = [], dt = new Date(Date.UTC(y, m - 1, d));
  while (out.length < 10) { const w = dt.getUTCDay(); if (w > 0 && w < 6) out.push(new Date(dt)); dt.setUTCDate(dt.getUTCDate() + 1); }
  return out;
};
SPRINTS.forEach(sp => {
  const r = rng(sp.seed * 7919);
  sp.days = workdays(sp.start);
  let k = sp.key;
  const all = sp.planned.map(([title, type, pts]) => ({ title, type, pts, added: 0, removed: null }));
  sp.adds.forEach(([day, title, type, pts, reason, by]) => all.push({ title, type, pts, added: day, removed: null, reason, by }));
  sp.removes.forEach(([day, idx, reason, note]) => Object.assign(all[idx], { removed: day, rreason: reason, note }));
  all.forEach(i => {
    i.key = 'PAY-' + (k++);
    i.who = r() * PEOPLE.length | 0;
    /* finish days follow a centred (triangular) spread, so the cumulative line is an S-curve */
    const b = (r() + r()) / 2;
    i.plan = i.removed != null ? null : Math.min(10, i.added + 1 + Math.floor(b * (10 - i.added)));
    i.started = r() < 0.55;
    i.rank = r();
  });
  /* the (1 - ratio) share of points that never lands: taken from the latest finishers */
  const live = all.filter(i => i.plan != null).sort((a, b) => b.plan - a.plan || a.rank - b.rank);
  let miss = (1 - sp.ratio) * live.reduce((a, i) => a + i.pts, 0);
  for (const i of live) { if (miss <= 0) break; if (i.pts <= miss + 1) { miss -= i.pts; i.plan = null; } }
  /* the current sprint only knows what has happened up to today */
  sp.issues = all.filter(i => i.added <= sp.today).map(i => {
    const removed = i.removed != null && i.removed <= sp.today ? i.removed : null;
    const done = removed == null && i.plan != null && i.plan <= sp.today ? i.plan : null;
    const status = removed != null ? 'removed' : done != null ? 'done' : sp.today < 10 ? (i.started || (i.plan != null && i.plan <= sp.today + 2) ? 'progress' : 'todo') : 'spill';
    return { ...i, removed, done, status };
  });
  sp.events = [];
  sp.issues.forEach(i => {
    if (i.added > 0) sp.events.push({ day: i.added, issue: i, sign: 1, reason: i.reason, by: i.by });
    if (i.removed != null) sp.events.push({ day: i.removed, issue: i, sign: -1, reason: i.rreason, by: i.note });
  });
  sp.events.sort((a, b) => a.day - b.day || b.sign - a.sign);
  sp.events.forEach((e, n) => { e.n = n; });
});

const compute = (sp, unit) => {
  const v = i => unit === 'pts' ? i.pts : 1;
  const cut = sp.today, scope = [], done = [];
  for (let d = 0; d <= 10; d++) {
    const dd = Math.min(d, cut); let s = 0, c = 0;
    sp.issues.forEach(i => {
      if (i.added <= dd && !(i.removed != null && i.removed <= dd)) s += v(i);
      if (i.done != null && i.done <= dd) c += v(i);
    });
    scope.push(s); done.push(c);
  }
  const sum = list => list.reduce((a, i) => a + v(i), 0);
  const addedL = sp.issues.filter(i => i.added > 0), removedL = sp.issues.filter(i => i.removed != null);
  const committed = scope[0], added = sum(addedL), removed = sum(removedL);
  const completed = done[cut], final = scope[cut], remaining = final - completed;
  const rate = cut ? completed / cut : 0;
  const projDone = Math.min(final, completed + rate * (10 - cut));
  return { v, scope, done, rem: scope.map((s, d) => s - done[d]), committed, added, removed, nAdded: addedL.length, nRemoved: removedL.length, completed, final, remaining, cut, rate, projDone };
};

/* ---------- state ---------- */
const S = { sp: 3, mode: 'up', unit: 'pts', hover: null, pin: null, reasons: new Set(Object.keys(REASON)), statuses: null, sort: { k: 'key', dir: 1 }, picked: new Set(), view: 'chart' };
const sp = () => SPRINTS[S.sp];
const unitLabel = () => S.unit === 'pts' ? 'pts' : 'issues';
const fmtD = d => `${DOW[d.getUTCDay()]} ${MON[d.getUTCMonth()]} ${d.getUTCDate()}`;
const dayLabel = (s, d) => d === 0 ? 'Planning' : fmtD(s.days[d - 1]);

/* ---------- chart scaffold ---------- */
const plot = $('.dbp-burnup-plot'), svg = $('.dbp-burnup-svg'), tip = $('.dbp-burnup-tip');
svg.innerHTML = `
  <defs>
    <linearGradient id="${uid}-g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-opacity="0.34"/><stop offset="1" stop-opacity="0"/></linearGradient>
    <clipPath id="${uid}-c"><rect x="0" y="-20" width="0" height="0"/></clipPath>
  </defs>
  <g class="dbp-burnup-weeks"></g>
  <g class="dbp-burnup-grid"></g>
  <g class="dbp-burnup-xaxis"></g>
  <path class="dbp-burnup-area" fill="url(#${uid}-g)" clip-path="url(#${uid}-c)"/>
  <path class="dbp-burnup-ideal"/>
  <path class="dbp-burnup-proj" data-k="p"/>
  <path class="dbp-burnup-proj" data-k="s"/>
  <path class="dbp-burnup-sline dbp-burnup-draw" pathLength="1" clip-path="url(#${uid}-c)"/>
  <path class="dbp-burnup-pline dbp-burnup-draw" pathLength="1" clip-path="url(#${uid}-c)"/>
  <g class="dbp-burnup-today"><line/><rect rx="3" width="40" height="15"/><text text-anchor="middle">TODAY</text></g>
  <g class="dbp-burnup-ends"><text class="dbp-burnup-endl" data-k="p"/><text class="dbp-burnup-endl" data-k="s"/></g>
  <g class="dbp-burnup-marks"></g>
  <g class="dbp-burnup-xh" data-off><line/><circle r="4.5" data-k="p"/><circle r="4.5" data-k="s"/></g>`;
const q = s => svg.querySelector(s);
const el = {
  weeks: q('.dbp-burnup-weeks'), grid: q('.dbp-burnup-grid'), xaxis: q('.dbp-burnup-xaxis'), clip: q('clipPath rect'),
  area: q('.dbp-burnup-area'), ideal: q('.dbp-burnup-ideal'), projP: q('.dbp-burnup-proj[data-k="p"]'), projS: q('.dbp-burnup-proj[data-k="s"]'),
  pl: q('.dbp-burnup-pline'), sl: q('.dbp-burnup-sline'), today: q('.dbp-burnup-today'), endP: q('.dbp-burnup-endl[data-k="p"]'), endS: q('.dbp-burnup-endl[data-k="s"]'),
  marks: q('.dbp-burnup-marks'), xh: q('.dbp-burnup-xh')
};
el.xh.querySelector('[data-k="p"]').style.fill = 'var(--dbp-burnup-scope)';
el.xh.querySelector('[data-k="s"]').style.fill = 'var(--dbp-burnup-done)';

const niceStep = raw => { const p = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-6)))), f = raw / p; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; };
const valAt = (arr, t) => { const i = Math.floor(t), f = t - i; return i >= arr.length - 1 ? arr[arr.length - 1] : arr[i] + (arr[i + 1] - arr[i]) * f; };

const target = () => {
  const s = sp(), c = compute(s, S.unit), up = S.mode === 'up';
  const P = up ? c.scope : c.rem;
  const I = Array.from({ length: 11 }, (_, d) => up ? c.committed * d / 10 : c.committed * (1 - d / 10));
  const pEnd = up ? c.final : Math.max(0, c.remaining - c.rate * (10 - c.cut));
  const sEnd = up ? c.projDone : 0;
  const raw = Math.max(...P, c.committed, 1);
  const step = niceStep(raw / 4.2);
  return { P, S: c.done.slice(), I, k: up ? 1 : 0, sOp: up ? 1 : 0, cut: c.cut, pEnd, sEnd, max: Math.ceil(raw * 1.04 / step) * step, c };
};
let cur = null, geom = null, markDays = [];

const buildMarks = () => {
  const s = sp(), by = new Map(), v = compute(s, S.unit).v;
  s.events.forEach(e => { const g = by.get(e.day) || { day: e.day, net: 0, list: [] }; g.net += e.sign * v(e.issue); g.list.push(e); by.set(e.day, g); });
  markDays = [...by.values()];
  el.marks.innerHTML = markDays.map((g, i) => `<g data-day="${g.day}"><g class="dbp-burnup-mk" style="--i:${i}"${g.net < 0 ? ' data-neg' : ''}><circle r="7"/><path d="${g.net < 0 ? 'M-3.5 0H3.5' : 'M-3.5 0H3.5M0 -3.5V3.5'}"/></g></g>`).join('');
};

const draw = st => {
  const W = plot.clientWidth, H = plot.clientHeight;
  if (!W || !H) return;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const narrow = W < 480, s = sp();
  const m = { l: 38, r: narrow ? 16 : 60, t: 22, b: 30 };
  const iw = W - m.l - m.r, ih = H - m.t - m.b;
  const x = d => m.l + d / 10 * iw, y = v => m.t + ih - v / st.max * ih;
  geom = { x, y, m, iw, ih, W, H };
  const f = n => Math.round(n * 10) / 10;

  /* week bands */
  el.weeks.innerHTML = `<rect class="dbp-burnup-wk" x="${f(x(5))}" y="${m.t - 16}" width="${f(x(10) - x(5))}" height="${ih + 16}"/>` +
    `<text class="dbp-burnup-wkl" x="${f(x(2.5))}" y="${m.t - 5}" text-anchor="middle">Week 1</text><text class="dbp-burnup-wkl" x="${f(x(7.5))}" y="${m.t - 5}" text-anchor="middle">Week 2</text>`;
  /* grid + y labels */
  const step = niceStep(st.max / 4.2); let g = '';
  for (let v = 0; v <= st.max + 1e-6; v += step) {
    const yy = Math.round(y(v)) + 0.5;
    g += `<line class="dbp-burnup-gl${v === 0 ? ' dbp-burnup-gl0' : ''}" x1="${m.l}" x2="${W - m.r}" y1="${yy}" y2="${yy}"/><text x="${m.l - 8}" y="${yy + 3.5}" text-anchor="end">${Math.round(v)}</text>`;
  }
  el.grid.innerHTML = g;
  /* x labels: weekday + date, thinned when a day is narrower than a label */
  const per = iw / 10; let xa = '';
  for (let d = 1; d <= 10; d++) {
    if (per < 30 && d % 2) continue;
    const dt = s.days[d - 1], lab = per < 44 ? String(dt.getUTCDate()) : `${DOW[dt.getUTCDay()]} ${dt.getUTCDate()}`;
    xa += `<text x="${f(x(d))}" y="${H - 10}" text-anchor="middle">${lab}</text>`;
  }
  el.xaxis.innerHTML = xa;

  /* series */
  const pts = arr => arr.map((v, d) => `${d ? 'L' : 'M'}${f(x(d))},${f(y(v))}`).join('');
  let p = `M${f(x(0))},${f(y(st.P[0]))}`;
  for (let d = 1; d <= 10; d++) { const a = x(d - 1), b = x(d); p += `L${f(a + st.k * (b - a))},${f(y(st.P[d - 1]))}L${f(b)},${f(y(st.P[d]))}`; }
  el.pl.setAttribute('d', p);
  el.sl.setAttribute('d', pts(st.S));
  el.sl.style.opacity = st.sOp;
  el.area.setAttribute('d', pts(st.S) + `L${f(x(10))},${f(y(0))}L${f(x(0))},${f(y(0))}Z`);
  el.area.style.opacity = st.sOp;
  el.ideal.setAttribute('d', pts(st.I));
  const cx = x(st.cut);
  el.clip.setAttribute('width', st.cut >= 9.999 ? W : f(cx + 1.5));
  el.clip.setAttribute('height', H + 40);

  /* forecast from today to the last day */
  const live = st.cut < 9.999;
  const p0 = valAt(st.P, st.cut), s0 = valAt(st.S, st.cut);
  el.projP.setAttribute('d', live ? `M${f(cx)},${f(y(p0))}L${f(x(10))},${f(y(st.pEnd))}` : '');
  el.projS.setAttribute('d', live ? `M${f(cx)},${f(y(s0))}L${f(x(10))},${f(y(st.sEnd))}` : '');
  el.projS.style.opacity = st.sOp;
  el.today.style.display = live ? '' : 'none';
  if (live) {
    el.today.setAttribute('transform', `translate(${f(cx)} 0)`);
    const ln = el.today.querySelector('line'); ln.setAttribute('y1', m.t); ln.setAttribute('y2', m.t + ih);
    el.today.querySelector('rect').setAttribute('x', -20); el.today.querySelector('rect').setAttribute('y', m.t - 18);
    el.today.querySelector('text').setAttribute('y', m.t - 7.5);
  }
  /* end labels, nudged apart when they would collide */
  if (!narrow) {
    let yp = y(live ? st.pEnd : st.P[10]), ys = y(live ? st.sEnd : st.S[10]);
    const sOn = st.sOp > 0.05;
    if (sOn && Math.abs(yp - ys) < 14) { const mid = (yp + ys) / 2, up = yp <= ys; yp = mid + (up ? -7 : 7); ys = mid + (up ? 7 : -7); }
    el.endP.setAttribute('x', f(x(10) + 8)); el.endP.setAttribute('y', f(yp + 4)); el.endP.textContent = Math.round(live ? st.pEnd : st.P[10]);
    el.endS.setAttribute('x', f(x(10) + 8)); el.endS.setAttribute('y', f(ys + 4)); el.endS.textContent = sOn ? Math.round(live ? st.sEnd : st.S[10]) : '';
    el.endS.style.opacity = st.sOp;
  } else { el.endP.textContent = ''; el.endS.textContent = ''; }

  /* scope-change markers ride the primary line */
  el.marks.querySelectorAll('[data-day]').forEach(gm => { const d = +gm.dataset.day; gm.setAttribute('transform', `translate(${f(x(d))} ${f(y(st.P[d]))})`); });
  placeCross();
};

/* ---------- tween between states (sprint, unit, chart type) ---------- */
let raf = 0;
const ease = t => t >= 1 ? 1 : 1 - (1 + 8 * t) * Math.exp(-8 * t);
const lerp = (a, b, t) => a + (b - a) * t;
const mix = (a, b, t) => ({ P: a.P.map((v, i) => lerp(v, b.P[i], t)), S: a.S.map((v, i) => lerp(v, b.S[i], t)), I: a.I.map((v, i) => lerp(v, b.I[i], t)), k: lerp(a.k, b.k, t), sOp: lerp(a.sOp, b.sOp, t), cut: lerp(a.cut, b.cut, t), pEnd: lerp(a.pEnd, b.pEnd, t), sEnd: lerp(a.sEnd, b.sEnd, t), max: lerp(a.max, b.max, t), c: b.c });
let kpiNow = null;
const go = () => {
  const to = target();
  buildMarks();
  const kTo = kpiValues(to.c);
  if (reduce || !cur) { cur = to; kpiNow = kTo; draw(cur); renderKpis(kTo, to.c); return; }
  const from = cur, kFrom = kpiNow, t0 = performance.now();
  cancelAnimationFrame(raf);
  const step = now => {
    if (!root.isConnected) return;
    const t = Math.min(1, (now - t0) / 720), e = ease(t);
    cur = t >= 1 ? to : mix(from, to, e);
    kpiNow = kTo.map((v, i) => lerp(kFrom[i], v, e));
    draw(cur); renderKpis(kpiNow, to.c);
    if (t < 1) raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
};

/* ---------- KPIs ---------- */
const kpiBox = $('[data-kpis]');
kpiBox.innerHTML = ['committed', 'added', 'removed', 'done', 'rem', 'drift'].map(k => `<div class="dbp-burnup-kpi" data-k="${k}"><span></span><b></b><span></span></div>`).join('');
const kpiValues = c => [c.committed, c.added, c.removed, c.completed, c.remaining, c.committed ? (c.added - c.removed) / c.committed * 100 : 0];
const renderKpis = (vals, c) => {
  const u = `<small>${unitLabel()}</small>`, s = sp(), r = Math.round;
  const rows = [
    ['Committed', `${r(vals[0])}${u}`, 'at sprint planning'],
    ['Added mid-sprint', `+${r(vals[1])}${u}`, `${c.nAdded} issue${c.nAdded === 1 ? '' : 's'} entered`],
    ['Removed', `−${r(vals[2])}${u}`, `${c.nRemoved} issue${c.nRemoved === 1 ? '' : 's'} left`],
    ['Completed', `${r(vals[3])}${u}`, `${c.final ? Math.round(c.completed / c.final * 100) : 0}% of current scope`],
    ['Remaining', `${r(vals[4])}${u}`, s.today < 10 ? `${10 - s.today} working days left` : 'spilled to next sprint'],
    ['Scope drift', `${vals[5] >= 0 ? '+' : '−'}${Math.abs(vals[5]).toFixed(0)}<small>%</small>`, 'vs commitment']
  ];
  $$('.dbp-burnup-kpi', kpiBox).forEach((k, i) => {
    const [a, b, d] = rows[i], sp0 = k.children;
    if (sp0[0].textContent !== a) sp0[0].textContent = a;
    sp0[1].innerHTML = b; sp0[2].textContent = d;
    if (i === 4) sp0[1].toggleAttribute('data-warn', s.today >= 10 && c.remaining > 0);
  });
};

/* ---------- crosshair + tooltip ---------- */
const placeCross = () => {
  const d = S.hover ?? S.pin;
  el.marks.querySelectorAll('[data-day]').forEach(gm => gm.firstElementChild.toggleAttribute('data-on', +gm.dataset.day === d));
  if (d == null || !geom || !cur) { el.xh.setAttribute('data-off', ''); tip.hidden = true; return; }
  const { x, y, m, ih, W } = geom, c = cur.c, s = sp(), live = d > c.cut, up = S.mode === 'up';
  el.xh.removeAttribute('data-off');
  const ln = el.xh.querySelector('line');
  ln.setAttribute('x1', x(d)); ln.setAttribute('x2', x(d)); ln.setAttribute('y1', m.t); ln.setAttribute('y2', m.t + ih);
  const lerpLive = (a, end) => live ? valAt(a, c.cut) + (end - valAt(a, c.cut)) * (d - c.cut) / (10 - c.cut) : a[d];
  const pv = lerpLive(cur.P, cur.pEnd), sv = lerpLive(cur.S, cur.sEnd);
  const cp = el.xh.querySelector('[data-k="p"]'), cs = el.xh.querySelector('[data-k="s"]');
  cp.setAttribute('cx', x(d)); cp.setAttribute('cy', y(pv));
  cs.setAttribute('cx', x(d)); cs.setAttribute('cy', y(sv)); cs.style.display = up ? '' : 'none';
  const u = unitLabel(), r1 = n => Math.round(n * 10) / 10;
  const ideal = up ? c.committed * d / 10 : c.committed * (1 - d / 10);
  const rows = live
    ? (up ? [['Scope (if no change)', c.final, 'var(--dbp-burnup-scope)'], ['Forecast completed', r1(c.completed + c.rate * (d - c.cut)), 'var(--dbp-burnup-done)']]
          : [['Forecast remaining', r1(Math.max(0, c.remaining - c.rate * (d - c.cut))), 'var(--dbp-burnup-scope)']])
    : (up ? [['Scope', c.scope[d], 'var(--dbp-burnup-scope)'], ['Completed', c.done[d], 'var(--dbp-burnup-done)'], ['Remaining', c.rem[d], 'transparent']]
          : [['Remaining', c.rem[d], 'var(--dbp-burnup-scope)'], ['Completed', c.done[d], 'transparent'], ['Scope', c.scope[d], 'transparent']]);
  rows.push(['Ideal', r1(ideal), 'var(--dbp-burnup-faint)']);
  const evs = live ? [] : s.events.filter(e => e.day === d);
  tip.innerHTML = `<h4>${dayLabel(s, d)}${d ? ` · day ${d}` : ''}${live ? ' · forecast' : ''}</h4><dl>${rows.map(([a, b, col]) => `<dt><i style="--c:${col}"></i>${a}</dt><dd>${b} ${u}</dd>`).join('')}</dl>` +
    (evs.length ? `<ul>${evs.map(e => `<li><b${e.sign < 0 ? ' data-neg' : ''}>${e.sign > 0 ? '+' : '−'}${c.v(e.issue)}</b><span>${esc(e.issue.title)}</span></li>`).join('')}</ul>` : '');
  tip.hidden = false;
  const tw = tip.offsetWidth, px = x(d);
  tip.style.left = (px + 16 + tw > W ? Math.max(4, px - 16 - tw) : px + 16) + 'px';
};
const setHover = d => { S.hover = d; placeCross(); };
const dayFromEvent = e => { const r = plot.getBoundingClientRect(); return clamp(Math.round((e.clientX - r.left - geom.m.l) / geom.iw * 10), 0, 10); };
plot.addEventListener('pointermove', e => { if (geom) setHover(dayFromEvent(e)); });
plot.addEventListener('pointerleave', () => setHover(null));
plot.addEventListener('click', e => {
  if (!geom) return;
  const d = dayFromEvent(e), ev = sp().events.find(x => x.day === d);
  if (ev) selectEvent(ev.n, false); else { S.pin = null; syncEvents(); placeCross(); }
});
plot.addEventListener('keydown', e => {
  const d0 = S.hover ?? S.pin ?? -1;
  let d = null;
  if (e.key === 'ArrowRight') d = Math.min(10, d0 + 1);
  else if (e.key === 'ArrowLeft') d = Math.max(0, d0 < 0 ? 10 : d0 - 1);
  else if (e.key === 'Home') d = 0;
  else if (e.key === 'End') d = 10;
  else if (e.key === 'Escape') { S.hover = null; S.pin = null; syncEvents(); placeCross(); return; }
  else return;
  e.preventDefault(); setHover(d);
});
plot.addEventListener('blur', () => { if (S.hover != null) setHover(null); });

/* ---------- ledger list (chart view) ---------- */
const evList = $('[data-events]');
const renderEvents = () => {
  const s = sp(), c = compute(s, S.unit);
  $('[data-net]').textContent = `${c.added - c.removed >= 0 ? '+' : '−'}${Math.abs(c.added - c.removed)} ${unitLabel()} net`;
  evList.innerHTML = s.events.length ? s.events.map((e, i) => {
