      <span class="dbp-burnup-evm"><span class="dbp-burnup-pill" style="--c:${rc}">${rl}</span><code>${e.issue.key}</code><span>${esc(e.by)}</span></span>
    </li>`;
  }).join('') : '<li class="dbp-burnup-empty">No scope changed this sprint.</li>';
  const first = evList.querySelector('[role="option"]'); if (first) first.tabIndex = 0;
  syncEvents();
};
const syncEvents = () => {
  const s = sp(), on = S.pin == null ? null : S.pinN;
  $$('[role="option"]', evList).forEach(li => li.setAttribute('aria-selected', String(+li.dataset.n === on)));
};
const selectEvent = (n, focus) => {
  const e = sp().events[n]; if (!e) return;
  S.pin = e.day; S.pinN = n;
  $$('[role="option"]', evList).forEach(li => { li.tabIndex = +li.dataset.n === n ? 0 : -1; });
  syncEvents(); placeCross();
  const li = evList.querySelector(`[data-n="${n}"]`);
