};
evList.addEventListener('click', e => { const li = e.target.closest('[role="option"]'); if (li) selectEvent(+li.dataset.n, false); });
evList.addEventListener('pointerover', e => { const li = e.target.closest('[role="option"]'); if (li) setHover(sp().events[+li.dataset.n].day); });
evList.addEventListener('pointerleave', () => setHover(null));
evList.addEventListener('keydown', e => {
  const opts = $$('[role="option"]', evList); if (!opts.length) return;
  const i = opts.indexOf(document.activeElement);
  let j = null;
  if (e.key === 'ArrowDown') j = Math.min(opts.length - 1, i + 1);
