  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = opts.length - 1;
  else if (e.key === 'Escape') { S.pin = null; syncEvents(); placeCross(); return; }
  else if (e.key === 'Enter' || e.key === ' ') { if (i >= 0) selectEvent(+opts[i].dataset.n, true); e.preventDefault(); return; }
  else return;
