/* ---------- issues view ---------- */
const statusBox = $('[data-status]'), tbody = $('[data-issues]');
const ORDER = { done: 0, progress: 1, todo: 2, spill: 3, removed: 4 };
const sorters = {
  key: (a, b) => a.key.localeCompare(b.key), title: (a, b) => a.title.localeCompare(b.title), who: (a, b) => PEOPLE[a.who][0].localeCompare(PEOPLE[b.who][0]),
  pts: (a, b) => a.pts - b.pts, status: (a, b) => ORDER[a.status] - ORDER[b.status], done: (a, b) => (a.done ?? 99) - (b.done ?? 99)
};
const renderIssues = (flipIt) => {
  const s = sp(), counts = {};
  s.issues.forEach(i => { counts[i.status] = (counts[i.status] || 0) + 1; });
  if (!S.statuses) S.statuses = new Set(Object.keys(STATUS));
  statusBox.innerHTML = Object.keys(STATUS).filter(k => counts[k]).map(k => `<button class="dbp-burnup-chip" data-s="${k}" aria-pressed="${S.statuses.has(k)}">${STATUS[k]}<i>${counts[k]}</i></button>`).join('');
  const list = s.issues.filter(i => S.statuses.has(i.status)).sort((a, b) => sorters[S.sort.k](a, b) * S.sort.dir || a.key.localeCompare(b.key));
  const paint = () => {
    const keep = new Map(Array.from(tbody.rows).map(r => [r.dataset.key, r]));
    const frag = document.createDocumentFragment();
    list.forEach(i => {
      let tr = keep.get(i.key);
      if (!tr) {
        tr = document.createElement('tr'); tr.dataset.key = i.key; tr.tabIndex = -1;
        const [tl, tc] = TYPE[i.type], dd = i.done ? s.days[i.done - 1] : null;
        tr.innerHTML = `<td><code>${i.key}</code></td><td class="dbp-burnup-ttl"><span>${esc(i.title)}</span><small><i class="dbp-burnup-ty" style="--c:${tc}"></i>${tl}${i.added ? ` · added day ${i.added}` : ''}</small></td>
          <td>${PEOPLE[i.who][0]}</td><td class="dbp-burnup-num">${i.pts}</td><td><span class="dbp-burnup-st" data-s="${i.status}">${STATUS[i.status]}</span></td><td class="dbp-burnup-num">${dd ? `${DOW[dd.getUTCDay()]} ${dd.getUTCDate()}` : '—'}</td>`;
      }
      tr.setAttribute('aria-selected', String(S.picked.has(i.key)));
      frag.appendChild(tr);
    });
    tbody.replaceChildren(frag);
    if (!list.length) tbody.innerHTML = '<tr><td colspan="6" class="dbp-burnup-empty">No issues match these filters.</td></tr>';
    const firstRow = tbody.querySelector('tr[data-key]'); if (firstRow && !tbody.querySelector('tr[tabindex="0"]')) firstRow.tabIndex = 0;
  };
  if (flipIt && !reduce) {
    const before = new Map(Array.from(tbody.rows).map(r => [r.dataset.key, r.getBoundingClientRect().top]));
    paint();
    Array.from(tbody.rows).forEach(r => {
      const b = before.get(r.dataset.key); if (b == null) return;
      const dy = b - r.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) r.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 460, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
    });
  } else paint();
  $$('.dbp-burnup-itable th[aria-sort]').forEach(th => th.setAttribute('aria-sort', th.querySelector('button').dataset.sort === S.sort.k ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  sumPicked();
};
const sumPicked = () => {
  const s = sp(), pick = s.issues.filter(i => S.picked.has(i.key));
  $('[data-selsum]').textContent = pick.length ? `${pick.length} selected · ${pick.reduce((a, i) => a + i.pts, 0)} pts` : 'Select rows to total them';
};
statusBox.addEventListener('click', e => {
  const b = e.target.closest('[data-s]'); if (!b) return;
  const k = b.dataset.s;
  if (S.statuses.has(k)) S.statuses.delete(k); else S.statuses.add(k);
  renderIssues(true);
  const nb = statusBox.querySelector(`[data-s="${k}"]`); if (nb) nb.focus();
});
$('.dbp-burnup-itable thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  S.sort = { k, dir: S.sort.k === k ? -S.sort.dir : (k === 'pts' ? -1 : 1) };
  renderIssues(true);
});
const togglePick = tr => {
  const k = tr.dataset.key; if (!k) return;
  if (S.picked.has(k)) S.picked.delete(k); else S.picked.add(k);
  tr.setAttribute('aria-selected', String(S.picked.has(k)));
