};
tbody.addEventListener('click', e => { const tr = e.target.closest('tr[data-key]'); if (!tr) return; $$('tr', tbody).forEach(r => { r.tabIndex = r === tr ? 0 : -1; }); togglePick(tr); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr[data-key]'); if (!tr) return;
  const move = n => { if (!n || !n.dataset.key) return; tr.tabIndex = -1; n.tabIndex = 0; n.focus(); };
