    fc.innerHTML = spill > 0
      ? `At ${c.rate.toFixed(1)} ${u}/day the team lands <b>${land} of ${c.final} ${u}</b> by ${fmtD(last)}; <b data-bad>${spill} ${u}</b> would spill into S${s.n + 1}.`
      : `At ${c.rate.toFixed(1)} ${u}/day the team finishes all <b>${c.final} ${u}</b> before ${fmtD(last)}.`;
  } else {
    const pct = c.final ? Math.round(c.completed / c.final * 100) : 0;
    fc.innerHTML = `Closed <b>${c.completed} of ${c.final} ${u}</b> (${pct}%). ${c.remaining ? `<b data-bad>${c.remaining} ${u}</b> spilled into S${s.n + 1}; ` : ''}scope moved <b>${c.added - c.removed >= 0 ? '+' : '−'}${Math.abs(c.added - c.removed)} ${u}</b> after commitment.`;
  }
  plot.setAttribute('aria-label', `${up ? 'Burnup' : 'Burndown'} chart for sprint ${s.n}. ${fc.textContent} Use left and right arrow keys to read each day.`);
};
$('[data-team]').innerHTML = PEOPLE.map(([n, h]) => `<span style="--h:${h}" title="${n}">${n.split(' ').map(w => w[0]).join('')}</span>`).join('');

const refresh = () => { S.pin = null; S.hover = null; renderChrome(); renderEvents(); renderLedger(); renderIssues(false); go(); };

/* segmented controls with roving focus and arrow keys */
const seg = (name, fn) => {
  const g = $(`[data-group="${name}"]`), bs = $$('[role="radio"]', g);
  const sync = () => bs.forEach(b => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
  const pick = (b, focus) => { bs.forEach(x => x.setAttribute('aria-checked', String(x === b))); sync(); if (focus) b.focus(); fn(b.dataset.v); };
  g.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  g.addEventListener('keydown', e => {
    const dir = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key]; if (!dir) return;
    e.preventDefault();
    const i = bs.findIndex(b => b.getAttribute('aria-checked') === 'true');
    pick(bs[(i + dir + bs.length) % bs.length], true);
  });
  sync();
};
seg('sprint', v => { S.sp = +v; S.picked.clear(); S.statuses = null; S.reasons = new Set(Object.keys(REASON)); refresh(); });
seg('mode', v => { S.mode = v; renderChrome(); go(); });
seg('unit', v => { S.unit = v; S.pin = null; renderChrome(); renderEvents(); renderLedger(); go(); });

/* views */
const navs = $$('.dbp-burnup-navbtn');
const setView = v => {
  S.view = v;
  navs.forEach(b => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dbp-burnup-view').forEach(sec => { sec.hidden = sec.dataset.view !== v; });
  $('.dbp-burnup-main').scrollTop = 0;
};
navs.forEach(b => b.addEventListener('click', () => setView(b.dataset.view)));
$('.dbp-burnup-nav').addEventListener('keydown', e => {
  const dir = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!dir) return;
  const i = navs.indexOf(document.activeElement); if (i < 0) return;
  e.preventDefault(); const n = navs[(i + dir + navs.length) % navs.length]; n.focus(); setView(n.dataset.view);
});

/* redraw on resize */
let lastWH = '';
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const k = plot.clientWidth + 'x' + plot.clientHeight;
  if (k !== lastWH && cur) { lastWH = k; draw(cur); }
});
ro.observe(plot);

refresh();
lastWH = plot.clientWidth + 'x' + plot.clientHeight;
setTimeout(() => root.setAttribute('data-ready', ''), reduce ? 0 : 1800);

