@keyframes dbp-roadmap-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-roadmap-grow { from { clip-path: inset(0 100% 0 0 round 6px); } to { clip-path: inset(0 0 0 0 round 6px); } }
@keyframes dbp-roadmap-fade { from { opacity: 0; } }
@keyframes dbp-roadmap-ping { from { opacity: 0.9; transform: scale(0.6); } to { opacity: 0; transform: scale(2.2); } }

.dbp-roadmap {
  /* re-theme with these four */
  --dbp-roadmap-paper: oklch(0.982 0.007 85);
  --dbp-roadmap-ink: oklch(0.27 0.025 255);
  --dbp-roadmap-accent: oklch(0.6 0.19 33);
  --dbp-roadmap-brand: oklch(0.45 0.09 160);
  /* derived */
  --dbp-roadmap-card: color-mix(in oklch, var(--dbp-roadmap-paper), white 65%);
  --dbp-roadmap-sunk: color-mix(in oklch, var(--dbp-roadmap-paper), var(--dbp-roadmap-ink) 4%);
  --dbp-roadmap-line: color-mix(in oklch, var(--dbp-roadmap-ink) 10%, transparent);
  --dbp-roadmap-line-2: color-mix(in oklch, var(--dbp-roadmap-ink) 19%, transparent);
  --dbp-roadmap-muted: color-mix(in oklch, var(--dbp-roadmap-ink) 62%, var(--dbp-roadmap-paper));
  --dbp-roadmap-faint: color-mix(in oklch, var(--dbp-roadmap-ink) 40%, var(--dbp-roadmap-paper));
  --dbp-roadmap-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-roadmap-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-roadmap-mono: ui-monospace, Menlo, monospace;
  --dbp-roadmap-rh: 34px;
  --dbp-roadmap-lw: 280px;

  width: 100%;
  height: var(--dbp-roadmap-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-roadmap-paper);
  color: var(--dbp-roadmap-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-roadmap-brand);
  box-shadow: inset 0 0 0 1px var(--dbp-roadmap-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-roadmap-brand); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-roadmap-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-roadmap-muted); }
  .dbp-roadmap-num { text-align: right; }

  .dbp-roadmap-app { display: grid; height: 100%; grid-template-columns: 188px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-roadmap-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; border-right: 1px solid var(--dbp-roadmap-line); background: var(--dbp-roadmap-sunk); }
  .dbp-roadmap-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-roadmap-brand svg { width: 30px; height: 30px; padding: 5px; flex: none; border-radius: 8px; background: var(--dbp-roadmap-ink); fill: none; stroke: var(--dbp-roadmap-paper); stroke-width: 1.8; stroke-linecap: round; }
  .dbp-roadmap-brand span { display: grid; line-height: 1.2; }
  .dbp-roadmap-brand b { font-weight: 720; letter-spacing: -0.015em; }
  .dbp-roadmap-brand small { font-size: 11px; color: var(--dbp-roadmap-muted); }
  .dbp-roadmap-nav { display: grid; gap: 2px; }
  .dbp-roadmap-navbtn { position: relative; width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-roadmap-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-roadmap-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-roadmap-navbtn:hover { color: var(--dbp-roadmap-ink); background: var(--dbp-roadmap-line); }
  .dbp-roadmap-navbtn[aria-current="page"] { color: var(--dbp-roadmap-ink); background: var(--dbp-roadmap-card); box-shadow: 0 0 0 1px var(--dbp-roadmap-line), 0 1px 2px var(--dbp-roadmap-line); }
  .dbp-roadmap-navbtn[aria-current="page"] svg { color: var(--dbp-roadmap-brand); }
  .dbp-roadmap-badge { margin-left: auto; min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; border-radius: 99px; font: 650 10.5px var(--dbp-roadmap-mono); font-style: normal; color: var(--dbp-roadmap-paper); background: var(--dbp-roadmap-accent); animation: dbp-roadmap-fade 300ms both; }
  .dbp-roadmap-health { margin-top: auto; display: grid; gap: 6px; padding: 14px 10px; border-radius: 12px; background: var(--dbp-roadmap-card); box-shadow: 0 0 0 1px var(--dbp-roadmap-line); }
  .dbp-roadmap-health b { font: 680 26px/1 system-ui, sans-serif; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; color: var(--dbp-roadmap-brand); }
  .dbp-roadmap-health b small { font-size: 12px; font-weight: 550; letter-spacing: 0; color: var(--dbp-roadmap-muted); margin-left: 4px; }
  .dbp-roadmap-health[data-late] b { color: var(--dbp-roadmap-accent); }
  .dbp-roadmap-health small { font-size: 11.5px; line-height: 1.35; color: var(--dbp-roadmap-muted); }
  .dbp-roadmap-buf { height: 6px; border-radius: 99px; background: var(--dbp-roadmap-line); overflow: hidden; }
  .dbp-roadmap-buf i { display: block; height: 100%; width: 100%; border-radius: inherit; background: var(--dbp-roadmap-brand); transform-origin: left; transform: scaleX(var(--f, 0)); transition: transform 600ms var(--dbp-roadmap-spring), background-color 300ms; }
  .dbp-roadmap-health[data-late] .dbp-roadmap-buf i { background: var(--dbp-roadmap-accent); }

  /* ---------- top ---------- */
  .dbp-roadmap-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; }
  .dbp-roadmap-title { display: grid; gap: 3px; }
  .dbp-roadmap-h { font-size: clamp(19px, 0.95rem + 0.9cqi, 27px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; }
  .dbp-roadmap-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; }
  .dbp-roadmap-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbp-roadmap-sunk); box-shadow: inset 0 0 0 1px var(--dbp-roadmap-line); }
  .dbp-roadmap-seg button { height: 26px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbp-roadmap-muted); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbp-roadmap-seg button:hover { color: var(--dbp-roadmap-ink); }
  .dbp-roadmap-seg button[aria-checked="true"] { color: var(--dbp-roadmap-ink); background: var(--dbp-roadmap-card); box-shadow: 0 1px 2px var(--dbp-roadmap-line-2), 0 0 0 1px var(--dbp-roadmap-line); }
  .dbp-roadmap-switch { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; color: var(--dbp-roadmap-muted); cursor: pointer; }
  .dbp-roadmap-switch input { appearance: none; margin: 0; width: 30px; height: 18px; border-radius: 99px; background: var(--dbp-roadmap-line-2); position: relative; cursor: pointer; transition: background-color 200ms; }
  .dbp-roadmap-switch input::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px var(--dbp-roadmap-line-2); transition: translate 260ms var(--dbp-roadmap-spring); }
  .dbp-roadmap-switch input:checked { background: var(--dbp-roadmap-accent); }
  .dbp-roadmap-switch input:checked::after { translate: 12px 0; }
  .dbp-roadmap-switch:has(input:checked) { color: var(--dbp-roadmap-ink); }

  /* ---------- main ---------- */
  .dbp-roadmap-main { grid-area: main; min-height: 0; overflow: auto; padding: 0 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dbp-roadmap-line-2) transparent; }
  .dbp-roadmap-view { min-height: 100%; }
  .dbp-roadmap-view > * { animation: dbp-roadmap-rise 480ms var(--dbp-roadmap-ease) both; animation-delay: calc(var(--i, 0) * 70ms); }
  .dbp-roadmap-vtime { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; }
  .dbp-roadmap-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbp-roadmap-card); box-shadow: 0 0 0 1px var(--dbp-roadmap-line), 0 1px 3px var(--dbp-roadmap-line); overflow: hidden; }
  .dbp-roadmap-gpanel { --i: 1; }
  .dbp-roadmap-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 12px 16px 8px; }
  .dbp-roadmap-ph h3 { font-size: 13.5px; font-weight: 680; margin-right: auto; }
  .dbp-roadmap-btn { height: 28px; padding: 0 11px; display: inline-flex; align-items: center; gap: 6px; border-radius: 8px; font-size: 12px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--dbp-roadmap-line-2); transition: background-color 150ms, opacity 150ms, transform 250ms var(--dbp-roadmap-spring); }
  .dbp-roadmap-btn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-roadmap-btn:hover:not(:disabled) { background: var(--dbp-roadmap-sunk); }
  .dbp-roadmap-btn:active:not(:disabled) { transform: scale(0.95); }
  .dbp-roadmap-btn:disabled { opacity: 0.4; cursor: default; }

  /* ---------- stats ---------- */
  .dbp-roadmap-stats { --i: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  .dbp-roadmap-stat { display: grid; gap: 1px; padding: 10px 14px; border-radius: 12px; background: var(--dbp-roadmap-card); box-shadow: 0 0 0 1px var(--dbp-roadmap-line); min-width: 0; }
  .dbp-roadmap-stat span { font-size: 11px; color: var(--dbp-roadmap-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbp-roadmap-stat b { font: 700 clamp(17px, 0.8rem + 0.8cqi, 22px)/1.15 system-ui, sans-serif; letter-spacing: -0.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbp-roadmap-stat b[data-late] { color: var(--dbp-roadmap-accent); }
  .dbp-roadmap-stat small { font-size: 11.5px; color: var(--dbp-roadmap-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbp-roadmap-stat small[data-late] { color: var(--dbp-roadmap-accent); font-weight: 600; }

  /* ---------- toolbar ---------- */
  .dbp-roadmap-bar-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 10px 12px; border-bottom: 1px solid var(--dbp-roadmap-line); }
  .dbp-roadmap-chips { display: flex; flex-wrap: wrap; gap: 5px; }
  .dbp-roadmap-chip { height: 26px; padding: 0 10px 0 8px; display: inline-flex; align-items: center; gap: 6px; border-radius: 99px; font-size: 12px; font-weight: 580; color: var(--dbp-roadmap-faint); box-shadow: inset 0 0 0 1px var(--dbp-roadmap-line-2); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbp-roadmap-chip i { width: 9px; height: 9px; border-radius: 3px; background: oklch(0.86 0.04 var(--h)); box-shadow: inset 0 0 0 1.5px oklch(0.62 0.1 var(--h)); transition: background-color 150ms; }
  .dbp-roadmap-chip[aria-pressed="true"] { color: var(--dbp-roadmap-ink); background: oklch(0.95 0.025 var(--h)); box-shadow: inset 0 0 0 1px oklch(0.8 0.07 var(--h)); }
  .dbp-roadmap-chip[aria-pressed="true"] i { background: oklch(0.62 0.1 var(--h)); }
  .dbp-roadmap-hint { margin-left: auto; font-size: 11.5px; color: var(--dbp-roadmap-faint); }

  /* ---------- gantt ---------- */
  .dbp-roadmap-scroll { position: relative; flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbp-roadmap-line-2) transparent; }
  .dbp-roadmap-gantt { display: grid; grid-template-columns: var(--dbp-roadmap-lw) max-content; grid-template-rows: 46px auto; min-width: 100%; width: max-content; }
  .dbp-roadmap-corner { position: sticky; left: 0; top: 0; z-index: 5; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 12px 8px 14px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbp-roadmap-faint); background: var(--dbp-roadmap-card); border-bottom: 1px solid var(--dbp-roadmap-line-2); border-right: 1px solid var(--dbp-roadmap-line-2); }
  .dbp-roadmap-scale { position: sticky; top: 0; z-index: 4; height: 46px; background: var(--dbp-roadmap-card); border-bottom: 1px solid var(--dbp-roadmap-line-2); font: 10.5px var(--dbp-roadmap-mono); color: var(--dbp-roadmap-faint); }
  .dbp-roadmap-scale span { position: absolute; white-space: nowrap; font-variant-numeric: tabular-nums; }
  .dbp-roadmap-scale .dbp-roadmap-mon { top: 7px; font: 680 11px system-ui, sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbp-roadmap-ink); padding-left: 6px; border-left: 1px solid var(--dbp-roadmap-line-2); height: 39px; }
  .dbp-roadmap-scale .dbp-roadmap-wk { bottom: 7px; translate: -50% 0; }
  .dbp-roadmap-scale .dbp-roadmap-tag { bottom: 4px; translate: -50% 0; padding: 1px 6px; border-radius: 4px; font: 700 9.5px system-ui, sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: white; background: var(--dbp-roadmap-ink); z-index: 1; }
  .dbp-roadmap-scale .dbp-roadmap-tag[data-k="target"] { background: var(--dbp-roadmap-brand); }
  .dbp-roadmap-scale .dbp-roadmap-tag[data-k="target"][data-late] { background: var(--dbp-roadmap-accent); }

  .dbp-roadmap-list { position: sticky; left: 0; z-index: 3; background: var(--dbp-roadmap-card); border-right: 1px solid var(--dbp-roadmap-line-2); }
  .dbp-roadmap-row { position: relative; height: var(--dbp-roadmap-rh); display: grid; grid-template-columns: minmax(0, 1fr) 26px 34px; align-items: center; gap: 8px; padding: 0 12px 0 calc(14px + var(--lvl, 0) * 16px); border-bottom: 1px solid var(--dbp-roadmap-line); cursor: pointer; outline: none; transition: background-color 120ms; }
  .dbp-roadmap-row:hover, .dbp-roadmap-row[data-hot] { background: var(--dbp-roadmap-sunk); }
  .dbp-roadmap-row[aria-selected="true"] { background: color-mix(in oklch, var(--dbp-roadmap-brand) 10%, var(--dbp-roadmap-card)); box-shadow: inset 3px 0 0 var(--dbp-roadmap-brand); }
  .dbp-roadmap-row:focus-visible { box-shadow: inset 0 0 0 2px var(--dbp-roadmap-brand); }
  .dbp-roadmap-row[data-group] { font-weight: 680; background: var(--dbp-roadmap-sunk); }
  .dbp-roadmap-rn { display: flex; align-items: center; gap: 7px; min-width: 0; }
  .dbp-roadmap-rn span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbp-roadmap-rn svg { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: rotate 260ms var(--dbp-roadmap-spring); }
  .dbp-roadmap-row[aria-expanded="false"] .dbp-roadmap-rn svg { rotate: -90deg; }
  .dbp-roadmap-dot { width: 8px; height: 8px; flex: none; border-radius: 3px; background: oklch(0.62 0.1 var(--h)); }
  .dbp-roadmap-row[data-ms] .dbp-roadmap-dot { rotate: 45deg; border-radius: 1px; background: var(--dbp-roadmap-ink); }
  .dbp-roadmap-crit { width: 6px; height: 6px; flex: none; border-radius: 50%; background: var(--dbp-roadmap-accent); opacity: 0; transition: opacity 200ms; }
  &[data-crit] .dbp-roadmap-row[data-c] .dbp-roadmap-crit { opacity: 1; }
  .dbp-roadmap-av { width: 24px; height: 24px; display: grid; place-items: center; border-radius: 50%; font: 650 9.5px system-ui, sans-serif; color: oklch(0.32 0.07 var(--h)); background: oklch(0.92 0.045 var(--h)); }
  .dbp-roadmap-dur { font: 11px var(--dbp-roadmap-mono); color: var(--dbp-roadmap-muted); text-align: right; font-variant-numeric: tabular-nums; }

  .dbp-roadmap-canvas { position: relative; background-image: linear-gradient(to bottom, transparent calc(var(--dbp-roadmap-rh) - 1px), var(--dbp-roadmap-line) calc(var(--dbp-roadmap-rh) - 1px)); background-size: 100% var(--dbp-roadmap-rh); }
  .dbp-roadmap-gridline { position: absolute; top: 0; bottom: 0; width: 0; border-left: 1px solid var(--dbp-roadmap-line); }
  .dbp-roadmap-gridline[data-m] { border-left-color: var(--dbp-roadmap-line-2); }
  .dbp-roadmap-weekend { position: absolute; top: 0; bottom: 0; background: color-mix(in oklch, var(--dbp-roadmap-ink) 2.2%, transparent); }
  .dbp-roadmap-vline { position: absolute; top: 0; bottom: 0; width: 0; z-index: 2; pointer-events: none; }
  .dbp-roadmap-vline[data-k="today"] { border-left: 1.5px solid var(--dbp-roadmap-ink); }
  .dbp-roadmap-vline[data-k="target"] { border-left: 1.5px dashed var(--dbp-roadmap-brand); }
  .dbp-roadmap-vline[data-k="target"][data-late] { border-left-color: var(--dbp-roadmap-accent); }
  .dbp-roadmap-hl { position: absolute; left: 0; right: 0; height: var(--dbp-roadmap-rh); background: var(--dbp-roadmap-sunk); opacity: 0; pointer-events: none; transition: opacity 120ms; }
  .dbp-roadmap-hl[data-on] { opacity: 1; }
  .dbp-roadmap-hl[data-sel] { opacity: 1; background: color-mix(in oklch, var(--dbp-roadmap-brand) 8%, transparent); }
  .dbp-roadmap-links { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; z-index: 1; animation: dbp-roadmap-fade 700ms 650ms both; }
