const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const uid = 'dbp-roadmap-' + Math.random().toString(36).slice(2, 8);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

/* ---------- calendar ----------
   Day 0 is kickoff, Wed 16 Sep 2026. Durations are calendar days; a task occupies
   [es, ef). The visible range runs from Mon 14 Sep to Sun 6 Dec. */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const DAY0 = Date.UTC(2026, 8, 16), R0 = -2, R1 = 82, TODAY = 16, TARGET = 72;
const dt = d => new Date(DAY0 + d * 864e5);
const fd = d => `${MON[dt(d).getUTCMonth()]} ${dt(d).getUTCDate()}`;
const fdw = d => `${DOW[dt(d).getUTCDay()]} ${fd(d)}`;
const plural = (n, w) => `${n} ${w}${Math.abs(n) === 1 ? '' : 's'}`;

/* ---------- plan ---------- */
const TEAMS = { Platform: 255, Data: 195, Design: 330, Mobile: 150, Web: 70, QA: 290 };
const GROUPS = [['sync', 'Sync engine'], ['clients', 'Clients'], ['launch', 'Launch']];
const T = [
  ['spec', 'sync', 'CRDT sync protocol spec', 'Platform', 'Ana Ruiz', 12, [], 100],
  ['core', 'sync', 'Sync engine core', 'Platform', 'Jonas Ek', 26, ['spec'], 20],
  ['conflict', 'sync', 'Conflict resolution API', 'Platform', 'Ana Ruiz', 12, ['core'], 0],
  ['migrate', 'sync', 'Migrate 2.x local stores', 'Data', 'Hira Qureshi', 16, ['core'], 0],
  ['tokens', 'clients', 'Design system v3 tokens', 'Design', 'Léa Fontaine', 16, [], 100],
  ['ios', 'clients', 'iOS shell on new navigation', 'Mobile', 'Yuki Tanabe', 24, ['tokens'], 0],
  ['android', 'clients', 'Android shell on new navigation', 'Mobile', 'Marcus Bell', 27, ['tokens'], 0],
  ['web', 'clients', 'Web editor rewrite', 'Web', 'Oren Shalev', 34, ['tokens'], 0],
  ['offline', 'clients', 'Offline states and sync badges', 'Design', 'Pia Laurent', 9, ['conflict'], 0],
  ['wire', 'clients', 'Wire clients to the sync engine', 'Mobile', 'Yuki Tanabe', 14, ['core', 'ios', 'android'], 0],
  ['beta', 'launch', 'Private beta · 2,000 users', null, 'Grace Okoye', 0, ['wire', 'web', 'migrate'], 0],
  ['fixes', 'launch', 'Beta feedback fixes', 'Web', 'Oren Shalev', 10, ['beta'], 0],
  ['perf', 'launch', 'Performance budget pass', 'QA', 'Grace Okoye', 12, ['beta'], 0],
  ['a11y', 'launch', 'Accessibility audit', 'QA', 'Grace Okoye', 8, ['offline', 'web'], 0],
  ['store', 'launch', 'Store listings and review', 'Design', 'Léa Fontaine', 10, ['beta'], 0],
  ['launch', 'launch', 'Public launch', null, 'Maya Castell', 0, ['fixes', 'perf', 'a11y', 'store'], 0]
].map(([id, g, name, team, owner, dur, deps, prog]) => ({ id, g, name, team, owner, dur, deps, prog, ms: dur === 0, nnet: null, fixed: prog > 0 ? (id === 'core' ? 12 : 0) : null }));
const byId = {}; T.forEach(t => { byId[t.id] = t; });
const SUCC = {}; T.forEach(t => { SUCC[t.id] = []; }); T.forEach(t => t.deps.forEach(d => SUCC[d].push(t.id)));
const hue = t => t.team ? TEAMS[t.team] : 255;
const initials = n => n.split(' ').map(w => w[0]).join('');

/* forward pass for early dates, backward pass for late dates; slack = ls - es */
const minStart = t => Math.max(t.ms ? 0 : TODAY, ...t.deps.map(d => byId[d].ef));
const schedule = () => {
  T.forEach(t => {
    t.es = t.fixed != null ? t.fixed : Math.max(minStart(t), t.nnet ?? -Infinity);
    t.ef = t.es + t.dur;
  });
  const end = byId.launch.ef;
  for (let i = T.length - 1; i >= 0; i--) {
    const t = T[i];
    t.lf = SUCC[t.id].length ? Math.min(...SUCC[t.id].map(s => byId[s].ls)) : end;
    t.ls = t.lf - t.dur; t.slack = t.ls - t.es; t.crit = t.slack <= 0;
  }
};
schedule();
T.forEach(t => { t.bes = t.es; t.bef = t.ef; });
const snapshot = () => T.map(t => [t.nnet, t.dur]);
const BASE = snapshot();
const restore = snap => { T.forEach((t, i) => { t.nnet = snap[i][0]; t.dur = snap[i][1]; }); schedule(); };
const KEY = [['tokens', 'Design system v3 ready', 'ef'], ['core', 'Sync engine feature-complete', 'ef'], ['beta', 'Private beta opens', 'es'], ['launch', 'Public launch', 'es']];
const keyDay = ([id, , k], base) => { const t = byId[id]; return k === 'es' ? (base ? t.bes : t.es) : (base ? t.bef : t.ef) - 1; };

/* ---------- state ---------- */
const S = { view: 'timeline', zoom: 'fit', px: 8, crit: true, teams: new Set(Object.keys(TEAMS)), collapsed: new Set(), sel: null, hot: null, log: [] };
let R = [], rowOf = {};
const D = { px: null, t: {}, g: {} };
const RH = () => parseFloat(getComputedStyle(root).getPropertyValue('--dbp-roadmap-rh')) || 34;

const list = $('[data-list]'), canvas = $('[data-canvas]'), scale = $('[data-scale]'), scroller = $('[data-scroll]');
const bars = $('[data-bars]'), links = $('[data-links]'), hl = $('[data-hl]'), drawer = $('[data-drawer]');
bars.setAttribute('aria-hidden', 'true');
bars.innerHTML = T.map((t, i) => `<div class="dbp-roadmap-task" data-id="${t.id}" style="--h:${hue(t)};--i:${i};--p:${t.prog}"${t.ms ? ' data-ms' : ''}${t.prog >= 100 ? ' data-done data-locked' : ''}>${t.ms ? '<i></i>' : ''}<span>${esc(t.name)}</span>${!t.ms && t.prog < 100 ? '<b class="dbp-roadmap-grip"></b>' : ''}</div>`).join('') +
  GROUPS.map(([g]) => `<div class="dbp-roadmap-sum" data-g="${g}"><b></b></div>`).join('');
const barEl = {}; $$('.dbp-roadmap-task', bars).forEach(b => { barEl[b.dataset.id] = b; });
const sumEl = {}; $$('.dbp-roadmap-sum', bars).forEach(b => { sumEl[b.dataset.g] = b; });
links.innerHTML = `<defs>${['n', 'c', 'i', 'h'].map(k => `<marker id="${uid}-${k}" data-k="${k}" viewBox="0 0 8 8" refX="7.6" refY="4" markerWidth="7" markerHeight="7" markerUnits="userSpaceOnUse" orient="auto"><path d="M0 0.6L8 4L0 7.4z"/></marker>`).join('')}</defs><g data-paths></g>`;
const pathsG = $('[data-paths]', links);
const deco = document.createElement('div'); deco.setAttribute('aria-hidden', 'true'); canvas.prepend(deco);
const toast = document.createElement('div'); toast.className = 'dbp-roadmap-toast'; toast.setAttribute('role', 'status'); toast.hidden = true; $('.dbp-roadmap-gpanel').appendChild(toast);
let toastT = 0;
const say = msg => { toast.textContent = msg; toast.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { toast.hidden = true; }, 2600); };

/* ---------- rows ---------- */
const rows = () => {
  const out = [];
  GROUPS.forEach(([gid, name]) => {
    const kids = T.filter(t => t.g === gid && (t.ms || S.teams.has(t.team)));
    if (!kids.length) return;
    out.push({ kind: 'g', id: gid, name, kids });
    if (!S.collapsed.has(gid)) kids.forEach(t => out.push({ kind: 't', id: t.id, t }));
