  return out;
};
const buildList = (animate) => {
  const before = new Map($$('.dbp-roadmap-row', list).map(r => [r.dataset.id, r.getBoundingClientRect().top]));
  const focusId = list.contains(document.activeElement) ? document.activeElement.dataset.id : null;
  R = rows(); rowOf = {}; R.forEach((r, i) => { rowOf[r.id] = i; });
  list.innerHTML = R.map(r => r.kind === 'g'
    ? `<div class="dbp-roadmap-row" role="row" data-group data-id="${r.id}" aria-level="1" aria-expanded="${!S.collapsed.has(r.id)}" tabindex="-1"><div class="dbp-roadmap-rn" role="gridcell"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg><span>${r.name}</span></div><span role="gridcell"></span><span class="dbp-roadmap-dur" role="gridcell" data-dur></span></div>`
    : `<div class="dbp-roadmap-row" role="row" data-id="${r.id}" aria-level="2" style="--lvl:1;--h:${hue(r.t)}"${r.t.ms ? ' data-ms' : ''} aria-selected="${S.sel === r.id}" tabindex="-1"><div class="dbp-roadmap-rn" role="gridcell"><i class="dbp-roadmap-dot"></i><span>${esc(r.t.name)}</span><i class="dbp-roadmap-crit"></i></div><span role="gridcell"><span class="dbp-roadmap-av" title="${esc(r.t.owner)}">${initials(r.t.owner)}</span></span><span class="dbp-roadmap-dur" role="gridcell" data-dur></span></div>`).join('');
  const tab = (focusId && list.querySelector(`[data-id="${focusId}"]`)) || list.querySelector(`[data-id="${S.sel}"]`) || list.firstElementChild;
  if (tab) tab.tabIndex = 0;
  if (focusId && tab && tab.dataset.id === focusId) tab.focus({ preventScroll: true });
  canvas.style.height = R.length * RH() + 'px';
  if (animate && !reduce) {
    $$('.dbp-roadmap-row', list).forEach(r => {
      const b = before.get(r.dataset.id);
      if (b == null) { r.animate([{ opacity: 0, transform: 'translateY(-6px)' }, { opacity: 1, transform: 'none' }], { duration: 300, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' }); return; }
      const dy = b - r.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) r.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 340, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
    });
  }
