};
const updateRows = () => {
  $$('.dbp-roadmap-row', list).forEach(r => {
    const id = r.dataset.id;
    if (r.hasAttribute('data-group')) {
      const kids = T.filter(t => t.g === id && !t.ms);
      const s = Math.min(...T.filter(t => t.g === id).map(t => t.es)), e = Math.max(...T.filter(t => t.g === id).map(t => t.ef));
      r.querySelector('[data-dur]').textContent = kids.length ? `${e - s}d` : '';
      return;
    }
    const t = byId[id];
    r.toggleAttribute('data-c', t.crit);
    r.querySelector('[data-dur]').textContent = t.ms ? fd(t.es) : `${t.dur}d`;
    r.setAttribute('aria-label', `${t.name}, ${t.ms ? fdw(t.es) : `${fd(t.es)} to ${fd(t.ef - 1)}, ${plural(t.dur, 'day')}`}${t.crit ? ', critical' : `, ${plural(t.slack, 'day')} of slack`}`);
  });
  T.forEach(t => barEl[t.id].toggleAttribute('data-c', t.crit));
};

/* ---------- scale, gridlines, today and target ---------- */
const x = d => (d - R0) * D.px;
let decoKey = '';
const buildDeco = () => {
  const late = byId.launch.es > TARGET, key = D.px.toFixed(2) + late;
  if (key === decoKey) return;
  decoKey = key;
  const W = (R1 - R0) * D.px;
  canvas.style.width = W + 'px'; scale.style.width = W + 'px';
  let sc = '', g = '';
  for (let d = R0; d < R1; d++) {
    const day = dt(d), dow = day.getUTCDay(), f = Math.round(x(d) * 10) / 10;
    if (day.getUTCDate() === 1 || d === R0) sc += `<span class="dbp-roadmap-mon" style="left:${f}px">${MON[day.getUTCMonth()]}${day.getUTCMonth() === 8 ? ' 2026' : ''}</span>`;
    if (dow === 1) {
      g += `<i class="dbp-roadmap-gridline" style="left:${f}px"></i>`;
      const wk = Math.round((d - R0) / 7);
      if (D.px * 7 >= 30 || wk % 2 === 0) sc += `<span class="dbp-roadmap-wk" style="left:${Math.round((x(d) + D.px * 3.5) * 10) / 10}px">${day.getUTCDate()}</span>`;
    } else if (D.px >= 22) sc += `<span class="dbp-roadmap-wk" style="left:${Math.round((x(d) + D.px / 2) * 10) / 10}px;opacity:.55">${day.getUTCDate()}</span>`;
    if (day.getUTCDate() === 1) g += `<i class="dbp-roadmap-gridline" data-m style="left:${f}px"></i>`;
    if (dow === 6 && D.px >= 9) g += `<i class="dbp-roadmap-weekend" style="left:${f}px;width:${Math.round(D.px * 2 * 10) / 10}px"></i>`;
  }
  sc += `<span class="dbp-roadmap-tag" style="left:${x(TODAY)}px">Today</span><span class="dbp-roadmap-tag" data-k="target"${late ? ' data-late' : ''} style="left:${x(TARGET)}px">Target</span>`;
  g += `<i class="dbp-roadmap-vline" data-k="today" style="left:${x(TODAY)}px"></i><i class="dbp-roadmap-vline" data-k="target"${late ? ' data-late' : ''} style="left:${x(TARGET)}px"></i>`;
  scale.innerHTML = sc; deco.innerHTML = g;
};

/* ---------- paint from the displayed (springing) values ---------- */
const rounded = (p, r) => {
  let d = `M${p[0][0]},${p[0][1]}`;
  for (let i = 1; i < p.length - 1; i++) {
    const [x0, y0] = p[i - 1], [x1, y1] = p[i], [x2, y2] = p[i + 1];
    const l1 = Math.hypot(x1 - x0, y1 - y0), l2 = Math.hypot(x2 - x1, y2 - y1), rr = Math.min(r, l1 / 2, l2 / 2);
    if (rr < 0.5) { d += `L${x1},${y1}`; continue; }
    d += `L${x1 - (x1 - x0) / l1 * rr},${y1 - (y1 - y0) / l1 * rr}Q${x1},${y1} ${x1 + (x2 - x1) / l2 * rr},${y1 + (y2 - y1) / l2 * rr}`;
  }
  const l = p[p.length - 1];
  return d + `L${l[0]},${l[1]}`;
};
const paint = () => {
  buildDeco();
  const rh = RH(), r1 = v => Math.round(v * 10) / 10;
  T.forEach(t => {
    const el = barEl[t.id], d = D.t[t.id];
    if (rowOf[t.id] == null) { el.style.display = 'none'; d.vis = false; return; }
    el.style.display = '';
    const w = (d.e - d.s) * D.px;
    el.style.transform = `translate(${r1(t.ms ? x(d.s) - 7 : x(d.s))}px, ${r1(d.y + (rh - (t.ms ? 14 : 22)) / 2)}px)`;
    if (!t.ms) { el.style.width = Math.max(6, w) + 'px'; el.toggleAttribute('data-out', w < t.name.length * 6.3 + 24); }
    el.toggleAttribute('data-late', t.id === 'launch' && t.es > TARGET);
  });
  GROUPS.forEach(([g]) => {
    const el = sumEl[g], gr = D.g[g];
    if (rowOf[g] == null) { el.style.display = 'none'; return; }
    const kids = T.filter(t => t.g === g);
    const s = Math.min(...kids.map(t => D.t[t.id].s)), e = Math.max(...kids.map(t => D.t[t.id].e));
    const work = kids.filter(t => !t.ms), tot = work.reduce((a, t) => a + t.dur, 0);
    el.style.display = '';
    el.style.transform = `translate(${r1(x(s))}px, ${r1(gr.y + rh / 2 - 6)}px)`;
    el.style.width = Math.max(4, (e - s) * D.px) + 'px';
    el.style.setProperty('--p', tot ? work.reduce((a, t) => a + t.dur * t.prog, 0) / tot : 0);
  });
  let p = '';
  T.forEach(b => b.deps.forEach(aid => {
    const a = byId[aid];
    if (rowOf[a.id] == null || rowOf[b.id] == null) return;
    const da = D.t[a.id], db = D.t[b.id];
    const x1 = r1(a.ms ? x(da.s) + 7 : x(da.e)), y1 = r1(da.y + rh / 2), x2 = r1(b.ms ? x(db.s) - 7 : x(db.s)), y2 = r1(db.y + rh / 2);
    const down = y2 > y1, ym = r1(y2 + (down ? -rh / 2 : rh / 2));
    const pts = x2 - x1 >= 16 ? [[x1, y1], [x1 + 8, y1], [x1 + 8, y2], [x2 - 1, y2]] : [[x1, y1], [x1 + 8, y1], [x1 + 8, ym], [x2 - 12, ym], [x2 - 12, y2], [x2 - 1, y2]];
    const c = a.crit && b.crit && b.es === a.ef, hot = S.hot === a.id || S.hot === b.id || S.sel === a.id || S.sel === b.id;
    const mk = hot ? 'h' : S.crit && c ? 'c' : c ? 'i' : 'n';
    p += `<path class="dbp-roadmap-ln" d="${rounded(pts, 5)}"${c ? ' data-c' : ''}${hot ? ' data-hot' : ''} marker-end="url(#${uid}-${mk})"/>`;
  }));
  pathsG.innerHTML = p;
  const hr = S.hot != null ? rowOf[S.hot] : null, sr = S.sel != null ? rowOf[S.sel] : null;
  const rowY = id => (D.t[id] || D.g[id] || { y: 0 }).y;
  if (hr != null) { hl.style.transform = `translateY(${r1(rowY(S.hot))}px)`; hl.setAttribute('data-on', ''); hl.removeAttribute('data-sel'); }
  else if (sr != null) { hl.style.transform = `translateY(${r1(rowY(S.sel))}px)`; hl.setAttribute('data-sel', ''); hl.removeAttribute('data-on'); }
  else { hl.removeAttribute('data-on'); hl.removeAttribute('data-sel'); }
};

/* ---------- spring loop: runs only while something is still moving ---------- */
let raf = 0, last = 0, drag = null, anchor = null;
const targetPx = () => S.zoom === 'month' ? 15 : S.zoom === 'week' ? 30 : Math.max(5, (scroller.clientWidth - list.offsetWidth - 2) / (R1 - R0));
const tick = now => {
  if (!root.isConnected) return;
  const dts = Math.min(0.05, (now - last) / 1000 || 0.016); last = now;
  const a = reduce ? 1 : 1 - Math.exp(-dts * 15), rh = RH();
  let moving = false;
  const step = (cur, to) => { const n = cur + (to - cur) * a; if (Math.abs(to - n) > 0.004) { moving = true; return n; } return to; };
  const pxTo = S.px, oldPx = D.px;
  D.px = step(D.px, pxTo);
  T.forEach(t => {
    const d = D.t[t.id], live = drag && drag.moved && drag.t === t;
    const ts = live ? drag.liveS : t.es, te = live ? drag.liveE : t.ef, ty = (rowOf[t.id] ?? 0) * rh;
    if (live) { d.s = ts; d.e = te; } else { d.s = step(d.s, ts); d.e = step(d.e, te); }
    d.y = d.vis === false || reduce ? ty : step(d.y, ty);
    if (rowOf[t.id] != null) d.vis = true;
  });
  GROUPS.forEach(([g]) => { const gr = D.g[g], ty = (rowOf[g] ?? 0) * rh; gr.y = gr.vis === false ? ty : step(gr.y, ty); gr.vis = rowOf[g] != null; });
  if (anchor && oldPx !== D.px) scroller.scrollLeft = Math.max(0, x(anchor.day) - anchor.off);
  paint();
  raf = moving || (drag && drag.moved) ? requestAnimationFrame(tick) : 0;
  if (!raf) anchor = null;
};
const kick = () => { if (!raf) { last = performance.now(); raf = requestAnimationFrame(tick); } };

/* ---------- derived panels ---------- */
const renderStats = () => {
  const L = byId.launch, buf = TARGET - L.es, late = buf < 0;
  const crit = T.filter(t => t.crit && !t.ms), work = T.filter(t => !t.ms);
  const inflight = work.filter(t => t.es <= TODAY && TODAY < t.ef && t.prog < 100);
  const tot = work.reduce((a, t) => a + t.dur, 0), done = work.reduce((a, t) => a + t.dur * t.prog / 100, 0);
  $('[data-stats]').innerHTML = [
    ['Launch forecast', `<b${late ? ' data-late' : ''}>${fdw(L.es)}</b>`, `<small${late ? ' data-late' : ''}>${late ? `${plural(-buf, 'day')} past the ${fd(TARGET)} target` : `${plural(buf, 'day')} before the ${fd(TARGET)} target`}</small>`],
    ['Critical path', `<b>${crit.length} tasks</b>`, `<small>${L.es} days from kickoff to launch</small>`],
    ['In flight today', `<b>${inflight.length} of ${work.length}</b>`, `<small>tasks running on ${fd(TODAY)}</small>`],
    ['Planned work done', `<b>${Math.round(done / tot * 100)}%</b>`, `<small>${work.filter(t => t.prog >= 100).length} of ${work.length} tasks complete</small>`]
  ].map(([a, b, c]) => `<div class="dbp-roadmap-stat"><span>${a}</span>${b}${c}</div>`).join('');
  const h = $('[data-health]');
  h.toggleAttribute('data-late', late);
  $('[data-buffer]').innerHTML = `${late ? '−' : ''}${Math.abs(buf)}<small>${Math.abs(buf) === 1 ? 'day' : 'days'}${late ? ' late' : ''}</small>`;
  $('[data-bufbar]').style.setProperty('--f', late ? 1 : clamp(buf / 10, 0.04, 1));
  $('[data-bufnote]').textContent = late ? `Launch lands ${fd(L.es)}. Pull work off the critical path to recover.` : `Launch lands ${fd(L.es)} against a ${fd(TARGET)} target.`;
  const n = S.log.length, badge = $('[data-logcount]');
  badge.hidden = !n; badge.textContent = n;
  $('[data-undo]').disabled = !n;
};

const depBtn = (t, k) => `<button class="dbp-roadmap-dep" data-go="${t.id}"><i class="dbp-roadmap-dot" style="--h:${hue(t)}${t.ms ? ';rotate:45deg;border-radius:1px;background:var(--dbp-roadmap-ink)' : ''}"></i><span>${esc(t.name)}</span><small>${k === 'pred' ? (t.ms ? fd(t.es) : `ends ${fd(t.ef - 1)}`) : `starts ${fd(t.es)}`}</small></button>`;
const renderDrawer = () => {
  const t = byId[S.sel];
