      <div class="dbp-roadmap-meta">${t.team ? `<span class="dbp-roadmap-pill" style="--h:${hue(t)}">${t.team}</span>` : '<span class="dbp-roadmap-pill">Milestone</span>'}<span>${esc(t.owner)}</span>${t.crit ? '<span class="dbp-roadmap-pill" data-k="crit">Critical</span>' : `<span class="dbp-roadmap-pill" data-k="ok">${plural(t.slack, 'day')} slack</span>`}</div></div>
