      ${t.ms ? `<dt>Date</dt><dd>${fdw(t.es)}</dd>` : `<dt>Start</dt><dd>${fdw(t.es)}</dd><dt>Finish</dt><dd>${fdw(t.ef - 1)}</dd><dt>Duration</dt><dd>${plural(t.dur, 'day')}</dd>`}
