      <button class="dbp-roadmap-btn" data-size="-1" ${lockSize || t.dur <= 1 ? 'disabled' : ''}>Shorter</button><button class="dbp-roadmap-btn" data-size="1" ${lockSize ? 'disabled' : ''}>Longer</button></div>`}
    <div class="dbp-roadmap-dsec"><h5>Waits on</h5>${t.deps.length ? t.deps.map(d => depBtn(byId[d], 'pred')).join('') : '<span class="dbp-roadmap-none">Nothing — starts on its own.</span>'}</div>
    <div class="dbp-roadmap-dsec"><h5>Unblocks</h5>${SUCC[t.id].length ? SUCC[t.id].map(d => depBtn(byId[d], 'succ')).join('') : '<span class="dbp-roadmap-none">Nothing downstream.</span>'}</div>`;
  drawer.hidden = false;
};

const renderLog = () => {
  const ol = $('[data-log]');
  if (!S.log.length) { ol.innerHTML = '<li class="dbp-roadmap-empty">No changes yet. Drag a bar on the timeline, or use the arrow keys on a row, to reschedule work.</li>'; return; }
  ol.innerHTML = S.log.slice().reverse().map((e, i) => `<li class="dbp-roadmap-entry" style="--i:${i}"><svg viewBox="0 0 24 24" aria-hidden="true">${e.kind === 'size' ? '<path d="M4 12h16M8 8l-4 4 4 4M16 8l4 4-4 4"/>' : '<path d="M5 12h14M13 6l6 6-6 6"/>'}</svg><b>${esc(e.text)}</b>${i === 0 ? '<button class="dbp-roadmap-btn" data-undo-one>Undo</button>' : '<span></span>'}<small>${e.time} · launch <span class="dbp-roadmap-imp"${e.impact > 0 ? ' data-late' : e.impact < 0 ? ' data-early' : ''}>${e.impact === 0 ? 'unchanged' : `${fd(e.launch0)} → ${fd(e.launch1)} (${e.impact > 0 ? '+' : '−'}${plural(Math.abs(e.impact), 'day')})`}</span></small></li>`).join('');
};

/* milestones: baseline vs forecast dumbbells */
const dumb = $('[data-dumb]'), dsvg = $('[data-dsvg]'), dtip = $('.dbp-roadmap-tip', dumb);
let dRow = null;
const renderMilestones = () => {
  const W = dumb.clientWidth, H = dumb.clientHeight;
  if (!W) return;
  const l = Math.min(210, W * 0.38), r = 16, top = 26, rh = (H - top - 8) / KEY.length;
  const sx = d => l + (d - R0) / (R1 - R0) * (W - l - r);
  let s = '';
  for (let d = R0; d < R1; d++) { const day = dt(d); if (day.getUTCDate() === 1 || d === R0) s += `<line x1="${sx(d)}" x2="${sx(d)}" y1="${top - 6}" y2="${H}"/><text x="${sx(d) + 4}" y="${top - 12}">${MON[day.getUTCMonth()]}</text>`; }
  s += `<line class="dbp-roadmap-dt" x1="${sx(TARGET)}" x2="${sx(TARGET)}" y1="${top - 6}" y2="${H}"/><text x="${sx(TARGET) + 4}" y="${H - 4}" style="fill:var(--dbp-roadmap-brand)">target ${fd(TARGET)}</text>`;
  s += `<line x1="${sx(TODAY)}" x2="${sx(TODAY)}" y1="${top - 6}" y2="${H}" style="stroke:var(--dbp-roadmap-ink);stroke-width:1.5"/>`;
  KEY.forEach((k, i) => {
    const b = keyDay(k, true), f = keyDay(k, false), y = top + rh * i + rh / 2, v = f - b;
    s += `<g class="dbp-roadmap-drow" data-i="${i}"${dRow === i ? ' data-on' : ''}><rect x="0" y="${top + rh * i}" width="${W}" height="${rh}" rx="8"/>
