const refresh = () => { updateRows(); renderStats(); if (S.sel) renderDrawer(); renderLog(); if (S.view === 'milestones') renderMilestones(); kick(); };

/* ---------- edits ---------- */
const clock = () => { const n = new Date(); return `${String(n.getHours()).padStart(2, '0')}:${String(n.getMinutes()).padStart(2, '0')}`; };
const record = (t, kind, prev, snap, launch0, merge) => {
