    S.log.pop(); delta += lastE.delta; snap = lastE.snap; launch0 = lastE.launch0;
  }
  if (!delta) return;
  const launch1 = byId.launch.es;
  S.log.push({ id: t.id, kind, delta, at: Date.now(), time: clock(), snap, launch0, launch1, impact: launch1 - launch0,
