  if (launch1 !== launch0) { const m = barEl.launch; m.removeAttribute('data-ping'); void m.offsetWidth; m.setAttribute('data-ping', ''); }
};
const lockMsg = (t, resize) => t.ms ? `${t.name} is a milestone — it moves with the work it waits on.` : t.prog >= 100 ? `${t.name} is done and can't be rescheduled.` : (!resize && t.prog > 0) ? `${t.name} started ${fd(t.es)}; you can change its length but not its start.` : null;
