const shake = el => { if (reduce || !el) return; el.animate([{ translate: '0' }, { translate: '-5px' }, { translate: '4px' }, { translate: '-3px' }, { translate: '2px' }, { translate: '0' }], { duration: 380, easing: 'ease-out' }); };
$$('.dbp-roadmap-task', bars).forEach(el => el.addEventListener('animationend', e => { if (e.animationName.endsWith('ping')) el.removeAttribute('data-ping'); }));
const undo = () => { const e = S.log.pop(); if (!e) return; restore(e.snap); refresh(); say(`Undid: ${e.text}`); };
$('[data-undo]').addEventListener('click', undo);
$('[data-log]').addEventListener('click', e => { if (e.target.closest('[data-undo-one]')) undo(); });
