const setHot = id => { if (S.hot === id) return; S.hot = id; $$('.dbp-roadmap-row', list).forEach(r => r.toggleAttribute('data-hot', r.dataset.id === id)); T.forEach(t => barEl[t.id].toggleAttribute('data-hot', t.id === id)); kick(); };
list.addEventListener('pointerover', e => { const r = e.target.closest('.dbp-roadmap-row'); setHot(r ? r.dataset.id : null); });
