css:
@property --dbp-capacity-u { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbp-capacity-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-capacity-fade { from { opacity: 0; } }
@keyframes dbp-capacity-grow { from { transform: scaleY(0); } }
@keyframes dbp-capacity-flash { 0% { box-shadow: inset 0 0 0 2px var(--dbp-capacity-ink); } 100% { box-shadow: inset 0 0 0 2px transparent; } }

.dbp-capacity {
  /* re-theme with these four */
  --dbp-capacity-paper: oklch(0.985 0.004 250);
  --dbp-capacity-ink: oklch(0.26 0.02 265);
  --dbp-capacity-ok: oklch(0.79 0.1 165);
  --dbp-capacity-over: oklch(0.58 0.19 27);
  /* derived */
  --dbp-capacity-empty: color-mix(in oklch, var(--dbp-capacity-paper), oklch(0.93 0.03 95) 70%);
  --dbp-capacity-warn: color-mix(in oklch, var(--dbp-capacity-over), oklch(0.84 0.15 80) 72%);
  --dbp-capacity-accent: color-mix(in oklch, var(--dbp-capacity-ok), var(--dbp-capacity-ink) 52%);
  --dbp-capacity-card: color-mix(in oklch, var(--dbp-capacity-paper), white 70%);
  --dbp-capacity-sunk: color-mix(in oklch, var(--dbp-capacity-paper), var(--dbp-capacity-ink) 4%);
  --dbp-capacity-line: color-mix(in oklch, var(--dbp-capacity-ink) 9%, transparent);
  --dbp-capacity-line-2: color-mix(in oklch, var(--dbp-capacity-ink) 18%, transparent);
  --dbp-capacity-muted: color-mix(in oklch, var(--dbp-capacity-ink) 60%, var(--dbp-capacity-paper));
  --dbp-capacity-faint: color-mix(in oklch, var(--dbp-capacity-ink) 40%, var(--dbp-capacity-paper));
  --dbp-capacity-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-capacity-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-capacity-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-capacity-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-capacity-paper);
  color: var(--dbp-capacity-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-capacity-accent);
  box-shadow: inset 0 0 0 1px var(--dbp-capacity-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & select { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-capacity-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-capacity-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-capacity-muted); }

  .dbp-capacity-app { display: grid; height: 100%; grid-template-columns: 184px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-capacity-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; border-right: 1px solid var(--dbp-capacity-line); }
  .dbp-capacity-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-capacity-brand svg { width: 30px; height: 30px; padding: 6px; flex: none; border-radius: 8px; background: var(--dbp-capacity-accent); fill: color-mix(in oklch, var(--dbp-capacity-paper) 85%, transparent); stroke: none; }
  .dbp-capacity-brand span { display: grid; line-height: 1.2; }
  .dbp-capacity-brand b { font-weight: 720; letter-spacing: -0.015em; }
  .dbp-capacity-brand small { font-size: 11px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-nav { display: grid; gap: 2px; }
  .dbp-capacity-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-capacity-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-capacity-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-capacity-navbtn:hover { color: var(--dbp-capacity-ink); background: var(--dbp-capacity-sunk); }
  .dbp-capacity-navbtn[aria-current="page"] { color: var(--dbp-capacity-ink); background: color-mix(in oklch, var(--dbp-capacity-ok) 22%, var(--dbp-capacity-paper)); }
  .dbp-capacity-navbtn[aria-current="page"] svg { color: var(--dbp-capacity-accent); }
  .dbp-capacity-legend { margin-top: auto; display: grid; gap: 7px; padding: 14px 8px 0; border-top: 1px solid var(--dbp-capacity-line); }
  .dbp-capacity-ramp { height: 10px; border-radius: 3px; background: linear-gradient(90deg in oklch, var(--dbp-capacity-empty), var(--dbp-capacity-ok) 64%, var(--dbp-capacity-ok) 71.4%, var(--dbp-capacity-warn) 82.1%, var(--dbp-capacity-over)); box-shadow: inset 0 0 0 1px var(--dbp-capacity-line); }
  .dbp-capacity-ticks { position: relative; height: 12px; font: 10px var(--dbp-capacity-mono); color: var(--dbp-capacity-muted); }
  .dbp-capacity-ticks span { position: absolute; top: 0; }
  .dbp-capacity-ticks span:nth-child(1) { left: 0; }
  .dbp-capacity-ticks span:nth-child(2) { left: 35.7%; translate: -50% 0; }
  .dbp-capacity-ticks span:nth-child(3) { left: 71.4%; translate: -50% 0; }
  .dbp-capacity-ticks span:nth-child(4) { right: 0; }
  .dbp-capacity-pto { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dbp-capacity-muted); }
