  .dbp-capacity-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  .dbp-capacity-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbp-capacity-sunk); box-shadow: inset 0 0 0 1px var(--dbp-capacity-line); }
  .dbp-capacity-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbp-capacity-muted); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
