  .dbp-capacity-sort select { height: 32px; padding: 0 30px 0 10px; border: 0; border-radius: 9px; appearance: none; font-size: 12px; font-weight: 600; cursor: pointer; background: var(--dbp-capacity-card); box-shadow: inset 0 0 0 1px var(--dbp-capacity-line-2); }

  /* ---------- main ---------- */
  .dbp-capacity-main { grid-area: main; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 0 20px 18px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbp-capacity-line-2) transparent; }
