  .dbp-capacity-kpi span { grid-column: 1 / -1; font-size: 11px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-kpi b { font: 720 clamp(18px, 0.85rem + 0.8cqi, 23px)/1.15 system-ui, sans-serif; letter-spacing: -0.035em; font-variant-numeric: tabular-nums; }
  .dbp-capacity-kpi small { grid-column: 1 / -1; font-size: 11.5px; color: var(--dbp-capacity-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
