  .dbp-capacity-grid { display: grid; grid-template-columns: minmax(150px, 1.6fr) repeat(var(--n), minmax(40px, 1fr)) 52px; min-width: min-content; padding: 0 8px 10px; }
  .dbp-capacity-row { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; }
  .dbp-capacity-head { position: sticky; top: 0; z-index: 3; background: var(--dbp-capacity-card); padding-top: 6px; }
  .dbp-capacity-head > * { padding: 8px 0 7px; text-align: center; font: 600 10.5px/1.2 var(--dbp-capacity-mono); color: var(--dbp-capacity-faint); border-bottom: 1px solid var(--dbp-capacity-line-2); transition: color 150ms; }
