  .dbp-capacity-squad { grid-column: 1 / -1; display: flex; align-items: baseline; gap: 10px; padding: 14px 6px 5px; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
  .dbp-capacity-squad small { font: 500 11px var(--dbp-capacity-mono); letter-spacing: 0; text-transform: none; color: var(--dbp-capacity-muted); }
  .dbp-capacity-who { display: flex; align-items: center; gap: 9px; min-width: 0; padding: 0 8px 0 4px; height: 40px; border-radius: 8px 0 0 8px; transition: background-color 150ms; }
  .dbp-capacity-row:has([aria-selected="true"]) .dbp-capacity-who { background: color-mix(in oklch, var(--dbp-capacity-ok) 16%, transparent); }
  .dbp-capacity-av { width: 28px; height: 28px; flex: none; display: grid; place-items: center; border-radius: 50%; font: 650 10px system-ui, sans-serif; color: oklch(0.33 0.06 var(--h)); background: oklch(0.91 0.045 var(--h)); }
  .dbp-capacity-who span { display: grid; min-width: 0; line-height: 1.2; }
  .dbp-capacity-who b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbp-capacity-who small { font-size: 11px; color: var(--dbp-capacity-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbp-capacity-cell {
    --a: clamp(0%, calc(var(--dbp-capacity-u) * 111%), 100%);
    --b: clamp(0%, calc((var(--dbp-capacity-u) - 1) * 667%), 100%);
    --c: clamp(0%, calc((var(--dbp-capacity-u) - 1.15) * 400%), 100%);
    position: relative; height: 36px; margin: 2px; border-radius: 6px; display: grid; place-content: center;
    background: color-mix(in oklch, color-mix(in oklch, color-mix(in oklch, var(--dbp-capacity-empty), var(--dbp-capacity-ok) var(--a)), var(--dbp-capacity-warn) var(--b)), var(--dbp-capacity-over) var(--c));
    font: 600 11.5px var(--dbp-capacity-mono); font-variant-numeric: tabular-nums; color: color-mix(in oklch, var(--dbp-capacity-ink) 78%, transparent);
    cursor: pointer; outline: none;
    transition: --dbp-capacity-u 700ms var(--dbp-capacity-spring), transform 220ms var(--dbp-capacity-spring), box-shadow 150ms;
    transition-delay: calc(var(--d, 0) * 1ms), 0ms, 0ms;
    @starting-style { --dbp-capacity-u: 0; }
  }
  .dbp-capacity-cell small { font-size: 0.8em; opacity: 0.6; margin-left: 1px; }
  .dbp-capacity-cell[data-hot] { color: white; }
  .dbp-capacity-cell:hover { transform: scale(1.06); z-index: 1; box-shadow: 0 6px 14px -6px color-mix(in oklch, var(--dbp-capacity-ink) 45%, transparent); }
  .dbp-capacity-cell:focus-visible { box-shadow: inset 0 0 0 2px var(--dbp-capacity-ink); }
  .dbp-capacity-cell[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dbp-capacity-card), 0 0 0 4px var(--dbp-capacity-ink); z-index: 1; }
  .dbp-capacity-cell[data-pto] { background: repeating-linear-gradient(135deg, var(--dbp-capacity-line-2) 0 1.5px, transparent 1.5px 6px), var(--dbp-capacity-sunk); color: var(--dbp-capacity-faint); font: 650 9.5px system-ui, sans-serif; letter-spacing: 0.08em; }
  .dbp-capacity-cell[data-part]::after { content: ""; position: absolute; top: 4px; right: 4px; width: 5px; height: 5px; border-radius: 50%; background: var(--dbp-capacity-ink); opacity: 0.45; }
  .dbp-capacity-cell[data-flash] { animation: dbp-capacity-flash 900ms ease-out; }
  .dbp-capacity-peak { justify-self: end; padding-right: 4px; font: 650 11.5px var(--dbp-capacity-mono); font-variant-numeric: tabular-nums; }
  .dbp-capacity-peak[data-over] { color: var(--dbp-capacity-over); }
  .dbp-capacity-foot > * { padding: 10px 0 2px; text-align: center; font: 600 11px var(--dbp-capacity-mono); color: var(--dbp-capacity-muted); border-top: 1px solid var(--dbp-capacity-line-2); margin-top: 6px; }
  .dbp-capacity-foot > *:first-child { text-align: left; padding-left: 6px; font: 650 10.5px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; }
  .dbp-capacity-foot i { display: block; height: 4px; margin: 5px 6px 0; border-radius: 2px; background: var(--dbp-capacity-line); overflow: hidden; }
  .dbp-capacity-foot i::before { content: ""; display: block; height: 100%; width: calc(min(var(--f), 1) * 100%); background: var(--dbp-capacity-accent); border-radius: inherit; transition: width 500ms var(--dbp-capacity-ease); }
  .dbp-capacity-foot i[data-over]::before { background: var(--dbp-capacity-over); }

  .dbp-capacity-tip { position: absolute; z-index: 6; left: 0; top: 0; width: 220px; padding: 10px 12px; border-radius: 10px; pointer-events: none; background: var(--dbp-capacity-ink); color: var(--dbp-capacity-paper); font-size: 12px; box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--dbp-capacity-ink) 70%, transparent); transition: opacity 120ms, translate 200ms var(--dbp-capacity-ease); @starting-style { opacity: 0; translate: 0 4px; } }
  .dbp-capacity-tip h4 { font-size: 12px; font-weight: 650; margin-bottom: 6px; }
  .dbp-capacity-tip h4 small { font-weight: 500; opacity: 0.7; }
  .dbp-capacity-tip ul { display: grid; gap: 3px; }
  .dbp-capacity-tip li { display: grid; grid-template-columns: 9px 1fr auto; gap: 7px; align-items: center; }
  .dbp-capacity-tip li i { width: 9px; height: 9px; border-radius: 2px; background: oklch(0.72 0.11 var(--h)); }
  .dbp-capacity-tip li b { font: 600 11.5px var(--dbp-capacity-mono); }
  .dbp-capacity-tip p { margin-top: 7px; padding-top: 7px; border-top: 1px solid color-mix(in oklch, var(--dbp-capacity-paper) 18%, transparent); display: flex; justify-content: space-between; font-variant-numeric: tabular-nums; }

  /* ---------- detail ---------- */
  .dbp-capacity-dbody { display: grid; gap: 14px; padding: 16px; }
  .dbp-capacity-dh { display: flex; align-items: center; gap: 10px; }
