  .dbp-capacity-dh small { font-size: 12px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-x { margin-left: auto; width: 28px; height: 28px; flex: none; display: grid; place-items: center; border-radius: 8px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-x:hover { background: var(--dbp-capacity-sunk); color: var(--dbp-capacity-ink); }
  .dbp-capacity-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dbp-capacity-big { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
  .dbp-capacity-big b { font: 740 30px/1 system-ui, sans-serif; letter-spacing: -0.045em; font-variant-numeric: tabular-nums; }
  .dbp-capacity-big span { font-size: 12.5px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-big em { margin-left: auto; padding: 2px 8px; border-radius: 99px; font: 650 11.5px var(--dbp-capacity-mono); font-style: normal; color: var(--dbp-capacity-accent); background: color-mix(in oklch, var(--dbp-capacity-ok) 25%, transparent); }
  .dbp-capacity-big em[data-over] { color: white; background: var(--dbp-capacity-over); }
  .dbp-capacity-big em[data-low] { color: var(--dbp-capacity-muted); background: var(--dbp-capacity-sunk); }
  .dbp-capacity-stack { position: relative; display: flex; height: 14px; border-radius: 4px; background: var(--dbp-capacity-sunk); }
  .dbp-capacity-stack i { flex: var(--g) 1 0; min-width: 0; background: oklch(0.72 0.11 var(--h)); transition: flex-grow 500ms var(--dbp-capacity-ease); }
  .dbp-capacity-stack i:first-child { border-radius: 4px 0 0 4px; }
  .dbp-capacity-stack i:last-of-type { border-radius: 0 4px 4px 0; }
  .dbp-capacity-stack i + i { box-shadow: inset 1.5px 0 0 var(--dbp-capacity-card); }
  .dbp-capacity-stack u { position: absolute; top: -4px; bottom: -4px; left: var(--x); width: 2px; margin-left: -1px; border-radius: 1px; background: var(--dbp-capacity-ink); transition: left 500ms var(--dbp-capacity-ease); }
  .dbp-capacity-stack u::after { content: attr(data-l); position: absolute; top: -16px; left: 50%; translate: -50% 0; font: 600 10px var(--dbp-capacity-mono); color: var(--dbp-capacity-muted); white-space: nowrap; }
  .dbp-capacity-asg { display: grid; gap: 6px; }
  .dbp-capacity-asg h5, .dbp-capacity-hot h5 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbp-capacity-faint); }
  .dbp-capacity-item { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; gap: 2px 9px; align-items: center; padding: 8px 10px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dbp-capacity-line); }
  .dbp-capacity-item > i { width: 10px; height: 10px; border-radius: 3px; background: oklch(0.72 0.11 var(--h)); }
  .dbp-capacity-item b { font-weight: 600; font-size: 12.5px; }
  .dbp-capacity-item small { grid-column: 2; font-size: 11.5px; color: var(--dbp-capacity-muted); font-variant-numeric: tabular-nums; }
  .dbp-capacity-item > span { font: 650 12px var(--dbp-capacity-mono); font-variant-numeric: tabular-nums; }
  .dbp-capacity-move { grid-column: 3; grid-row: 2; justify-self: end; font-size: 11.5px; font-weight: 650; color: var(--dbp-capacity-accent); padding: 2px 4px; border-radius: 5px; }
  .dbp-capacity-move:hover { background: color-mix(in oklch, var(--dbp-capacity-ok) 20%, transparent); }
  .dbp-capacity-item:has(.dbp-capacity-form) { box-shadow: inset 0 0 0 1.5px var(--dbp-capacity-accent); }
  .dbp-capacity-form { grid-column: 1 / -1; display: grid; gap: 8px; margin-top: 6px; padding-top: 8px; border-top: 1px dashed var(--dbp-capacity-line-2); }
  .dbp-capacity-form label { display: grid; gap: 4px; font-size: 11px; font-weight: 600; color: var(--dbp-capacity-muted); }
  .dbp-capacity-form select { height: 30px; padding: 0 8px; border-radius: 7px; border: 0; background: var(--dbp-capacity-sunk); box-shadow: inset 0 0 0 1px var(--dbp-capacity-line-2); font-size: 12px; }
  .dbp-capacity-range { display: flex; align-items: center; gap: 8px; }
  .dbp-capacity-range input { flex: 1; min-width: 0; margin: 0; }
  .dbp-capacity-range output { font: 600 11.5px var(--dbp-capacity-mono); color: var(--dbp-capacity-ink); white-space: nowrap; font-variant-numeric: tabular-nums; }
  .dbp-capacity-form fieldset { border: 0; margin: 0; padding: 0; display: flex; gap: 12px; font-size: 12px; }
  .dbp-capacity-form fieldset label { display: inline-flex; flex-direction: row; align-items: center; gap: 5px; font-weight: 500; color: var(--dbp-capacity-ink); }
  .dbp-capacity-form p { font-size: 11.5px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-acts { display: flex; gap: 6px; }
  .dbp-capacity-btn { height: 30px; padding: 0 12px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbp-capacity-line-2); transition: background-color 150ms, transform 220ms var(--dbp-capacity-spring); }
  .dbp-capacity-btn:hover { background: var(--dbp-capacity-sunk); }
  .dbp-capacity-btn:active { transform: scale(0.95); }
  .dbp-capacity-btn[data-primary] { color: white; background: var(--dbp-capacity-accent); box-shadow: none; }
  .dbp-capacity-btn[data-primary]:hover { background: color-mix(in oklch, var(--dbp-capacity-accent), black 12%); }
  .dbp-capacity-hot { display: grid; gap: 6px; }
  .dbp-capacity-hotbtn { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 0 10px; align-items: center; padding: 7px 8px; border-radius: 9px; text-align: left; transition: background-color 150ms; }
  .dbp-capacity-hotbtn:hover { background: var(--dbp-capacity-sunk); }
  .dbp-capacity-hotbtn span { display: grid; line-height: 1.25; min-width: 0; }
  .dbp-capacity-hotbtn small { font-size: 11.5px; color: var(--dbp-capacity-muted); text-wrap: pretty; }
  .dbp-capacity-hotbtn em { font: 650 12px var(--dbp-capacity-mono); font-style: normal; color: var(--dbp-capacity-over); }
  .dbp-capacity-note { font-size: 12.5px; color: var(--dbp-capacity-muted); line-height: 1.5; }
  .dbp-capacity-undo { justify-self: start; }
  .dbp-capacity-log { display: grid; gap: 4px; font-size: 11.5px; color: var(--dbp-capacity-muted); }
  .dbp-capacity-log li { padding-left: 12px; position: relative; animation: dbp-capacity-rise 380ms var(--dbp-capacity-ease) both; }
  .dbp-capacity-log li::before { content: ""; position: absolute; left: 0; top: 7px; width: 5px; height: 5px; border-radius: 50%; background: var(--dbp-capacity-accent); }

  /* ---------- projects chart ---------- */
  .dbp-capacity-ppanel { height: 100%; min-height: 380px; }
  .dbp-capacity-chips { display: flex; flex-wrap: wrap; gap: 5px; }
  .dbp-capacity-chip { height: 26px; padding: 0 10px 0 8px; display: inline-flex; align-items: center; gap: 6px; border-radius: 99px; font-size: 12px; font-weight: 580; color: var(--dbp-capacity-faint); box-shadow: inset 0 0 0 1px var(--dbp-capacity-line-2); transition: color 150ms, background-color 150ms; }
  .dbp-capacity-chip i { width: 9px; height: 9px; border-radius: 3px; box-shadow: inset 0 0 0 1.5px oklch(0.72 0.11 var(--h)); transition: background-color 150ms; }
  .dbp-capacity-chip[aria-pressed="true"] { color: var(--dbp-capacity-ink); background: oklch(0.96 0.02 var(--h)); }
  .dbp-capacity-chip[aria-pressed="true"] i { background: oklch(0.72 0.11 var(--h)); }
  .dbp-capacity-chart { position: relative; flex: 1; min-height: 260px; margin: 4px 10px 12px; }
  .dbp-capacity-chart svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; font: 10.5px var(--dbp-capacity-mono); }
  .dbp-capacity-chart text { fill: var(--dbp-capacity-faint); font-variant-numeric: tabular-nums; }
  .dbp-capacity-chart .dbp-capacity-gl { stroke: var(--dbp-capacity-line); shape-rendering: crispEdges; }
  .dbp-capacity-chart .dbp-capacity-col rect { transition: opacity 150ms; }
  .dbp-capacity-chart .dbp-capacity-colg { transform-box: fill-box; transform-origin: bottom; animation: dbp-capacity-grow 700ms var(--dbp-capacity-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbp-capacity-chart[data-ready] .dbp-capacity-colg { animation: none; }
  .dbp-capacity-chart .dbp-capacity-hit { fill: transparent; }
  .dbp-capacity-chart .dbp-capacity-col[data-on] .dbp-capacity-hit { fill: var(--dbp-capacity-line); }
  .dbp-capacity-chart .dbp-capacity-capl { fill: none; stroke: var(--dbp-capacity-ink); stroke-width: 1.75; animation: dbp-capacity-fade 600ms 500ms both; }
  .dbp-capacity-chart .dbp-capacity-tgt { fill: none; stroke: var(--dbp-capacity-accent); stroke-width: 1.25; stroke-dasharray: 4 4; animation: dbp-capacity-fade 600ms 600ms both; }
  .dbp-capacity-chart .dbp-capacity-lab { font: 600 10.5px system-ui, sans-serif; }

  /* ---------- responsive ---------- */
  @container (max-width: 1060px) {
    .dbp-capacity-vpeople { grid-template-columns: minmax(0, 1fr) 236px; }
  }
  @container (max-width: 960px) {
    .dbp-capacity-app { grid-template-columns: 60px minmax(0, 1fr); }
    .dbp-capacity-side { align-items: center; padding-inline: 8px; }
    .dbp-capacity-brand { padding: 0; }
    .dbp-capacity-brand span, .dbp-capacity-navbtn span, .dbp-capacity-legend { display: none; }
    .dbp-capacity-navbtn { justify-content: center; padding: 10px; }
    .dbp-capacity-main { display: flex; flex-direction: column; }
    .dbp-capacity-main > * { flex: none; }
    .dbp-capacity-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .dbp-capacity-vpeople { grid-template-columns: minmax(0, 1fr); }
    .dbp-capacity-hpanel { max-height: 480px; }
    .dbp-capacity-hscroll { flex: 0 1 auto; }
    .dbp-capacity-detail { overflow: visible; }
  }
  @container (max-width: 760px) {
    .dbp-capacity-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "side" "top" "main"; }
    .dbp-capacity-side { flex-direction: row; justify-content: space-between; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbp-capacity-line); }
    .dbp-capacity-nav { display: flex; gap: 2px; }
    .dbp-capacity-top { padding: 12px 14px 10px; }
    .dbp-capacity-main { padding: 0 12px 12px; }
    .dbp-capacity-grid { grid-template-columns: minmax(128px, 1fr) repeat(var(--n), minmax(40px, 1fr)) 50px; padding: 0 6px 8px; }
    .dbp-capacity-who small { display: none; }
    .dbp-capacity-who { position: sticky; left: 0; z-index: 2; background: var(--dbp-capacity-card); }
    .dbp-capacity-head > *:first-child { position: sticky; left: 0; background: var(--dbp-capacity-card); }
  }
  @container (max-width: 440px) {
    .dbp-capacity-grid { grid-template-columns: 112px repeat(var(--n), 38px) 50px; }
    .dbp-capacity-who .dbp-capacity-av { display: none; }
    .dbp-capacity-cell { font-size: 10.5px; }
    .dbp-capacity-cell small { display: none; }
    .dbp-capacity-head > * { font-size: 9.5px; }
    .dbp-capacity-head b { display: none; }
    .dbp-capacity-kpi b { font-size: 17px; }
  }

  @media (prefers-reduced-motion: reduce) {
    & *, & *::before, & *::after { animation: none !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
