const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const uid = 'dbp-capacity-' + Math.random().toString(36).slice(2, 8);

/* ---------- people, projects, assignments ----------
   Load(person, week) is the sum of that person's assignment hours in the week; a
   week of time off has zero capacity and pauses their assignments. Every cell,
   footer, KPI, tooltip and the project chart are summed from the list A. */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WEEK0 = Date.UTC(2026, 9, 5);
const wd = i => new Date(WEEK0 + i * 7 * 864e5);
const fw = i => `${MON[wd(i).getUTCMonth()]} ${wd(i).getUTCDate()}`;
const SQUADS = { checkout: 'Checkout', growth: 'Growth', infra: 'Infra' };
const PEOPLE = [
  ['amara', 'Amara Diallo', 'checkout', 'Staff engineer', 40, {}, 25],
  ['felix', 'Felix Novak', 'checkout', 'Senior engineer', 40, { 2: 0 }, 70],
  ['sana', 'Sana Mirza', 'checkout', 'Engineer · 4-day week', 32, {}, 330],
  ['joaquin', 'Joaquín Reyes', 'checkout', 'Engineer', 40, {}, 150],
  ['ivy', 'Ivy Chen-Moreau', 'growth', 'Tech lead', 40, { 7: 0 }, 200],
  ['bram', 'Bram de Vries', 'growth', 'Senior engineer', 40, {}, 100],
  ['lucia', 'Lucia Ferraro', 'growth', 'Engineer · part-time', 24, {}, 10],
  ['tobias', 'Tobias Lund', 'growth', 'Engineer', 40, {}, 280],
  ['nadia', 'Nadia Haddad', 'infra', 'Staff SRE', 40, {}, 300],
  ['owen', 'Owen Pryce', 'infra', 'Senior SRE', 40, {}, 55],
  ['keiko', 'Keiko Arai', 'infra', 'SRE', 40, { 5: 24 }, 180],
  ['ruben', 'Ruben Soto', 'infra', 'SRE · 4-day week', 32, {}, 120]
].map(([id, name, squad, role, cap, off, h]) => ({ id, name, squad, role, cap, off, h, ini: name.split(' ')[0][0] + name.split(' ').slice(-1)[0][0] }));
const P = {}; PEOPLE.forEach(p => { P[p.id] = p; });
const PROJ = { pay: ['Wallet payments', 22], sub: ['Subscriptions v2', 300], onb: ['Onboarding revamp', 150], exp: ['Experiment platform', 95], k8s: ['Cluster migration', 250], obs: ['Observability', 200], oncall: ['On-call & support', 60] };
let nid = 0;
let A = [
  ['amara', 'pay', 0, 5, 24], ['amara', 'sub', 4, 9, 16], ['amara', 'oncall', 0, 9, 4],
  ['felix', 'pay', 0, 6, 30], ['felix', 'sub', 1, 3, 12], ['felix', 'oncall', 0, 9, 4],
  ['sana', 'sub', 0, 9, 20], ['sana', 'pay', 3, 6, 10], ['sana', 'oncall', 0, 9, 4],
  ['joaquin', 'pay', 0, 3, 16], ['joaquin', 'sub', 2, 9, 20], ['joaquin', 'oncall', 0, 9, 4],
  ['ivy', 'onb', 0, 9, 24], ['ivy', 'exp', 5, 8, 16], ['ivy', 'sub', 5, 6, 8],
  ['bram', 'exp', 0, 9, 28], ['bram', 'onb', 2, 5, 12],
  ['lucia', 'onb', 0, 9, 12], ['lucia', 'exp', 3, 4, 8],
  ['tobias', 'exp', 0, 4, 20], ['tobias', 'onb', 3, 9, 20], ['tobias', 'sub', 6, 8, 10],
  ['nadia', 'k8s', 0, 9, 28], ['nadia', 'obs', 6, 9, 8], ['nadia', 'oncall', 0, 0, 12], ['nadia', 'oncall', 4, 4, 12], ['nadia', 'oncall', 8, 8, 12],
  ['owen', 'k8s', 0, 6, 32], ['owen', 'obs', 0, 9, 8], ['owen', 'oncall', 1, 1, 12], ['owen', 'oncall', 5, 5, 12], ['owen', 'oncall', 9, 9, 12],
  ['keiko', 'obs', 0, 9, 20], ['keiko', 'k8s', 3, 8, 12], ['keiko', 'oncall', 2, 2, 12], ['keiko', 'oncall', 6, 6, 12],
  ['ruben', 'k8s', 2, 9, 16], ['ruben', 'obs', 0, 3, 8], ['ruben', 'oncall', 3, 3, 12], ['ruben', 'oncall', 7, 7, 12]
].map(([who, proj, from, to, h]) => ({ id: ++nid, who, proj, from, to, h }));

const cap = (p, w) => p.off[w] ?? p.cap;
const parts = (p, w) => cap(p, w) === 0 ? [] : A.filter(a => a.who === p.id && a.from <= w && w <= a.to);
const load = (p, w) => parts(p, w).reduce((s, a) => s + a.h, 0);
const util = (p, w) => cap(p, w) ? load(p, w) / cap(p, w) : null;
const pct = u => Math.round(u * 100);

/* ---------- state ---------- */
const S = { squad: 'all', weeks: 10, sort: 'squad', sel: null, view: 'people', hidden: new Set(), hist: [], log: [], form: null };
const people = () => PEOPLE.filter(p => S.squad === 'all' || p.squad === S.squad);
const wks = () => Array.from({ length: S.weeks }, (_, i) => i);
const peak = p => Math.max(0, ...wks().map(w => util(p, w) ?? 0));
const free = p => wks().reduce((s, w) => s + Math.max(0, cap(p, w) * 0.85 - load(p, w)), 0);
const ordered = () => {
  const ps = people().slice();
  if (S.sort === 'peak') ps.sort((a, b) => peak(b) - peak(a));
  else if (S.sort === 'free') ps.sort((a, b) => free(b) - free(a));
  else if (S.sort === 'name') ps.sort((a, b) => a.name.localeCompare(b.name));
  return ps;
};

/* ---------- heatmap ---------- */
const grid = $('[data-grid]'), tip = $('[data-tip]'), hpanel = $('.dbp-capacity-hpanel'), detail = $('[data-detail]');
const cellHtml = (p, w, r) => `<div class="dbp-capacity-cell" role="gridcell" tabindex="-1" data-p="${p.id}" data-w="${w}" aria-selected="false" style="--d:${(r + w) * 18}"></div>`;
const rowHtml = (p, r) => `<div class="dbp-capacity-row" role="row" data-p="${p.id}"><div class="dbp-capacity-who" role="rowheader"><i class="dbp-capacity-av" style="--h:${p.h}">${p.ini}</i><span><b>${esc(p.name)}</b><small>${esc(p.role)} · ${p.cap} h</small></span></div>${wks().map(w => cellHtml(p, w, r)).join('')}<div class="dbp-capacity-peak" role="gridcell" data-peak></div></div>`;
const squadHtml = sq => `<div class="dbp-capacity-squad" role="row" data-squad="${sq}"><span role="columnheader">${SQUADS[sq]}</span><small data-sqs></small></div>`;
let readyT = 0;
const build = () => {
  grid.style.setProperty('--n', S.weeks);
  const head = `<div class="dbp-capacity-row dbp-capacity-head" role="row"><div role="columnheader">Engineer</div>${wks().map(w => `<div role="columnheader" data-w="${w}"><b>W${41 + w}</b>${fw(w)}</div>`).join('')}<div role="columnheader">Peak</div></div>`;
  const foot = `<div class="dbp-capacity-row dbp-capacity-foot" role="row" data-foot><div role="rowheader">Team load</div>${wks().map(w => `<div role="gridcell" data-fw="${w}"></div>`).join('')}<div role="gridcell" data-favg></div></div>`;
  grid.innerHTML = head + people().map((p, r) => rowHtml(p, r)).join('') + foot;
  arrange(false);
  update();
  clearTimeout(readyT);
  readyT = setTimeout(() => { $$('.dbp-capacity-cell', grid).forEach(c => c.style.setProperty('--d', 0)); }, reduce ? 0 : 1600);
  const first = grid.querySelector('.dbp-capacity-cell');
  if (first) first.tabIndex = 0;
};
const arrange = flip => {
  const rows = new Map($$('.dbp-capacity-row[data-p]', grid).map(r => [r.dataset.p, r]));
  const before = flip && !reduce ? new Map([...rows].map(([k, r]) => [k, r.getBoundingClientRect().top])) : null;
  $$('[data-squad]', grid).forEach(n => n.remove());
  const foot = grid.querySelector('[data-foot]');
  let last = null;
  ordered().forEach(p => {
    if (S.sort === 'squad' && p.squad !== last) { foot.insertAdjacentHTML('beforebegin', squadHtml(p.squad)); last = p.squad; }
    grid.insertBefore(rows.get(p.id), foot);
  });
  if (before) rows.forEach((r, k) => {
    const dy = before.get(k) - r.getBoundingClientRect().top;
    if (Math.abs(dy) > 0.5) r.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(0.22, 1, 0.36, 1)' });
  });
  updateSquads();
};
const updateSquads = () => $$('[data-squad]', grid).forEach(n => {
  const ps = people().filter(p => p.squad === n.dataset.squad);
  let l = 0, c = 0; ps.forEach(p => wks().forEach(w => { l += load(p, w); c += cap(p, w); }));
  n.querySelector('[data-sqs]').textContent = `${ps.length} people · ${c ? pct(l / c) : 0}% of ${c} h`;
});
const update = () => {
  $$('.dbp-capacity-cell', grid).forEach(c => {
    const p = P[c.dataset.p], w = +c.dataset.w, u = util(p, w);
    if (u == null) { c.setAttribute('data-pto', ''); c.textContent = 'PTO'; c.style.setProperty('--dbp-capacity-u', 0); c.removeAttribute('data-hot'); c.setAttribute('aria-label', `${p.name}, week of ${fw(w)}: time off`); return; }
    c.removeAttribute('data-pto');
    c.style.setProperty('--dbp-capacity-u', u.toFixed(3));
    c.innerHTML = `<span>${pct(u)}<small>%</small></span>`;
    c.toggleAttribute('data-hot', u > 1.2);
    c.toggleAttribute('data-part', cap(p, w) < p.cap);
    c.setAttribute('aria-label', `${p.name}, week of ${fw(w)}: ${load(p, w)} of ${cap(p, w)} hours, ${pct(u)} percent`);
  });
  $$('.dbp-capacity-row[data-p]', grid).forEach(r => {
    const p = P[r.dataset.p], pk = peak(p), el = r.querySelector('[data-peak]');
    el.textContent = pct(pk) + '%'; el.toggleAttribute('data-over', pk > 1);
  });
  let tl = 0, tc = 0;
  wks().forEach(w => {
    let l = 0, c = 0; people().forEach(p => { l += load(p, w); c += cap(p, w); });
    tl += l; tc += c;
    const el = grid.querySelector(`[data-fw="${w}"]`); if (!el) return;
    const f = c ? l / c : 0;
    el.innerHTML = `${pct(f)}%<i style="--f:${f.toFixed(3)}"${f > 1 ? ' data-over' : ''}></i>`;
    el.title = `${l} of ${c} hours`;
  });
  const fa = grid.querySelector('[data-favg]'); if (fa) fa.textContent = tc ? pct(tl / tc) + '%' : '';
  updateSquads(); renderKpis(); renderDetail();
  if (S.view === 'projects') drawChart(true);
};

/* ---------- KPIs ---------- */
const renderKpis = () => {
  let l = 0, c = 0, over = 0, freeH = 0; const overP = new Set(), pto = [];
  people().forEach(p => wks().forEach(w => {
    const cp = cap(p, w), ld = load(p, w);
    if (!cp) { pto.push(`${p.name.split(' ')[0]} (${fw(w)})`); return; }
    l += ld; c += cp; freeH += Math.max(0, cp * 0.85 - ld);
    if (ld > cp) { over++; overP.add(p.id); }
  }));
  const series = wks().map(w => { let a = 0, b = 0; people().forEach(p => { a += load(p, w); b += cap(p, w); }); return b ? a / b : 0; });
  const sx = i => i / Math.max(1, series.length - 1) * 64, sy = v => 26 - clamp(v / 1.2, 0, 1) * 24;
  const spark = `<svg viewBox="0 0 64 26" aria-hidden="true"><line x1="0" x2="64" y1="${sy(1)}" y2="${sy(1)}"/><path d="${series.map((v, i) => `${i ? 'L' : 'M'}${sx(i).toFixed(1)},${sy(v).toFixed(1)}`).join('')}"/></svg>`;
  $('[data-kpis]').innerHTML = [
    ['util', 'Team utilisation', `${c ? pct(l / c) : 0}%`, `${l.toLocaleString('en-US')} of ${c.toLocaleString('en-US')} h booked`, spark],
    ['over', 'Overbooked weeks', String(over), `across ${overP.size} ${overP.size === 1 ? 'person' : 'people'}`, ''],
    ['free', 'Free hours', `${Math.round(freeH)} h`, 'below an 85% focus target', ''],
    ['pto', 'Time off', `${pto.length} wk`, pto.length ? pto.join(', ') : 'none in range', '']
  ].map(([k, a, b, d, x]) => `<div class="dbp-capacity-kpi" data-k="${k}"><span>${a}</span><b>${b}</b>${x || '<i></i>'}<small>${esc(d)}</small></div>`).join('');
};

/* ---------- tooltip ---------- */
const showTip = cell => {
  if (!cell) { tip.hidden = true; return; }
  const p = P[cell.dataset.p], w = +cell.dataset.w, cp = cap(p, w), ld = load(p, w);
  tip.innerHTML = cp === 0
    ? `<h4>${esc(p.name)} <small>· week of ${fw(w)}</small></h4><p style="border:0;margin:0;padding:0">Time off — assignments pause this week.</p>`
    : `<h4>${esc(p.name)} <small>· week of ${fw(w)}</small></h4><ul>${parts(p, w).map(a => `<li><i style="--h:${PROJ[a.proj][1]}"></i><span>${PROJ[a.proj][0]}</span><b>${a.h} h</b></li>`).join('') || '<li><span></span><span>Nothing booked</span></li>'}</ul><p><span>${ld} of ${cp} h${cp < p.cap ? ' (short week)' : ''}</span><b>${ld > cp ? `+${ld - cp} h over` : `${cp - ld} h free`}</b></p>`;
  tip.hidden = false;
  const pr = hpanel.getBoundingClientRect(), cr = cell.getBoundingClientRect();
  let x = cr.left - pr.left + cr.width / 2 - tip.offsetWidth / 2, y = cr.bottom - pr.top + 8;
  x = clamp(x, 6, pr.width - tip.offsetWidth - 6);
  if (y + tip.offsetHeight > pr.height - 6) y = cr.top - pr.top - tip.offsetHeight - 8;
  tip.style.left = x + 'px'; tip.style.top = y + 'px';
};
grid.addEventListener('pointerover', e => showTip(e.target.closest('.dbp-capacity-cell')));
grid.addEventListener('pointerleave', () => showTip(null));
$('.dbp-capacity-hscroll').addEventListener('scroll', () => { tip.hidden = true; }, { passive: true });

/* ---------- selection + keyboard ---------- */
const select = (pid, w, focus) => {
  S.sel = pid == null ? null : { p: pid, w }; S.form = null;
  $$('.dbp-capacity-cell', grid).forEach(c => {
    const on = !!S.sel && c.dataset.p === pid && +c.dataset.w === w;
    c.setAttribute('aria-selected', String(on));
    if (on) { $$('.dbp-capacity-cell[tabindex="0"]', grid).forEach(n => { n.tabIndex = -1; }); c.tabIndex = 0; if (focus) c.focus(); }
  });
  $$('.dbp-capacity-head [data-w]', grid).forEach(h => h.toggleAttribute('data-on', !!S.sel && +h.dataset.w === w));
  renderDetail();
};
grid.addEventListener('click', e => {
  const c = e.target.closest('.dbp-capacity-cell'); if (!c) return;
  const same = S.sel && S.sel.p === c.dataset.p && S.sel.w === +c.dataset.w;
  if (same) select(null); else select(c.dataset.p, +c.dataset.w);
});
grid.addEventListener('keydown', e => {
  const c = e.target.closest('.dbp-capacity-cell'); if (!c) return;
  const order = ordered().map(p => p.id), r = order.indexOf(c.dataset.p);
  let pr = r, w = +c.dataset.w;
  switch (e.key) {
    case 'ArrowRight': w = Math.min(S.weeks - 1, w + 1); break;
    case 'ArrowLeft': w = Math.max(0, w - 1); break;
    case 'ArrowDown': pr = Math.min(order.length - 1, r + 1); break;
    case 'ArrowUp': pr = Math.max(0, r - 1); break;
    case 'Home': w = 0; break;
    case 'End': w = S.weeks - 1; break;
    case 'Enter': case ' ': select(c.dataset.p, w, true); e.preventDefault(); return;
    case 'Escape': select(null); return;
    default: return;
  }
  e.preventDefault();
  const n = grid.querySelector(`.dbp-capacity-cell[data-p="${order[pr]}"][data-w="${w}"]`);
  if (n) { c.tabIndex = -1; n.tabIndex = 0; n.focus(); showTip(n); }
});
grid.addEventListener('focusout', e => { if (!grid.contains(e.relatedTarget)) showTip(null); });

/* ---------- detail: breakdown, rebalancing, hot spots ---------- */
const mates = (p, w) => PEOPLE.filter(m => m.squad === p.squad && m.id !== p.id && cap(m, w) > 0).sort((a, b) => util(a, w) - util(b, w));
const renderDetail = () => {
  if (!S.sel) {
    const cells = [];
    people().forEach(p => wks().forEach(w => { const u = util(p, w); if (u != null && u > 1) cells.push({ p, w, u }); }));
    cells.sort((a, b) => b.u - a.u);
    detail.innerHTML = `<div class="dbp-capacity-dbody">
      <div class="dbp-capacity-hot"><h5>Hot spots</h5>${cells.slice(0, 6).map(c => `<button class="dbp-capacity-hotbtn" data-go="${c.p.id}:${c.w}"><i class="dbp-capacity-av" style="--h:${c.p.h}">${c.p.ini}</i><span><b>${esc(c.p.name)}</b><small>Week of ${fw(c.w)} · ${load(c.p, c.w)}&nbsp;of&nbsp;${cap(c.p, c.w)}&nbsp;h</small></span><em>${pct(c.u)}%</em></button>`).join('') || '<p class="dbp-capacity-note">Nobody is booked over capacity in this range.</p>'}</div>
      <p class="dbp-capacity-note">Select a week to see what fills it, then move an assignment to a teammate with room.</p>
      ${S.log.length ? `<div class="dbp-capacity-asg"><h5>Moves this session</h5><ul class="dbp-capacity-log">${S.log.slice().reverse().map(l => `<li>${esc(l)}</li>`).join('')}</ul><button class="dbp-capacity-btn dbp-capacity-undo" data-undo>Undo last move</button></div>` : ''}
    </div>`;
    return;
  }
  const p = P[S.sel.p], w = S.sel.w, cp = cap(p, w), ld = load(p, w), u = cp ? ld / cp : null, ps = parts(p, w);
  const max = Math.max(cp, ld) || 1;
  detail.innerHTML = `<div class="dbp-capacity-dbody">
    <div class="dbp-capacity-dh"><i class="dbp-capacity-av" style="--h:${p.h}">${p.ini}</i><div><h4>${esc(p.name)}</h4><small>${SQUADS[p.squad]} · week of ${fw(w)}</small></div><button class="dbp-capacity-x" data-close aria-label="Clear selection"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div>
    ${cp === 0 ? '<p class="dbp-capacity-note">On time off this week. Assignments pause and resume the week after.</p>' : `
    <div class="dbp-capacity-big"><b>${ld} h</b><span>of ${cp} h${cp < p.cap ? ` (short week, usually ${p.cap})` : ''}</span><em${u > 1 ? ' data-over' : u < 0.6 ? ' data-low' : ''}>${pct(u)}%</em></div>
    <div class="dbp-capacity-stack" aria-hidden="true">${ps.map(a => `<i style="--h:${PROJ[a.proj][1]};--g:${a.h}"></i>`).join('')}${ld < max ? `<i style="--g:${max - ld};background:transparent"></i>` : ''}<u style="--x:${(cp / max * 100).toFixed(2)}%" data-l="${cp} h"></u></div>
    <div class="dbp-capacity-asg"><h5>Booked this week</h5>${ps.map(a => itemHtml(a, p, w)).join('') || '<p class="dbp-capacity-note">Nothing booked.</p>'}</div>`}
    ${S.hist.length ? '<button class="dbp-capacity-btn dbp-capacity-undo" data-undo>Undo last move</button>' : ''}
  </div>`;
};
const itemHtml = (a, p, w) => {
  const open = S.form && S.form.a === a.id;
  const ms = mates(p, w);
  let form = '';
  if (open) {
    const to = P[S.form.to] || ms[0];
    const end = S.form.scope === 'week' ? w : a.to;
    const hrs = Math.min(S.form.hrs || a.h, a.h);
    const nu = to ? (load(to, w) + hrs) / cap(to, w) : 0;
    form = `<div class="dbp-capacity-form">
      <label>Move to<select data-to>${ms.map(m => `<option value="${m.id}"${to && m.id === to.id ? ' selected' : ''}>${esc(m.name)} — ${pct(util(m, w))}% that week</option>`).join('')}</select></label>
      <label>Hours per week<span class="dbp-capacity-range"><input type="range" data-hrs min="${Math.min(4, a.h)}" max="${a.h}" step="${a.h % 4 ? 1 : 4}" value="${hrs}" aria-valuetext="${hrs} hours of ${a.h}"><output>${hrs} of ${a.h} h</output></span></label>
      <fieldset><legend class="dbp-capacity-eyebrow" style="margin-bottom:4px">For</legend><label><input type="radio" name="${uid}-scope-${a.id}" value="week"${S.form.scope === 'week' ? ' checked' : ''}> Week of ${fw(w)}</label><label><input type="radio" name="${uid}-scope-${a.id}" value="rest"${S.form.scope === 'rest' ? ' checked' : ''}> Through ${fw(a.to)}</label></fieldset>
      ${to ? (() => {
        let pk = nu, pw = w;
        for (let k = w + 1; k <= end; k++) { if (!cap(to, k)) continue; const v = (load(to, k) + hrs) / cap(to, k); if (v > pk) { pk = v; pw = k; } }
