@property --dbp-okr-p { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --dbp-okr-n { syntax: "<integer>"; inherits: false; initial-value: 0; }
@keyframes dbp-okr-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-okr-fade { from { opacity: 0; } }
@keyframes dbp-okr-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbp-okr-glow { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--dbp-okr-gold) 70%, transparent); } 100% { box-shadow: 0 0 0 14px transparent; } }

.dbp-okr {
  /* re-theme with these four */
  --dbp-okr-bg: oklch(0.21 0.028 165);
  --dbp-okr-ink: oklch(0.95 0.015 120);
  --dbp-okr-gold: oklch(0.84 0.13 85);
  --dbp-okr-alert: oklch(0.68 0.17 25);
  /* derived */
  --dbp-okr-good: color-mix(in oklch, var(--dbp-okr-gold), oklch(0.8 0.14 155) 70%);
  --dbp-okr-risk: color-mix(in oklch, var(--dbp-okr-gold), var(--dbp-okr-alert) 45%);
  --dbp-okr-card: color-mix(in oklch, var(--dbp-okr-bg), var(--dbp-okr-ink) 6%);
  --dbp-okr-raised: color-mix(in oklch, var(--dbp-okr-bg), var(--dbp-okr-ink) 10%);
  --dbp-okr-deep: color-mix(in oklch, var(--dbp-okr-bg), black 22%);
  --dbp-okr-line: color-mix(in oklch, var(--dbp-okr-ink) 11%, transparent);
  --dbp-okr-line-2: color-mix(in oklch, var(--dbp-okr-ink) 22%, transparent);
  --dbp-okr-muted: color-mix(in oklch, var(--dbp-okr-ink) 64%, var(--dbp-okr-bg));
  --dbp-okr-faint: color-mix(in oklch, var(--dbp-okr-ink) 42%, var(--dbp-okr-bg));
  --dbp-okr-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-okr-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-okr-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-okr-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: radial-gradient(120% 80% at 100% 0%, color-mix(in oklch, var(--dbp-okr-gold) 7%, transparent), transparent 60%), var(--dbp-okr-bg);
  color: var(--dbp-okr-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-okr-gold);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-okr-gold); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-okr-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbp-okr-muted); }
  .dbp-okr-num { text-align: right; }

  .dbp-okr-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-okr-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--dbp-okr-deep); border-right: 1px solid var(--dbp-okr-line); }
  .dbp-okr-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-okr-brand svg { width: 30px; height: 30px; padding: 4px; flex: none; border-radius: 50%; background: var(--dbp-okr-gold); fill: none; stroke: var(--dbp-okr-deep); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-okr-brand span { display: grid; line-height: 1.2; }
  .dbp-okr-brand b { font-weight: 720; letter-spacing: -0.01em; }
  .dbp-okr-brand small { font-size: 11px; color: var(--dbp-okr-muted); }
  .dbp-okr-nav { display: grid; gap: 2px; }
  .dbp-okr-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-okr-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-okr-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-okr-navbtn:hover { color: var(--dbp-okr-ink); background: var(--dbp-okr-line); }
  .dbp-okr-navbtn[aria-current="page"] { color: var(--dbp-okr-deep); background: var(--dbp-okr-gold); }
  .dbp-okr-quarter { margin-top: auto; display: grid; gap: 6px; padding: 14px 8px 0; border-top: 1px solid var(--dbp-okr-line); }
  .dbp-okr-quarter b { font: 650 22px/1 var(--dbp-okr-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
  .dbp-okr-quarter b small { font: 500 12px system-ui, sans-serif; letter-spacing: 0; color: var(--dbp-okr-muted); margin-left: 4px; }
  .dbp-okr-quarter small { font-size: 11.5px; color: var(--dbp-okr-muted); line-height: 1.4; }
  .dbp-okr-qbar { position: relative; height: 6px; border-radius: 99px; background: var(--dbp-okr-line); }
  .dbp-okr-qbar i { position: absolute; inset: 0 auto 0 0; width: calc(var(--f) * 100%); border-radius: inherit; background: repeating-linear-gradient(90deg, var(--dbp-okr-gold) 0 calc(100% / var(--w) - 2px), transparent calc(100% / var(--w) - 2px) calc(100% / var(--w))); }

  /* ---------- top ---------- */
  .dbp-okr-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; }
  .dbp-okr-title { display: grid; gap: 3px; }
  .dbp-okr-h { font-size: clamp(19px, 0.95rem + 0.9cqi, 27px); font-weight: 740; letter-spacing: -0.035em; line-height: 1.05; }
  .dbp-okr-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  .dbp-okr-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbp-okr-deep); box-shadow: inset 0 0 0 1px var(--dbp-okr-line); }
  .dbp-okr-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbp-okr-muted); transition: color 150ms, background-color 150ms; }
