/* ---------- layout: horizontal tidy tree when there is room, indented outline otherwise ---------- */
let L = null;
const layout = () => {
  const W = Math.max(280, tscroll.clientWidth - 28), horiz = W >= 700, pos = {};
  let y = 0;
  if (horiz) {
    const g = clamp(W * 0.055, 34, 60), c0 = clamp(W * 0.24, 184, 236), c2 = W - 2 * c0 - 2 * g;
    const X = [0, c0 + g, 2 * c0 + 2 * g], WID = [c0, c0, c2], H = { co: 104, team: 78, kr: 72 };
    const place = n => {
      const kids = S.collapsed.has(n.id) ? [] : n.kids;
      if (!kids.length) { pos[n.id] = { x: X[n.depth], y, w: WID[n.depth], h: H[n.kind] }; y += H[n.kind] + 10; return; }
      kids.forEach(place);
      const a = pos[kids[0].id];
      pos[n.id] = { x: X[n.depth], y: a.y, w: WID[n.depth], h: H[n.kind] };
      y = Math.max(y, a.y + H[n.kind] + 10);
