      if (!S.collapsed.has(n.id)) n.kids.forEach(place);
    };
    ROOTS.forEach(r => { place(r); y += 10; });
  }
  N.forEach(n => { const h = hiddenBy(n); if (h) pos[n.id] = { ...pos[h.id], out: true }; });
  L = { pos, horiz, W, H: Math.max(0, y - 18) };
  canvas.style.height = L.H + 'px';
  return L;
};

const edgePath = (p, c, horiz) => {
  if (horiz) {
    const x1 = p.x + p.w, y1 = p.y + p.h / 2, x2 = c.x, y2 = c.y + c.h / 2, m = (x2 - x1) / 2;
    return `M${x1.toFixed(1)},${y1.toFixed(1)}C${(x1 + m).toFixed(1)},${y1.toFixed(1)} ${(x2 - m).toFixed(1)},${y2.toFixed(1)} ${x2.toFixed(1)},${y2.toFixed(1)}`;
  }
