  const tr = e.target.closest('.dbp-okr-row'); if (!tr) return;
  const go = n => { if (n && n.classList.contains('dbp-okr-row')) { tr.tabIndex = -1; n.tabIndex = 0; n.focus(); } };
  if (e.key === 'ArrowDown') { e.preventDefault(); go(tr.nextElementSibling); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); go(tr.previousElementSibling); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(tr.dataset.id); }
  else if (e.key === 'Escape') select(null);
});

/* ---------- drawer ---------- */
let draft = null;
const crumbs = n => { const out = []; let p = n.parent && byId[n.parent]; while (p) { out.unshift(p.kind === 'co' ? p.title : `${p.team}: ${p.title}`); p = p.parent && byId[p.parent]; } return out.join(' › '); };
const renderDrawer = () => {
  const n = S.sel && byId[S.sel];
  if (!n) { drawer.hidden = true; draft = null; return; }
  const p = prog(n), s = statusOf(p), d = Math.round((p - PACE) * 100);
  const head = `<div class="dbp-okr-dh">${n.parent ? `<div class="dbp-okr-crumbs">${esc(crumbs(n))}</div>` : ''}<h4>${esc(n.title)}</h4><button class="dbp-okr-x" data-close aria-label="Close details"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div>
    <div class="dbp-okr-status" style="--c:var(--dbp-okr-${s === 'good' ? 'good' : s === 'risk' ? 'risk' : 'alert'})"><i></i><b>${LABEL[s]}</b><span>· ${pct(p)}% done, ${d >= 0 ? `${d} pts ahead of` : `${-d} pts behind`} pace</span></div>`;
  if (n.kind !== 'kr') {
    drawer.innerHTML = head + `<p class="dbp-okr-note">Owned by ${esc(n.owner)}${n.role ? `, ${n.role}` : ''}. Progress is the average of ${n.kids.length} ${n.kind === 'co' ? 'team objectives' : 'key results'}, weighted equally.</p>
      <div class="dbp-okr-kids">${n.kids.map(c => { const cp = prog(c), cs = statusOf(cp); return `<button class="dbp-okr-kid" data-go="${c.id}" style="--c:var(--dbp-okr-${cs === 'good' ? 'good' : cs === 'risk' ? 'risk' : 'alert'})"><b>${esc(c.kind === 'kr' ? c.title : `${c.team}: ${c.title}`)}</b><span>${pct(cp)}%</span><div class="dbp-okr-bar"><i style="--f:${cp.toFixed(4)}"></i><u style="--pace:${PACE}"></u></div></button>`; }).join('')}</div>`;
    drawer.hidden = false; return;
  }
  if (!draft || draft.id !== n.id) draft = { id: n.id, v: n.cur, conf: n.conf };
  const span = Math.abs(n.target - n.start), lo = Math.min(n.start, n.target) - span * 0.15, hi = Math.max(n.start, n.target) + span * 0.15, step = Math.pow(10, -n.dp);
  drawer.innerHTML = head + `
    <div class="dbp-okr-facts"><div><span>Start</span><b>${fmt(n, n.start)}</b></div><div><span>Now</span><b>${fmt(n, n.cur)}</b></div><div><span>Target</span><b>${fmt(n, n.target)}</b></div></div>
    <div class="dbp-okr-spark" data-spark tabindex="0" role="img" aria-label="Weekly check-ins for ${esc(n.title)} against the ideal pace. Arrow keys read each week."><svg data-ssvg aria-hidden="true"></svg><div class="dbp-okr-stip" hidden></div></div>
    <p class="dbp-okr-note" data-proj></p>
    <form class="dbp-okr-form" data-form>
      <h5>Week ${WEEK} check-in</h5>
      <label><span>Current value<output data-vout>${fmt(n, draft.v)}</output></span><input type="range" data-v min="${lo.toFixed(n.dp)}" max="${hi.toFixed(n.dp)}" step="${step}" value="${draft.v}"></label>
      <label><span>Confidence to hit target<output data-cout>${draft.conf}/10</output></span><input type="range" data-c min="0" max="10" step="1" value="${draft.conf}"></label>
      <div class="dbp-okr-preview" data-preview aria-live="polite"></div>
      <button class="dbp-okr-btn" data-primary type="submit">Save check-in</button>
    </form>`;
  drawer.hidden = false;
  drawSpark(n); preview(n);
};
const preview = n => {
  const box = drawer.querySelector('[data-preview]'); if (!box) return;
  const old = n.cur, before = [n, byId[n.parent], byId[byId[n.parent].parent]].map(prog), cb = company();
  n.cur = draft.v;
  const after = [n, byId[n.parent], byId[byId[n.parent].parent]].map(prog), ca = company();
  n.cur = old;
  const row = (label, a, b) => `<div><span>${label}</span><b>${pct(a)}% ${pct(a) !== pct(b) ? `→ <em>${pct(b)}%</em>` : ''}</b></div>`;
  box.innerHTML = row('This key result', before[0], after[0]) + row(esc(byId[n.parent].team), before[1], after[1]) + row('Company objective', before[2], after[2]) + row('Company score', cb, ca);
};
const drawSpark = n => {
  const box = drawer.querySelector('[data-spark]'); if (!box) return;
  const svg = box.querySelector('svg'), W = box.clientWidth, H = box.clientHeight; if (!W) return;
  const m = { l: 40, r: 10, t: 10, b: 20 }, iw = W - m.l - m.r, ih = H - m.t - m.b;
  const lastW = n.hist.length - 1, slope = lastW >= 3 ? (n.hist[lastW] - n.hist[lastW - 3]) / 3 : 0, projV = n.cur + slope * (WEEKS - lastW);
  const vals = [...n.hist, n.start, n.target, projV], lo = Math.min(...vals), hi = Math.max(...vals), pad = (hi - lo) * 0.1 || 1;
  const y0 = lo - pad, y1 = hi + pad, x = w => m.l + w / WEEKS * iw, y = v => m.t + ih - (v - y0) / (y1 - y0) * ih;
  let s = '';
  [n.start, n.target].forEach(v => { s += `<line class="dbp-okr-gl" x1="${m.l}" x2="${W - m.r}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text x="${m.l - 6}" y="${(y(v) + 3.5).toFixed(1)}" text-anchor="end">${fmt(n, v)}</text>`; });
  for (let w = 0, st = W < 300 ? 2 : 1; w <= WEEKS; w += st) s += `<text x="${x(w).toFixed(1)}" y="${H - 4}" text-anchor="middle">${w === 0 ? 'wk 0' : w}</text>`;
  s += `<path class="dbp-okr-ideal" d="M${x(0)},${y(n.start).toFixed(1)}L${x(WEEKS)},${y(n.target).toFixed(1)}"/>`;
  s += `<path class="dbp-okr-proj" d="M${x(lastW).toFixed(1)},${y(n.cur).toFixed(1)}L${x(WEEKS).toFixed(1)},${y(projV).toFixed(1)}"/>`;
  s += `<path class="dbp-okr-actual" pathLength="1" d="${n.hist.map((v, w) => `${w ? 'L' : 'M'}${x(w).toFixed(1)},${y(v).toFixed(1)}`).join('')}"/>`;
  s += `<line class="dbp-okr-xh" data-xh y1="${m.t}" y2="${m.t + ih}" x1="-10" x2="-10"/><circle r="4" cx="${x(lastW).toFixed(1)}" cy="${y(n.cur).toFixed(1)}"/>`;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`); svg.innerHTML = s;
  box._g = { x, y, m, iw, n };
  const pp = clamp((projV - n.start) / (n.target - n.start), 0, 1.2);
  drawer.querySelector('[data-proj]').innerHTML = `At the last four weeks' rate this lands near <b>${fmt(n, projV)}</b> by week ${WEEKS} — ${pct(Math.min(pp, 1))}% of target${pp >= 1 ? ', target met' : ''}.`;
};
const sparkAt = (box, w) => {
  const g = box._g, tip = box.querySelector('.dbp-okr-stip'), xh = box.querySelector('[data-xh]');
  if (w == null) { tip.hidden = true; xh.setAttribute('x1', -10); xh.setAttribute('x2', -10); return; }
  const n = g.n, v = n.hist[w];
  xh.setAttribute('x1', g.x(w)); xh.setAttribute('x2', g.x(w));
  const ideal = n.start + (n.target - n.start) * w / WEEKS;
  tip.textContent = `Week ${w}: ${fmt(n, v)} · pace ${fmt(n, ideal)}`;
  tip.hidden = false; tip.style.left = clamp(g.x(w), 70, box.clientWidth - 70) + 'px'; tip.style.top = g.y(v) + 'px';
};
drawer.addEventListener('pointermove', e => { const box = e.target.closest('[data-spark]'); if (!box || !box._g) return; const r = box.getBoundingClientRect(), g = box._g; box._w = clamp(Math.round((e.clientX - r.left - g.m.l) / g.iw * WEEKS), 0, g.n.hist.length - 1); sparkAt(box, box._w); });
drawer.addEventListener('pointerout', e => { const box = e.target.closest('[data-spark]'); if (box && !box.contains(e.relatedTarget)) sparkAt(box, null); });
drawer.addEventListener('keydown', e => {
  const box = e.target.closest('[data-spark]');
  if (box && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) { e.preventDefault(); box._w = clamp((box._w ?? box._g.n.hist.length) + (e.key === 'ArrowRight' ? 1 : -1), 0, box._g.n.hist.length - 1); sparkAt(box, box._w); return; }
  if (e.key === 'Escape') { const id = S.sel; select(null); if (id && S.view === 'tree') focusNode(id); }
});
drawer.addEventListener('input', e => {
  const n = byId[S.sel]; if (!n || !draft) return;
  if (e.target.matches('[data-v]')) { draft.v = +(+e.target.value).toFixed(n.dp); drawer.querySelector('[data-vout]').textContent = fmt(n, draft.v); preview(n); }
  if (e.target.matches('[data-c]')) { draft.conf = +e.target.value; drawer.querySelector('[data-cout]').textContent = `${draft.conf}/10`; }
});
drawer.addEventListener('click', e => {
  if (e.target.closest('[data-close]')) { const id = S.sel; select(null); if (id && S.view === 'tree') focusNode(id); return; }
  const go = e.target.closest('[data-go]'); if (go) { const id = go.dataset.go; if (hiddenBy(byId[id])) { S.collapsed.clear(); syncFold(); relayout(); } select(id); if (S.view === 'tree') focusNode(id); }
});
drawer.addEventListener('submit', e => {
  e.preventDefault();
  const n = byId[S.sel]; if (!n || !draft) return;
  n.cur = draft.v; n.conf = draft.conf;
  if (n.fresh) n.hist[n.hist.length - 1] = n.cur; else { n.hist.push(n.cur); n.fresh = true; }
  propagate(n);
  renderDrawer(); renderTable(); renderKpis(); applyFilter();
  const btn = drawer.querySelector('[data-primary]'); if (btn) { btn.textContent = 'Saved'; btn.focus(); setTimeout(() => { if (btn.isConnected) btn.textContent = 'Save check-in'; }, 1600); }
});

/* a check-in travels up the tree: each ancestor repaints as the pulse reaches it */
const propagate = n => {
  paintNode(n.id);
  const chain = []; let c = n;
  while (c.parent) { chain.push([c, byId[c.parent]]); c = byId[c.parent]; }
  if (reduce || S.view !== 'tree') { chain.forEach(([, p]) => paintNode(p.id)); return; }
  chain.forEach(([child, parent], i) => {
    const d = L && !L.pos[child.id].out && edgePath(D[parent.id], D[child.id], L.horiz);
    setTimeout(() => {
      if (!root.isConnected) return;
      if (d) {
        const p = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        p.setAttribute('class', 'dbp-okr-pulse'); p.setAttribute('d', d); p.setAttribute('pathLength', '100'); p.setAttribute('stroke-dasharray', '18 220');
        edgesSvg.appendChild(p);
        p.animate([{ strokeDashoffset: -100 }, { strokeDashoffset: 18 }], { duration: 560, easing: 'cubic-bezier(0.45, 0, 0.2, 1)' }).onfinish = () => p.remove();
      }
      setTimeout(() => { if (!root.isConnected) return; paintNode(parent.id); const e = el[parent.id]; e.removeAttribute('data-glow'); void e.offsetWidth; e.setAttribute('data-glow', ''); }, 470);
    }, i * 480);
  });
};
tree.addEventListener('animationend', e => { const n = e.target.closest('.dbp-okr-node'); if (n && e.animationName.endsWith('glow')) n.removeAttribute('data-glow'); });

/* ---------- controls ---------- */
const seg = (name, fn) => {
  const g = $(`[data-group="${name}"]`), bs = $$('[role="radio"]', g);
  const sync = () => bs.forEach(b => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
  const pick = (b, focus) => { bs.forEach(x => x.setAttribute('aria-checked', String(x === b))); sync(); if (focus) b.focus(); fn(b.dataset.v); };
  g.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  g.addEventListener('keydown', e => { const k = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key]; if (!k) return; e.preventDefault(); const i = bs.findIndex(b => b.getAttribute('aria-checked') === 'true'); pick(bs[(i + k + bs.length) % bs.length], true); });
  sync();
};
seg('status', v => { S.filter = v; applyFilter(); if (L) paint(); });
const foldBtn = $('[data-fold]');
const syncFold = () => { const all = N.filter(n => n.kind === 'team').every(n => S.collapsed.has(n.id)); foldBtn.setAttribute('aria-pressed', String(all)); foldBtn.querySelector('span').textContent = all ? 'Expand teams' : 'Collapse teams'; };
foldBtn.addEventListener('click', () => {
  const teams = N.filter(n => n.kind === 'team'), all = teams.every(n => S.collapsed.has(n.id));
  teams.forEach(n => { if (all) S.collapsed.delete(n.id); else S.collapsed.add(n.id); });
  ROOTS.forEach(r => S.collapsed.delete(r.id));
  syncFold(); relayout();
});

const navs = $$('.dbp-okr-navbtn');
const setView = v => {
  S.view = v;
  navs.forEach(b => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dbp-okr-view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'tree') relayout(); else renderTable();
};
navs.forEach(b => b.addEventListener('click', () => setView(b.dataset.view)));
$('.dbp-okr-nav').addEventListener('keydown', e => {
  const k = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const i = navs.indexOf(document.activeElement); if (i < 0) return;
  e.preventDefault(); const n = navs[(i + k + navs.length) % navs.length]; n.focus(); setView(n.dataset.view);
});

/* ---------- boot ---------- */
N.forEach(n => paintNode(n.id));
renderKpis(); renderTable();
let lastTW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = tscroll.clientWidth;
  if (w && w !== lastTW && S.view === 'tree') { const wasZero = !lastTW; lastTW = w; if (wasZero) first = true; relayout(); }
  const sp = drawer.querySelector('[data-spark]'); if (sp && S.sel) drawSpark(byId[S.sel]);
});
ro.observe(tscroll); ro.observe(drawer);
if (tscroll.clientWidth) { lastTW = tscroll.clientWidth; relayout(); }

css:
@keyframes dbp-cycle-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-cycle-grow { from { transform: scaleY(0); } }
@keyframes dbp-cycle-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbp-cycle-fade { from { opacity: 0; } }

.dbp-cycle {
  /* re-theme with these four */
  --dbp-cycle-paper: oklch(0.99 0.004 95);
  --dbp-cycle-ink: oklch(0.23 0.02 250);
  --dbp-cycle-accent: oklch(0.53 0.15 258);
  --dbp-cycle-hot: oklch(0.62 0.19 35);
  /* derived */
  --dbp-cycle-ochre: color-mix(in oklch, var(--dbp-cycle-hot), oklch(0.78 0.14 85) 70%);
  --dbp-cycle-slate: color-mix(in oklch, var(--dbp-cycle-ink) 42%, var(--dbp-cycle-paper));
  --dbp-cycle-card: color-mix(in oklch, var(--dbp-cycle-paper), white 60%);
  --dbp-cycle-sunk: color-mix(in oklch, var(--dbp-cycle-paper), var(--dbp-cycle-ink) 4%);
  --dbp-cycle-line: color-mix(in oklch, var(--dbp-cycle-ink) 9%, transparent);
  --dbp-cycle-line-2: color-mix(in oklch, var(--dbp-cycle-ink) 18%, transparent);
  --dbp-cycle-muted: color-mix(in oklch, var(--dbp-cycle-ink) 60%, var(--dbp-cycle-paper));
  --dbp-cycle-faint: color-mix(in oklch, var(--dbp-cycle-ink) 40%, var(--dbp-cycle-paper));
  --dbp-cycle-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-cycle-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-cycle-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-cycle-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-cycle-paper);
  color: var(--dbp-cycle-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-cycle-accent);
  box-shadow: inset 0 0 0 1px var(--dbp-cycle-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-cycle-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg, & canvas { display: block; }
  & [hidden] { display: none !important; }

  .dbp-cycle-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-cycle-muted); }

  .dbp-cycle-app { display: grid; height: 100%; grid-template-columns: 190px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-cycle-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; border-right: 1px solid var(--dbp-cycle-line); background: repeating-linear-gradient(0deg, transparent 0 23px, color-mix(in oklch, var(--dbp-cycle-accent) 9%, transparent) 23px 24px), var(--dbp-cycle-sunk); }
  .dbp-cycle-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-cycle-brand svg { width: 30px; height: 30px; padding: 4px; flex: none; border-radius: 8px; background: var(--dbp-cycle-card); box-shadow: inset 0 0 0 1.5px var(--dbp-cycle-ink); fill: var(--dbp-cycle-accent); stroke: var(--dbp-cycle-ink); stroke-width: 1.4; stroke-linecap: round; }
  .dbp-cycle-brand span { display: grid; line-height: 1.2; }
  .dbp-cycle-brand b { font-weight: 720; letter-spacing: -0.01em; }
  .dbp-cycle-brand small { font-size: 11px; color: var(--dbp-cycle-muted); }
  .dbp-cycle-nav { display: grid; gap: 2px; }
  .dbp-cycle-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-cycle-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-cycle-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-cycle-navbtn:hover { color: var(--dbp-cycle-ink); background: var(--dbp-cycle-line); }
  .dbp-cycle-navbtn[aria-current="page"] { color: var(--dbp-cycle-ink); background: var(--dbp-cycle-card); box-shadow: 0 0 0 1px var(--dbp-cycle-line-2); }
  .dbp-cycle-navbtn[aria-current="page"] svg { color: var(--dbp-cycle-accent); }
  .dbp-cycle-sle { margin-top: auto; display: grid; gap: 6px; padding: 12px; border-radius: 10px; background: var(--dbp-cycle-card); box-shadow: 0 0 0 1px var(--dbp-cycle-line-2); }
  .dbp-cycle-sle p { font-size: 12.5px; line-height: 1.45; }
  .dbp-cycle-sle b { font: 700 18px/1.1 var(--dbp-cycle-mono); color: var(--dbp-cycle-accent); letter-spacing: -0.03em; display: block; margin-bottom: 3px; }

  /* ---------- top ---------- */
  .dbp-cycle-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; }
  .dbp-cycle-title { display: grid; gap: 3px; }
  .dbp-cycle-h { font-size: clamp(19px, 0.95rem + 0.9cqi, 27px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; }
  .dbp-cycle-tools { display: flex; flex-wrap: wrap; gap: 8px; }
  .dbp-cycle-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbp-cycle-sunk); box-shadow: inset 0 0 0 1px var(--dbp-cycle-line); }
  .dbp-cycle-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dbp-cycle-muted); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbp-cycle-seg button:hover { color: var(--dbp-cycle-ink); }
  .dbp-cycle-seg button[aria-checked="true"] { color: var(--dbp-cycle-ink); background: var(--dbp-cycle-card); box-shadow: 0 1px 2px var(--dbp-cycle-line-2), 0 0 0 1px var(--dbp-cycle-line); }
  &:has(.dbp-cycle-view[data-view="velocity"]:not([hidden])) [data-group="scale"] { opacity: 0.35; pointer-events: none; }

  /* ---------- main ---------- */
  .dbp-cycle-main { grid-area: main; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 0 20px 18px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbp-cycle-line-2) transparent; }
  .dbp-cycle-view { min-height: 0; }
  .dbp-cycle-view > * { animation: dbp-cycle-rise 480ms var(--dbp-cycle-ease) both; animation-delay: calc(var(--i, 0) * 70ms); }
  .dbp-cycle-vcycle { display: grid; grid-template-columns: minmax(0, 1fr) 248px; gap: 12px; }
  .dbp-cycle-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbp-cycle-card); box-shadow: 0 0 0 1px var(--dbp-cycle-line), 0 1px 3px var(--dbp-cycle-line); }
  .dbp-cycle-aside { --i: 1; overflow: auto; scrollbar-width: thin; }
  .dbp-cycle-vpanel { height: 100%; }
