@keyframes dbp-release-flash { from { background-color: color-mix(in oklch, var(--dbp-release-go) 22%, transparent); } }
@keyframes dbp-release-scan { from { translate: -100% 0; } to { translate: 100% 0; } }
@keyframes dbp-release-stamp { 0% { opacity: 0; transform: rotate(-9deg) scale(1.6); filter: blur(6px); } 60% { opacity: 1; transform: rotate(-6deg) scale(0.96); filter: blur(0); } 100% { opacity: 1; transform: rotate(-6deg) scale(1); } }
@keyframes dbp-release-blink { 50% { opacity: 0.35; } }

.dbp-release {
  /* re-theme with these four */
  --dbp-release-bg: oklch(0.18 0.004 250);
  --dbp-release-ink: oklch(0.94 0.006 90);
  --dbp-release-go: oklch(0.8 0.17 150);
  --dbp-release-stop: oklch(0.67 0.2 25);
  /* derived */
  --dbp-release-hold: color-mix(in oklch, var(--dbp-release-go), var(--dbp-release-stop));
  --dbp-release-panel: color-mix(in oklch, var(--dbp-release-bg), var(--dbp-release-ink) 4.5%);
  --dbp-release-raised: color-mix(in oklch, var(--dbp-release-bg), var(--dbp-release-ink) 9%);
  --dbp-release-deep: color-mix(in oklch, var(--dbp-release-bg), black 30%);
  --dbp-release-line: color-mix(in oklch, var(--dbp-release-ink) 10%, transparent);
  --dbp-release-line-2: color-mix(in oklch, var(--dbp-release-ink) 20%, transparent);
  --dbp-release-muted: color-mix(in oklch, var(--dbp-release-ink) 60%, var(--dbp-release-bg));
  --dbp-release-faint: color-mix(in oklch, var(--dbp-release-ink) 38%, var(--dbp-release-bg));
  --dbp-release-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-release-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-release-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-release-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-release-bg);
  color: var(--dbp-release-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-release-go);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dbp-release-go); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-release-eyebrow { font: 600 10px/1.3 var(--dbp-release-mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--dbp-release-muted); }

  .dbp-release-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-release-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--dbp-release-deep); border-right: 1px solid var(--dbp-release-line); }
  .dbp-release-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-release-brand svg { width: 30px; height: 30px; padding: 4px; flex: none; border-radius: 8px; background: var(--dbp-release-ink); fill: none; stroke: var(--dbp-release-deep); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-release-brand span { display: grid; line-height: 1.2; }
  .dbp-release-brand b { font-weight: 720; letter-spacing: -0.01em; }
  .dbp-release-brand small { font-size: 11px; color: var(--dbp-release-muted); }
  .dbp-release-nav { display: grid; gap: 2px; }
  .dbp-release-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-release-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-release-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-release-navbtn:hover { color: var(--dbp-release-ink); background: var(--dbp-release-line); }
  .dbp-release-navbtn[aria-current="page"] { color: var(--dbp-release-ink); background: var(--dbp-release-raised); box-shadow: inset 2px 0 0 var(--dbp-release-go); }
  .dbp-release-badge { margin-left: auto; min-width: 20px; height: 18px; padding: 0 6px; display: grid; place-items: center; border-radius: 5px; font: 700 10.5px var(--dbp-release-mono); font-style: normal; color: var(--dbp-release-deep); background: var(--dbp-release-stop); transition: background-color 300ms; }
  .dbp-release-badge[data-zero] { background: var(--dbp-release-go); }
  .dbp-release-card { margin-top: auto; display: grid; gap: 6px; padding: 12px; border-radius: 10px; background: var(--dbp-release-panel); box-shadow: inset 0 0 0 1px var(--dbp-release-line); }
  .dbp-release-card > b { font-size: 12.5px; font-weight: 650; }
  .dbp-release-card small { font-size: 11px; color: var(--dbp-release-muted); line-height: 1.4; }
  .dbp-release-count { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; }
  .dbp-release-count span { display: grid; place-items: center; padding: 6px 0 4px; border-radius: 6px; background: var(--dbp-release-deep); font: 700 17px/1 var(--dbp-release-mono); font-variant-numeric: tabular-nums; letter-spacing: -0.04em; }
  .dbp-release-count span small { font: 600 8.5px var(--dbp-release-mono); letter-spacing: 0.12em; color: var(--dbp-release-faint); margin-top: 3px; }

  /* ---------- top ---------- */
  .dbp-release-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; }
  .dbp-release-title { display: grid; gap: 4px; }
  .dbp-release-h { font-size: clamp(19px, 0.95rem + 0.9cqi, 27px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; }
  .dbp-release-h em { font-style: normal; color: var(--dbp-release-muted); font-weight: 520; }
  .dbp-release-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbp-release-deep); box-shadow: inset 0 0 0 1px var(--dbp-release-line); }
  .dbp-release-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font: 600 11px var(--dbp-release-mono); letter-spacing: 0.04em; text-transform: uppercase; color: var(--dbp-release-muted); transition: color 150ms, background-color 150ms; }
  .dbp-release-seg button:hover { color: var(--dbp-release-ink); }
  .dbp-release-seg button[aria-checked="true"] { color: var(--dbp-release-deep); background: var(--dbp-release-ink); }

  /* ---------- main ---------- */
  .dbp-release-main { grid-area: main; min-height: 0; overflow: auto; padding: 0 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dbp-release-line-2) transparent; }
  .dbp-release-view { height: 100%; }
  .dbp-release-view > * { animation: dbp-release-rise 480ms var(--dbp-release-ease) both; animation-delay: calc(var(--i, 0) * 70ms); }
  .dbp-release-vcheck { display: grid; grid-template-columns: 296px minmax(0, 1fr); gap: 12px; }
  .dbp-release-panel { position: relative; min-width: 0; min-height: 0; border-radius: 12px; background: var(--dbp-release-panel); box-shadow: inset 0 0 0 1px var(--dbp-release-line); }
  .dbp-release-full { height: 100%; display: flex; flex-direction: column; overflow: hidden; }
  .dbp-release-ph { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 14px; padding: 14px 16px 8px; }
  .dbp-release-ph h3 { font-size: 13.5px; font-weight: 680; margin-right: auto; }
  .dbp-release-ph small { font: 600 11px var(--dbp-release-mono); color: var(--dbp-release-muted); }

  /* ---------- dial ---------- */
  .dbp-release-dialp { display: flex; flex-direction: column; gap: 14px; padding: 16px; overflow: auto; scrollbar-width: thin; }
  .dbp-release-dial { position: relative; width: min(100%, 220px); aspect-ratio: 1; margin: 0 auto; }
  .dbp-release-dial svg { width: 100%; height: 100%; overflow: visible; }
  .dbp-release-track { fill: none; stroke: var(--dbp-release-line); stroke-width: 14; }
  .dbp-release-arc { fill: none; stroke-width: 14; stroke: var(--c); stroke-dasharray: calc(var(--f) * 100) 100; transition: stroke-dasharray 900ms var(--dbp-release-spring), stroke 300ms, opacity 200ms; cursor: pointer; @starting-style { stroke-dasharray: 0 100; } }
  .dbp-release-arc[data-s="go"] { --c: var(--dbp-release-go); }
  .dbp-release-arc[data-s="hold"] { --c: var(--dbp-release-hold); }
  .dbp-release-arc[data-s="stop"] { --c: var(--dbp-release-stop); }
  .dbp-release-dial[data-hover] .dbp-release-arc:not([data-on]) { opacity: 0.35; }
  .dbp-release-ticks line { stroke: var(--dbp-release-line-2); stroke-width: 1; }
  .dbp-release-glabel { font: 600 8.5px var(--dbp-release-mono); letter-spacing: 0.1em; fill: var(--dbp-release-faint); text-transform: uppercase; }
  .dbp-release-center { position: absolute; inset: 22%; display: grid; place-content: center; justify-items: center; gap: 2px; text-align: center; pointer-events: none; }
  .dbp-release-center b { font: 700 40px/1 var(--dbp-release-mono); letter-spacing: -0.06em; font-variant-numeric: tabular-nums; }
  .dbp-release-center b::after { content: "%"; font-size: 0.45em; letter-spacing: 0; color: var(--dbp-release-muted); margin-left: 2px; }
  .dbp-release-center span { font: 600 10px var(--dbp-release-mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--dbp-release-muted); }
  .dbp-release-verdict { margin-top: 6px; padding: 3px 9px; border-radius: 5px; font: 700 11px var(--dbp-release-mono); font-style: normal; letter-spacing: 0.1em; color: var(--dbp-release-deep); background: var(--dbp-release-stop); transition: background-color 400ms; white-space: nowrap; }
  .dbp-release-verdict[data-go] { background: var(--dbp-release-go); }
  .dbp-release-dtip { position: absolute; z-index: 3; left: 50%; top: -6px; translate: -50% -100%; width: 200px; padding: 8px 10px; border-radius: 9px; background: var(--dbp-release-ink); color: var(--dbp-release-deep); font-size: 12px; pointer-events: none; transition: opacity 120ms; @starting-style { opacity: 0; } }
  .dbp-release-dtip b { display: block; font-weight: 700; }
  .dbp-release-gates { display: grid; gap: 2px; }
  .dbp-release-gbtn { width: 100%; display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 9px; align-items: center; padding: 6px 8px; border-radius: 7px; text-align: left; font-size: 12.5px; transition: background-color 150ms; }
  .dbp-release-gbtn:hover, .dbp-release-gbtn[aria-pressed="true"] { background: var(--dbp-release-line); }
  .dbp-release-gbtn i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  .dbp-release-gbtn span { font: 600 11.5px var(--dbp-release-mono); color: var(--dbp-release-muted); font-variant-numeric: tabular-nums; }
  .dbp-release-gbtn[data-s="go"] { --c: var(--dbp-release-go); }
  .dbp-release-gbtn[data-s="hold"] { --c: var(--dbp-release-hold); }
  .dbp-release-gbtn[data-s="stop"] { --c: var(--dbp-release-stop); }
  .dbp-release-sign { display: grid; gap: 8px; padding-top: 12px; border-top: 1px solid var(--dbp-release-line); }
  .dbp-release-signers { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; }
  .dbp-release-signer { position: relative; display: grid; justify-items: center; gap: 3px; padding: 4px 0; border-radius: 8px; font: 600 9.5px var(--dbp-release-mono); letter-spacing: 0.06em; color: var(--dbp-release-faint); text-transform: uppercase; transition: background-color 150ms, color 150ms; }
  .dbp-release-signer:hover:not(:disabled) { background: var(--dbp-release-line); color: var(--dbp-release-ink); }
  .dbp-release-signer:disabled { opacity: 0.5; }
  .dbp-release-signer i { position: relative; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; font: 650 10.5px system-ui, sans-serif; font-style: normal; letter-spacing: 0; color: var(--dbp-release-ink); background: var(--dbp-release-raised); box-shadow: inset 0 0 0 1.5px var(--dbp-release-line-2); transition: box-shadow 250ms, background-color 250ms; }
  .dbp-release-signer[aria-pressed="true"] i { box-shadow: inset 0 0 0 2px var(--dbp-release-go); }
  .dbp-release-signer[aria-pressed="true"] i::after { content: ""; position: absolute; right: -3px; bottom: -3px; width: 13px; height: 13px; border-radius: 50%; background: var(--dbp-release-go) no-repeat center / 8px; box-shadow: 0 0 0 2px var(--dbp-release-panel); }
  .dbp-release-signer[aria-pressed="true"] i::before { content: ""; position: absolute; z-index: 1; right: 1px; bottom: 1.5px; width: 3px; height: 6px; border: solid var(--dbp-release-deep); border-width: 0 1.5px 1.5px 0; rotate: 45deg; }
  .dbp-release-signer[aria-pressed="true"] { color: var(--dbp-release-go); }
  .dbp-release-ship { position: relative; overflow: hidden; height: 42px; border-radius: 10px; font: 700 12px var(--dbp-release-mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--dbp-release-deep); background: var(--dbp-release-go); transition: opacity 200ms, transform 220ms var(--dbp-release-spring), filter 200ms; }
  .dbp-release-ship:disabled { opacity: 1; color: var(--dbp-release-faint); background: repeating-linear-gradient(135deg, var(--dbp-release-line) 0 8px, transparent 8px 16px), var(--dbp-release-deep); box-shadow: inset 0 0 0 1px var(--dbp-release-line-2); }
  .dbp-release-ship:not(:disabled):hover { filter: brightness(1.08); }
  .dbp-release-ship:not(:disabled):active { transform: scale(0.97); }
  .dbp-release-ship:not(:disabled)::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent, color-mix(in oklch, white 45%, transparent), transparent); animation: dbp-release-scan 1800ms var(--dbp-release-ease) infinite; }
  .dbp-release-ship span { position: relative; }

  /* ---------- checklist ---------- */
  .dbp-release-listp { --i: 1; display: flex; flex-direction: column; overflow: hidden; }
  .dbp-release-lscroll { flex: 1; min-height: 0; overflow: auto; padding: 6px 8px 12px; scrollbar-width: thin; scrollbar-color: var(--dbp-release-line-2) transparent; }
  .dbp-release-group { padding: 4px 0; }
  .dbp-release-group + .dbp-release-group { border-top: 1px solid var(--dbp-release-line); }
  .dbp-release-gh { position: sticky; top: -6px; z-index: 2; width: 100%; display: grid; grid-template-columns: 14px minmax(0, 1fr) 90px auto; gap: 10px; align-items: center; padding: 9px 10px; border-radius: 8px; text-align: left; background: var(--dbp-release-panel); }
  .dbp-release-gh:hover { background: color-mix(in oklch, var(--dbp-release-panel), var(--dbp-release-ink) 4%); }
  .dbp-release-gh svg { width: 14px; height: 14px; fill: none; stroke: var(--dbp-release-muted); stroke-width: 2; stroke-linecap: round; transition: rotate 260ms var(--dbp-release-spring); }
  .dbp-release-gh[aria-expanded="false"] svg { rotate: -90deg; }
  .dbp-release-gh b { font-size: 13px; font-weight: 680; }
  .dbp-release-gh b small { margin-left: 8px; font: 500 11.5px system-ui, sans-serif; color: var(--dbp-release-muted); }
  .dbp-release-gh > span { font: 600 11px var(--dbp-release-mono); color: var(--dbp-release-muted); font-variant-numeric: tabular-nums; }
  .dbp-release-meter { height: 5px; border-radius: 99px; background: var(--dbp-release-line); overflow: hidden; }
  .dbp-release-meter i { display: block; height: 100%; width: 100%; border-radius: inherit; background: var(--c); transform-origin: left; transform: scaleX(var(--f)); transition: transform 700ms var(--dbp-release-spring), background-color 300ms; }
  .dbp-release-items { display: grid; gap: 2px; padding: 0 0 6px 24px; }
  .dbp-release-item { --c: var(--dbp-release-faint); display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 2px 10px; align-items: start; padding: 9px 10px; border-radius: 9px; transition: background-color 200ms; }
  .dbp-release-item:hover { background: color-mix(in oklch, var(--dbp-release-ink) 3%, transparent); }
  .dbp-release-item[data-flash] { animation: dbp-release-flash 900ms ease-out; }
  .dbp-release-item[data-s="pass"] { --c: var(--dbp-release-go); }
  .dbp-release-item[data-s="fail"] { --c: var(--dbp-release-stop); }
  .dbp-release-item[data-s="waived"] { --c: var(--dbp-release-hold); }
  .dbp-release-item[data-s="pending"] { --c: var(--dbp-release-muted); }
  .dbp-release-mark { width: 18px; height: 18px; margin-top: 1px; display: grid; place-items: center; border-radius: 5px; box-shadow: inset 0 0 0 1.5px var(--c); color: var(--dbp-release-deep); }
  .dbp-release-mark svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-release-item[data-s="pass"] .dbp-release-mark, .dbp-release-item[data-s="fail"] .dbp-release-mark, .dbp-release-item[data-s="waived"] .dbp-release-mark { background: var(--c); }
  .dbp-release-item input[type="checkbox"] { width: 18px; height: 18px; margin: 1px 0 0; cursor: pointer; }
  .dbp-release-it { display: grid; gap: 3px; min-width: 0; }
  .dbp-release-it b { font-weight: 580; line-height: 1.3; }
  .dbp-release-item[data-s="waived"] .dbp-release-it b { text-decoration: line-through; text-decoration-color: var(--dbp-release-hold); text-decoration-thickness: 1.5px; }
  .dbp-release-it small { font-size: 11.5px; color: var(--dbp-release-muted); }
  .dbp-release-it small code { font: 11px var(--dbp-release-mono); color: var(--dbp-release-ink); }
  .dbp-release-tags { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
  .dbp-release-tag { padding: 1px 6px; border-radius: 4px; font: 600 9.5px var(--dbp-release-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbp-release-muted); box-shadow: inset 0 0 0 1px var(--dbp-release-line-2); }
  .dbp-release-tag[data-k="req"] { color: var(--dbp-release-ink); }
  .dbp-release-tag[data-k="s"] { color: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent); }
  .dbp-release-bullet { position: relative; height: 8px; margin-top: 4px; border-radius: 2px; background: var(--dbp-release-line); max-width: 300px; }
  .dbp-release-bullet i { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; border-radius: 2px; background: var(--c); transform-origin: left; transform: scaleX(var(--v)); transition: transform 800ms var(--dbp-release-spring), background-color 300ms; @starting-style { transform: scaleX(0); } }
  .dbp-release-bullet u { position: absolute; top: -4px; bottom: -4px; left: calc(var(--t) * 100%); width: 2px; margin-left: -1px; background: var(--dbp-release-ink); }
  .dbp-release-bullet[data-run] i { background: linear-gradient(90deg, var(--dbp-release-line-2), var(--dbp-release-ink), var(--dbp-release-line-2)); background-size: 200% 100%; animation: dbp-release-blink 600ms ease-in-out infinite; }
  .dbp-release-acts { display: flex; gap: 6px; align-self: center; }
  .dbp-release-act { height: 26px; padding: 0 9px; border-radius: 7px; font: 600 10.5px var(--dbp-release-mono); letter-spacing: 0.05em; text-transform: uppercase; color: var(--dbp-release-muted); box-shadow: inset 0 0 0 1px var(--dbp-release-line-2); white-space: nowrap; transition: color 150ms, background-color 150ms, transform 200ms var(--dbp-release-spring); }
  .dbp-release-act:hover:not(:disabled) { color: var(--dbp-release-ink); background: var(--dbp-release-line); }
  .dbp-release-act:active:not(:disabled) { transform: scale(0.95); }
  .dbp-release-act:disabled { opacity: 0.45; }
  .dbp-release-waive { grid-column: 2 / -1; display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
  .dbp-release-waive input { flex: 1 1 180px; min-width: 0; height: 30px; padding: 0 10px; border: 0; border-radius: 7px; background: var(--dbp-release-deep); box-shadow: inset 0 0 0 1px var(--dbp-release-line-2); font-size: 12px; }
  .dbp-release-waive input:focus-visible { outline-offset: 0; }
  .dbp-release-empty { padding: 30px 16px; text-align: center; font-size: 12.5px; color: var(--dbp-release-faint); }

  /* ---------- blockers ---------- */
  .dbp-release-blist { flex: 1; min-height: 0; overflow: auto; padding: 4px 16px 16px; counter-reset: dbp-release-b; scrollbar-width: thin; }
  .dbp-release-b { counter-increment: dbp-release-b; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 4px 12px; align-items: start; padding: 14px 0; border-bottom: 1px solid var(--dbp-release-line); animation: dbp-release-rise 420ms var(--dbp-release-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbp-release-b::before { content: counter(dbp-release-b, decimal-leading-zero); font: 700 15px var(--dbp-release-mono); color: var(--dbp-release-stop); }
  .dbp-release-b[data-s="pending"]::before { color: var(--dbp-release-hold); }
  .dbp-release-b b { font-weight: 620; }
  .dbp-release-b p { grid-column: 2; font-size: 12px; color: var(--dbp-release-muted); }
  .dbp-release-b .dbp-release-act { grid-row: span 2; align-self: center; }
  .dbp-release-clear { display: grid; place-items: center; gap: 8px; padding: 50px 16px; text-align: center; color: var(--dbp-release-muted); }
