const ITEMS = [
  { id: 'q1', g: 'qa', t: 'Regression suite pass rate', req: 1, m: { v: 99.4, th: 99, dir: 'min', u: '%', dp: 1, lo: 97, hi: 100 }, note: '4,212 of 4,237 cases on rc.3' },
