  { id: 's3', g: 'sec', t: 'Code-signing certificate validity', req: 1, m: { v: 214, th: 90, dir: 'min', u: ' days', dp: 0, lo: 0, hi: 365 }, note: 'Renewed Mar 4, 2027 expiry' },
