  { id: 'o3', g: 'ops', t: 'Experiment flags default to off', req: 1, s: 'pass', note: 'Three flags: smart-titles, inline-ai, tab-groups' },
  { id: 'o4', g: 'ops', t: 'On-call staffed for 72 h after release', req: 1, s: 'pass', note: 'Kenji, Ama and Lukas cover Tue–Fri; Thursday night confirmed' },
  { id: 'l1', g: 'loc', t: 'Locales fully translated', req: 1, m: { v: 13, th: 14, dir: 'min', u: ' of 14', dp: 0, lo: 0, hi: 14 }, next: 14, note: 'Korean at 96%, 41 strings left with the vendor' },
