  dtip.innerHTML = `<b>${G.name} · ${Math.round(gateFrac(g) * 100)}%</b>${open.length ? `${open.length} not clear: ${open.map(i => esc(i.t)).slice(0, 2).join('; ')}${open.length > 2 ? '…' : ''}` : 'All items clear'}`;
