    const its = visibleItems(g.id), all = gateItems(g.id), c = all.filter(clear).length, open = !S.collapsed.has(g.id);
    if (!its.length && S.show !== 'all') return '';
    return `<section class="dbp-release-group" data-group-id="${g.id}"><button class="dbp-release-gh" data-fold="${g.id}" aria-expanded="${open}" style="--c:var(--dbp-release-${gateState(g.id)})"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg><b>${g.name}<small>${g.owner}</small></b><div class="dbp-release-meter" aria-hidden="true"><i style="--f:${gateFrac(g.id).toFixed(3)}"></i></div><span>${c} of ${all.length} clear</span></button>${open ? `<ul class="dbp-release-items">${its.map(itemHtml).join('')}</ul>` : ''}</section>`;
  }).join('');
  listEl.innerHTML = html || `<p class="dbp-release-empty">Nothing ${S.show === 'open' ? 'left to clear' : 'to show'} here.</p>`;
  const nd = listEl.querySelector('[data-reason]');
  if (nd && keep) { nd.value = keep.v; nd.form.querySelector('[data-wok]').disabled = keep.v.trim().length < 8; if (keep.f) { nd.focus({ preventScroll: true }); nd.setSelectionRange(keep.s, keep.s); } }
};
const flash = id => { const li = listEl.querySelector(`[data-id="${id}"]`); if (li && !reduce) { li.removeAttribute('data-flash'); void li.offsetWidth; li.setAttribute('data-flash', ''); } };
const refocus = sel => { const el = listEl.querySelector(sel); if (el) el.focus(); };
const update = (id, focusSel) => { renderSummary(); renderList(); renderBlockers(); if (S.view === 'hist') drawHist(); if (id) flash(id); if (focusSel) refocus(focusSel); };
listEl.addEventListener('change', e => {
  const c = e.target.closest('[data-check]'); if (!c) return;
  const i = byId[c.dataset.check]; i.s = c.checked ? 'pass' : 'pending';
  update(i.id, `[data-check="${i.id}"]`);
});
listEl.addEventListener('click', e => {
  const t = e.target;
  const fold = t.closest('[data-fold]');
  if (fold) { const g = fold.dataset.fold; if (S.collapsed.has(g)) S.collapsed.delete(g); else S.collapsed.add(g); renderList(); refocus(`[data-fold="${g}"]`); return; }
  const rr = t.closest('[data-rerun]');
  if (rr) {
    const i = byId[rr.dataset.rerun]; S.running.add(i.id); renderList(); refocus(`[data-rerun="${i.id}"]`);
    setTimeout(() => {
      if (!root.isConnected) return;
      S.running.delete(i.id);
      if (i.next != null) { i.m.v = i.next; if (i.id === 'q2' && i.m.v === 0) i.note = '<code>WREN-8812</code> fixed in rc.4, verified on Windows ARM'; if (i.id === 'p1') i.note = 'Re-measured on rc.4 after the font-cache fix, 30 runs'; if (i.id === 'l1') i.note = 'Korean delivered by the vendor this morning'; if (i.id === 's2') i.note = 'Still open: CSP header on the help viewer; verbose error from the updater'; }
      update(i.id, `[data-rerun="${i.id}"]`);
    }, reduce ? 300 : 1400);
    return;
  }
  const wv = t.closest('[data-waive]');
  if (wv) { S.waiving = wv.dataset.waive; renderList(); refocus('[data-reason]'); return; }
  if (t.closest('[data-wcancel]')) { const id = S.waiving; S.waiving = null; renderList(); refocus(`[data-waive="${id}"]`); return; }
  const uw = t.closest('[data-unwaive]');
  if (uw) { const i = byId[uw.dataset.unwaive]; delete i.waived; update(i.id, `[data-waive="${i.id}"], [data-check="${i.id}"]`); }
});
listEl.addEventListener('input', e => { if (e.target.matches('[data-reason]')) { const ok = e.target.value.trim().length >= 8; e.target.form.querySelector('[data-wok]').disabled = !ok; } });
listEl.addEventListener('submit', e => {
  e.preventDefault();
  const f = e.target.closest('[data-wform]'); if (!f) return;
  const reason = f.querySelector('[data-reason]').value.trim(); if (reason.length < 8) return;
  const i = byId[f.dataset.wform]; i.waived = reason; S.waiving = null;
  update(i.id, `[data-unwaive="${i.id}"]`);
});
listEl.addEventListener('keydown', e => { if (e.key === 'Escape' && S.waiving) { const id = S.waiving; S.waiving = null; renderList(); refocus(`[data-waive="${id}"]`); } });

/* ---------- blockers view ---------- */
const renderBlockers = () => {
  const bl = blockers().sort((a, b) => (status(a) === 'fail' ? 0 : 1) - (status(b) === 'fail' ? 0 : 1));
  const fails = bl.filter(i => status(i) === 'fail').length;
  $('[data-bsum]').textContent = bl.length ? `${fails} failing · ${bl.length - fails} open` : 'none';
  $('[data-blist]').innerHTML = bl.length ? bl.map((i, n) => { const g = GATES.find(x => x.id === i.g); return `<li class="dbp-release-b" data-s="${status(i)}" style="--i:${n}"><b>${esc(i.t)}</b><button class="dbp-release-act" data-goto="${i.id}">Open</button><p>${g.name} · ${g.owner} · ${i.m ? `${fmt(i.m)} against ${fmtTh(i.m)}` : 'not done yet'} — ${i.note}</p></li>`; }).join('')
    : `<li class="dbp-release-clear"><b>ALL CLEAR</b><span>Every required item has passed or been waived. Collect the remaining sign-offs to approve.</span></li>`;
};
$('[data-blist]').addEventListener('click', e => {
  const b = e.target.closest('[data-goto]'); if (!b) return;
  const i = byId[b.dataset.goto];
  S.gate = null; S.show = 'all'; S.collapsed.delete(i.g);
  $$('[data-group="show"] [role="radio"]').forEach(x => { x.setAttribute('aria-checked', String(x.dataset.v === 'all')); x.tabIndex = x.dataset.v === 'all' ? 0 : -1; });
  setView('check'); renderSummary(); renderList();
  const li = listEl.querySelector(`[data-id="${i.id}"]`);
  if (li) { li.scrollIntoView({ block: 'center', behavior: reduce ? 'auto' : 'smooth' }); flash(i.id); const f = li.querySelector('button, input'); if (f) f.focus({ preventScroll: true }); }
});

/* ---------- history view ---------- */
const HIST = [
  { v: '4.0', c: 'var(--dbp-release-faint)', d: [22, 26, 31, 35, 40, 44, 49, 55, 61, 66, 72, 80, 88, 95, 100], old: true },
  { v: '4.1', c: 'var(--dbp-release-muted)', d: [18, 20, 25, 27, 30, 36, 42, 47, 50, 54, 63, 71, 79, 92, 100], old: true },
  { v: '4.2', c: 'var(--dbp-release-go)', d: [20, 24, 27, 33, 38, 41, 45, 48, 52, 57] }
];
const hist = $('[data-hist]'), hsvg = $('[data-hsvg]'), htip = $('[data-htip]');
let hGeo = null, hDay = null;
$('[data-hkey]').innerHTML = HIST.map(h => `<span><i style="--c:${h.c}"></i>${h.v}${h.old ? ' (shipped)' : ' (this release)'}</span>`).join('');
const series = h => h.old ? h.d : [...h.d, Math.round(readiness() * 100)];
const drawHist = () => {
  const W = hist.clientWidth, H = hist.clientHeight; if (!W) return;
  const m = { l: 40, r: 40, t: 14, b: 26 }, iw = W - m.l - m.r, ih = H - m.t - m.b;
  const x = k => m.l + k / 14 * iw, y = v => m.t + ih - v / 100 * ih;
  let s = '';
  for (let v = 0; v <= 100; v += 25) s += `<line class="dbp-release-gl" x1="${m.l}" x2="${W - m.r}" y1="${Math.round(y(v)) + 0.5}" y2="${Math.round(y(v)) + 0.5}"/><text x="${m.l - 8}" y="${y(v) + 3.5}" text-anchor="end">${v}%</text>`;
  for (let k = 0; k <= 14; k += W < 420 ? 2 : 1) s += `<text x="${x(k).toFixed(1)}" y="${H - 6}" text-anchor="middle">${k === 14 ? 'T0' : `T−${14 - k}`}</text>`;
  s += `<line x1="${x(10)}" x2="${x(10)}" y1="${m.t}" y2="${m.t + ih}" style="stroke:var(--dbp-release-go);stroke-dasharray:2 4;opacity:.6"/><text x="${x(10) + 6}" y="${m.t + 10}" style="fill:var(--dbp-release-go)">today</text>`;
  HIST.forEach((h, n) => {
    const d = series(h);
    s += `<path class="dbp-release-ln"${h.old ? ' data-old' : ''} pathLength="1" style="--c:${h.c};--i:${n}" d="${d.map((v, k) => `${k ? 'L' : 'M'}${x(k).toFixed(1)},${y(v).toFixed(1)}`).join('')}"/>`;
    s += `<text x="${(x(d.length - 1) + 6).toFixed(1)}" y="${(y(d[d.length - 1]) + 4).toFixed(1)}" style="fill:${h.c};font-weight:650">${h.v}</text>`;
  });
  s += `<g data-xh style="display:none"><line class="dbp-release-xh" y1="${m.t}" y2="${m.t + ih}"/>${HIST.map(h => `<circle r="4" style="fill:${h.c}"/>`).join('')}</g>`;
  hsvg.setAttribute('viewBox', `0 0 ${W} ${H}`); hsvg.innerHTML = s;
  hGeo = { x, y, m, iw };
  const now = series(HIST[2]), at = HIST[1].d[10], diff = now[10] - at;
  $('[data-hnote]').innerHTML = `At T−4, 4.2 stands at <b>${now[10]}%</b> — ${diff >= 0 ? `${diff} points ahead of` : `${-diff} points behind`} 4.1 on the same day (${at}%). 4.1 still shipped on time after clearing ${100 - at} points in four days.`;
  hist.setAttribute('aria-label', `Readiness by day for releases 4.0, 4.1 and 4.2. ${$('[data-hnote]').textContent} Arrow keys read each day.`);
  if (hDay != null) histAt(hDay);
};
const histAt = k => {
  hDay = k; const g = hsvg.querySelector('[data-xh]');
  if (k == null || !hGeo) { if (g) g.style.display = 'none'; htip.hidden = true; return; }
  g.style.display = '';
  const X = hGeo.x(k); g.querySelector('line').setAttribute('x1', X); g.querySelector('line').setAttribute('x2', X);
  const cs = g.querySelectorAll('circle');
  HIST.forEach((h, n) => { const d = series(h); const c = cs[n]; if (k < d.length) { c.style.display = ''; c.setAttribute('cx', X); c.setAttribute('cy', hGeo.y(d[k])); } else c.style.display = 'none'; });
  htip.innerHTML = `<b>${k === 14 ? 'Release day' : `${14 - k} day${14 - k === 1 ? '' : 's'} before release`}</b>${HIST.map(h => { const d = series(h); return `<div><span style="--c:${h.c}">${h.v}</span><em>${k < d.length ? d[k] + '%' : '—'}</em></div>`; }).join('')}`;
  htip.hidden = false;
  const tw = htip.offsetWidth;
  htip.style.left = (X + 14 + tw > hist.clientWidth ? X - 14 - tw : X + 14) + 'px';
};
hist.addEventListener('pointermove', e => { if (!hGeo) return; const r = hist.getBoundingClientRect(); histAt(clamp(Math.round((e.clientX - r.left - hGeo.m.l) / hGeo.iw * 14), 0, 14)); });
hist.addEventListener('pointerleave', () => histAt(null));
hist.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); histAt(clamp((hDay ?? (e.key === 'ArrowRight' ? -1 : 15)) + (e.key === 'ArrowRight' ? 1 : -1), 0, 14)); }
  else if (e.key === 'Escape') histAt(null);
});
hist.addEventListener('blur', () => histAt(null));

/* ---------- ship ---------- */
const stamp = $('[data-stamp]');
$('[data-ship]').addEventListener('click', () => {
  if (!isGo()) return;
  S.shipped = true; renderSummary();
  stamp.innerHTML = `<b>CLEARED FOR RELEASE</b><span>4.2.0 · Tue Oct 6, 14:00 UTC · first ring 1%</span><span>Signed by ${GATES.map(g => g.ini).join(' · ')}</span><button data-revoke>Revoke approval</button>`;
  stamp.hidden = false; stamp.querySelector('[data-revoke]').focus();
});
stamp.addEventListener('click', e => { if (e.target.closest('[data-revoke]')) { S.shipped = false; stamp.hidden = true; renderSummary(); $('[data-ship]').focus(); } });
root.addEventListener('keydown', e => { if (e.key === 'Escape' && !stamp.hidden) { stamp.hidden = true; $('[data-ship]').focus(); } });

/* ---------- countdown: a fixed snapshot time plus real elapsed seconds ---------- */
const SNAP = Date.UTC(2026, 9, 2, 10, 40, 0), WINDOW = Date.UTC(2026, 9, 6, 14, 0, 0), mounted = Date.now();
const countEl = $('[data-count]');
countEl.innerHTML = ['d', 'h', 'm', 's'].map(u => `<span data-u="${u}">00<small>${{ d: 'DAYS', h: 'HRS', m: 'MIN', s: 'SEC' }[u]}</small></span>`).join('');
const cells = {}; $$('[data-u]', countEl).forEach(c => { cells[c.dataset.u] = c.firstChild; });
const tickCount = () => {
  let s = Math.max(0, Math.floor((WINDOW - SNAP - (Date.now() - mounted)) / 1000));
  const d = Math.floor(s / 86400); s -= d * 86400; const h = Math.floor(s / 3600); s -= h * 3600; const m = Math.floor(s / 60); s -= m * 60;
  [['d', d], ['h', h], ['m', m], ['s', s]].forEach(([u, v]) => { const t = String(v).padStart(2, '0'); if (cells[u].nodeValue !== t) cells[u].nodeValue = t; });
};
tickCount();
let onScreen = true;
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); return; }
  if (!onScreen || document.hidden) return;
  tickCount();
}, 1000);
const io = new IntersectionObserver(es => {
  if (!root.isConnected) { io.disconnect(); return; }
  onScreen = es[0].isIntersecting; root.toggleAttribute('data-off', !onScreen);
  if (onScreen) tickCount();
});
io.observe(root);

/* ---------- controls ---------- */
const seg = (name, fn) => {
  const g = $(`[data-group="${name}"]`), bs = $$('[role="radio"]', g);
  const sync = () => bs.forEach(b => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
  const pick = (b, focus) => { bs.forEach(x => x.setAttribute('aria-checked', String(x === b))); sync(); if (focus) b.focus(); fn(b.dataset.v); };
  g.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  g.addEventListener('keydown', e => { const k = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key]; if (!k) return; e.preventDefault(); const i = bs.findIndex(b => b.getAttribute('aria-checked') === 'true'); pick(bs[(i + k + bs.length) % bs.length], true); });
  sync();
};
seg('show', v => { S.show = v; renderList(); });
const navs = $$('.dbp-release-navbtn');
const setView = v => {
  S.view = v;
  navs.forEach(b => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dbp-release-view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'hist') drawHist();
};
navs.forEach(b => b.addEventListener('click', () => setView(b.dataset.view)));
$('.dbp-release-nav').addEventListener('keydown', e => {
  const k = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const i = navs.indexOf(document.activeElement); if (i < 0) return;
  e.preventDefault(); const n = navs[(i + k + navs.length) % navs.length]; n.focus(); setView(n.dataset.view);
});
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } if (S.view === 'hist') drawHist(); });
ro.observe(hist);

renderSummary(); renderList(); renderBlockers();

css:
@keyframes dbp-forecast-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-forecast-fade { from { opacity: 0; } }
@keyframes dbp-forecast-grow { from { transform: scaleY(0); } }
@keyframes dbp-forecast-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }

.dbp-forecast {
  /* re-theme with these four */
  --dbp-forecast-bg: oklch(0.21 0.02 45);
  --dbp-forecast-ink: oklch(0.94 0.022 80);
  --dbp-forecast-accent: oklch(0.76 0.13 42);
  --dbp-forecast-mint: oklch(0.83 0.11 168);
  /* derived */
  --dbp-forecast-panel: color-mix(in oklch, var(--dbp-forecast-bg), var(--dbp-forecast-ink) 5%);
  --dbp-forecast-raised: color-mix(in oklch, var(--dbp-forecast-bg), var(--dbp-forecast-ink) 10%);
  --dbp-forecast-deep: color-mix(in oklch, var(--dbp-forecast-bg), black 28%);
  --dbp-forecast-line: color-mix(in oklch, var(--dbp-forecast-ink) 10%, transparent);
  --dbp-forecast-line-2: color-mix(in oklch, var(--dbp-forecast-ink) 20%, transparent);
  --dbp-forecast-muted: color-mix(in oklch, var(--dbp-forecast-ink) 62%, var(--dbp-forecast-bg));
  --dbp-forecast-faint: color-mix(in oklch, var(--dbp-forecast-ink) 40%, var(--dbp-forecast-bg));
  --dbp-forecast-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-forecast-spring: linear(0, 0.02, 0.08 4%, 0.32 9%, 0.78 17%, 0.98 22%, 1.06 27%, 1.07 31%, 1.04 37%, 1.01 45%, 0.995 55%, 1);
  --dbp-forecast-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-forecast-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: radial-gradient(90% 70% at 0% 100%, color-mix(in oklch, var(--dbp-forecast-accent) 8%, transparent), transparent 70%), var(--dbp-forecast-bg);
  color: var(--dbp-forecast-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-forecast-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-forecast-mint); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-forecast-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-forecast-muted); text-wrap: balance; }

  .dbp-forecast-app { display: grid; height: 100%; grid-template-columns: 190px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }

  /* ---------- sidebar ---------- */
  .dbp-forecast-side { grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: color-mix(in oklch, var(--dbp-forecast-deep) 70%, transparent); border-right: 1px solid var(--dbp-forecast-line); }
  .dbp-forecast-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbp-forecast-brand svg { width: 30px; height: 30px; padding: 5px; flex: none; border-radius: 8px; background: var(--dbp-forecast-accent); fill: none; stroke: var(--dbp-forecast-deep); stroke-width: 2; stroke-linecap: round; }
  .dbp-forecast-brand span { display: grid; line-height: 1.2; }
  .dbp-forecast-brand b { font-weight: 720; letter-spacing: -0.01em; }
  .dbp-forecast-brand small { font-size: 11px; color: var(--dbp-forecast-muted); }
  .dbp-forecast-nav { display: grid; gap: 2px; }
  .dbp-forecast-navbtn { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--dbp-forecast-muted); font-weight: 560; transition: background-color 150ms, color 150ms; }
  .dbp-forecast-navbtn svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbp-forecast-navbtn:hover { color: var(--dbp-forecast-ink); background: var(--dbp-forecast-line); }
  .dbp-forecast-navbtn[aria-current="page"] { color: var(--dbp-forecast-ink); background: var(--dbp-forecast-raised); }
  .dbp-forecast-navbtn[aria-current="page"] svg { color: var(--dbp-forecast-accent); }
  .dbp-forecast-method { margin-top: auto; display: grid; gap: 6px; padding: 12px 8px 0; border-top: 1px solid var(--dbp-forecast-line); }
  .dbp-forecast-method p { font-size: 11.5px; line-height: 1.5; color: var(--dbp-forecast-muted); }

  /* ---------- top ---------- */
  .dbp-forecast-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 16px 20px 12px; }
  .dbp-forecast-title { display: grid; gap: 3px; }
  .dbp-forecast-h { font-size: clamp(19px, 0.95rem + 0.9cqi, 27px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; }
  .dbp-forecast-btn { height: 32px; padding: 0 12px; display: inline-flex; align-items: center; gap: 7px; border-radius: 9px; font-size: 12px; font-weight: 640; box-shadow: inset 0 0 0 1px var(--dbp-forecast-line-2); transition: background-color 150ms, transform 220ms var(--dbp-forecast-spring); }
  .dbp-forecast-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: rotate 600ms var(--dbp-forecast-spring); }
  .dbp-forecast-btn:hover { background: var(--dbp-forecast-line); }
  .dbp-forecast-btn:active { transform: scale(0.95); }
  .dbp-forecast-btn[data-spin] svg { rotate: 360deg; }

  /* ---------- main ---------- */
  .dbp-forecast-main { grid-area: main; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 0 20px 18px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbp-forecast-line-2) transparent; }
  .dbp-forecast-grid { min-height: 0; display: grid; grid-template-columns: 262px minmax(0, 1fr); gap: 12px; }
  .dbp-forecast-grid > * { animation: dbp-forecast-rise 500ms var(--dbp-forecast-ease) both; animation-delay: calc(var(--i, 0) * 70ms); }
  .dbp-forecast-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbp-forecast-panel); box-shadow: inset 0 0 0 1px var(--dbp-forecast-line); }

  /* ---------- KPIs ---------- */
  .dbp-forecast-kpis { display: grid; grid-template-columns: 1.25fr repeat(3, minmax(0, 1fr)); gap: 10px; animation: dbp-forecast-rise 500ms var(--dbp-forecast-ease) both; }
