const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const fmt = n => Math.round(n).toLocaleString('en-US');
const niceStep = raw => { const p = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-6)))), f = raw / p; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; };

/* ---------- throughput history ----------
   Items the checkout team finished in each of the last 26 weeks (Mon 6 Apr to Fri 2 Oct).
   The team grew from four to six engineers in July; mid-August is the summer shutdown.
   Forecast weeks start Mon 5 Oct, and week k ends on its Friday. The when-view counts
   working days: day v of the forecast is weekday ((v - 1) % 5) of week ceil(v / 5). */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const THRU = [4, 5, 3, 6, 5, 4, 6, 5, 6, 3, 5, 6, 4, 7, 6, 8, 7, 9, 5, 3, 4, 9, 8, 10, 7, 11];
const HIST0 = Date.UTC(2026, 3, 6), START = Date.UTC(2026, 9, 5), DAY = 864e5, TRIALS = 10000;
const md = t => { const d = new Date(t); return `${MON[d.getUTCMonth()]} ${d.getUTCDate()}`; };
const wd = t => `${DOW[new Date(t).getUTCDay()]} ${md(t)}`;
const dayT = v => START + (Math.floor((v - 1) / 5) * 7 + ((v - 1) % 5)) * DAY;
const fri = k => dayT(5 * k);
const histWeek = i => HIST0 + i * 7 * DAY;

/* ---------- state ---------- */
const S = { view: 'when', backlog: 64, growth: 15, win: 13, target: 11, seed: 1, hover: null, tHover: null, drag: false };
const pool = () => THRU.slice(-S.win);

/* ---------- the simulation ----------
   Every future i gets its own seeded stream (common random numbers), so moving a slider
   changes each future a little rather than re-drawing all of them: the histogram slides
   instead of jittering. When: the working day backlog + growth is cleared (the last week's
   output is spread over its five days). How many: items finished in `target` weeks. */
let st = 0;
const rnd = () => { st = (st + 0x6D2B79F5) | 0; let t = Math.imul(st ^ (st >>> 15), 1 | st); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const simulate = () => {
  const P = pool(), n = P.length, out = new Int32Array(TRIALS), g = S.growth / 100;
  let maxV = 0;
  for (let i = 0; i < TRIALS; i++) {
    st = S.seed * 1000003 + i * 7919;
    const share = rnd();
    let v = 0;
    if (S.view === 'when') {
      let left = Math.round(S.backlog * (1 + g * (0.5 + share))), w = 0;
      while (left > 0 && w < 156) {
        const t = P[(rnd() * n) | 0]; w++;
        /* the last item lands somewhere inside its slot of the final week */
        if (left <= t) { v = (w - 1) * 5 + Math.min(5, 1 + Math.floor(5 * (left - rnd()) / t)); left = 0; } else left -= t;
      }
      if (left > 0) v = w * 5;
    } else {
      for (let w = 0; w < S.target; w++) v += P[(rnd() * n) | 0];
    }
    out[i] = v; if (v > maxV) maxV = v;
  }
  const full = new Float64Array(maxV + 2);
  for (let i = 0; i < TRIALS; i++) full[out[i]]++;
  return { out, full };
};
/* nearest-rank quantile over a per-value count array */
const quant = (dist, tot, p) => {
  if (tot <= 0) return 0;
  const rank = Math.max(1, Math.ceil(p * tot - 1e-9));
  let c = 0;
  for (let v = 0; v < dist.length; v++) { c += dist[v]; if (c >= rank - 1e-9) return v; }
  return dist.length - 1;
};
const sumRange = (dist, a, b) => { let c = 0; for (let v = Math.max(0, a); v < Math.min(dist.length, b); v++) c += dist[v]; return c; };
const marker = () => (S.view === 'when' ? S.target : S.backlog);
const markV = () => (S.view === 'when' ? 5 * S.target : S.backlog);
const layout = R => {
  const lo = quant(R.full, TRIALS, 0.002), hi = quant(R.full, TRIALS, 0.998), mk = markV();
  if (S.view === 'when') return { x0: Math.max(1, Math.min(lo, mk) - 3), x1: Math.max(hi, mk) + 4, bw: 1 };
  const span = Math.max(hi, mk) - Math.min(lo, mk) + 1, bw = Math.max(1, Math.ceil(span / 30));
  const x0 = Math.floor((Math.min(lo, mk) - bw) / bw) * bw, x1 = (Math.floor(Math.max(hi, mk) / bw) + 2) * bw;
  return { x0: Math.max(0, x0), x1, bw };
};
const peak = (dist, d) => { let m = 0; for (let v = d.x0; v < d.x1; v += d.bw) m = Math.max(m, sumRange(dist, v, v + d.bw)); return m; };
const frameFor = R => { const d = layout(R), pk = peak(R.full, d), step = niceStep(pk / 4); return { ...d, yMax: Math.max(step, Math.ceil(pk * 1.06 / step) * step), dist: R.full, tot: TRIALS }; };
const lerpF = (a, b, e) => {
  const n = Math.max(a.dist.length, b.dist.length), dist = new Float64Array(n);
  for (let i = 0; i < n; i++) dist[i] = (a.dist[i] || 0) * (1 - e) + (b.dist[i] || 0) * e;
  return { x0: a.x0 + (b.x0 - a.x0) * e, x1: a.x1 + (b.x1 - a.x1) * e, bw: b.bw, yMax: a.yMax + (b.yMax - a.yMax) * e, dist, tot: a.tot + (b.tot - a.tot) * e };
};
/* read-outs from any frame, so KPIs converge while futures pour in and glide during tweens */
const readF = f => {
  const t = f.tot;
  if (S.view === 'when') {
    const hits = sumRange(f.dist, 0, 5 * S.target + 1);
    return { hits, p: hits / Math.max(1, t), q50: quant(f.dist, t, 0.5), q85: quant(f.dist, t, 0.85), q95: quant(f.dist, t, 0.95) };
  }
  const hits = sumRange(f.dist, S.backlog, f.dist.length);
  return { hits, p: hits / Math.max(1, t), q50: quant(f.dist, t, 0.5), q85: quant(f.dist, t, 0.15), q95: quant(f.dist, t, 0.05) };
};

/* ---------- chart ---------- */
const chart = $('[data-chart]'), csvg = $('[data-csvg]'), tip = $('[data-tip]');
const clipId = 'dbp-forecast-clip-' + Math.random().toString(36).slice(2, 9);
let R = null, F = null, anim = null, CW = 0, CH = 0, hoverPx = 0;
const geo = () => { const m = { l: 52, r: 50, t: 40, b: 40 }; return { m, iw: Math.max(20, CW - m.l - m.r), ih: Math.max(20, CH - m.t - m.b) }; };
const scales = () => {
  const { m, iw, ih } = geo();
  return { m, iw, ih, X: v => m.l + (v - F.x0) / (F.x1 - F.x0) * iw, IX: px => F.x0 + (px - m.l) / iw * (F.x1 - F.x0), Y: c => m.t + ih - c / F.yMax * ih, YP: p => m.t + ih - p * ih };
};
const paintChart = () => {
  CW = chart.clientWidth; CH = chart.clientHeight;
  if (!CW || !CH || !F) return;
  const when = S.view === 'when', { m, iw, ih, X, Y, YP } = scales(), bw = F.bw, tot = F.tot;
  let s = `<defs><clipPath id="${clipId}"><rect x="${m.l}" y="${m.t - 30}" width="${iw}" height="${ih + 30}"/></clipPath></defs>`;
  /* y grid: futures per bucket on the left, cumulative share on the right */
  const step = niceStep(F.yMax / 4);
  for (let c = 0; c <= F.yMax + 1e-6; c += step) {
    const y = Math.round(Y(c)) + 0.5;
    s += `<line class="dbp-forecast-gl" x1="${m.l}" x2="${m.l + iw}" y1="${y}" y2="${y}"/><text x="${m.l - 8}" y="${y + 3.5}" text-anchor="end">${fmt(c)}</text>`;
  }
  [0, 0.25, 0.5, 0.75, 1].forEach(p => { s += `<text x="${m.l + iw + 8}" y="${YP(p) + 3.5}">${p * 100}%</text>`; });
  s += `<text class="dbp-forecast-cap" transform="translate(12 ${m.t + ih / 2}) rotate(-90)" text-anchor="middle">FUTURES</text>`;
  s += `<text class="dbp-forecast-cap" transform="translate(${CW - 10} ${m.t + ih / 2}) rotate(90)" text-anchor="middle">${when ? 'DONE BY THEN' : 'AT LEAST THIS MANY'}</text>`;
  /* bars */
  const first = Math.floor(F.x0 / bw) * bw, gap = Math.min(3, (X(first + bw) - X(first)) * 0.2);
  let bars = '', cdf = '', below = sumRange(F.dist, 0, first);
  const P = c => (tot > 0 ? c / tot : 0);
  cdf = `M${X(first).toFixed(1)},${YP(when ? P(below) : 1 - P(below)).toFixed(1)}`;
  for (let v = first; v < F.x1; v += bw) {
    const c = sumRange(F.dist, v, v + bw);
    if (c >= 0.5) {
      const x = X(v) + gap / 2, w = Math.max(1, X(v + bw) - X(v) - gap), y = Y(c);
      const hit = when ? v + bw - 1 <= 5 * S.target : v >= S.backlog;
      bars += `<rect class="dbp-forecast-bar"${hit ? ' data-hit' : ''}${S.hover === v ? ' data-on' : ''} x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${w.toFixed(1)}" height="${(m.t + ih - y).toFixed(1)}" rx="2"/>`;
    }
    below += c;
    cdf += `L${X(v + bw).toFixed(1)},${YP(when ? P(below) : 1 - P(below)).toFixed(1)}`;
  }
  s += `<g clip-path="url(#${clipId})">${bars}${tot > 0 ? `<path class="dbp-forecast-cdf" d="${cdf}"/>` : ''}</g>`;
  /* x axis */
  s += `<line class="dbp-forecast-gl" x1="${m.l}" x2="${m.l + iw}" y1="${m.t + ih + 0.5}" y2="${m.t + ih + 0.5}" style="stroke:var(--dbp-forecast-line-2)"/>`;
  if (when) {
    /* a tick at every week boundary, the Friday labelled as often as there is room */
    const wk = (X(6) - X(1)), every = Math.max(1, Math.ceil(52 / wk));
    for (let k = Math.max(1, Math.floor(F.x0 / 5)); 5 * k <= F.x1; k++) {
      const xb = Math.round(X(5 * k + 1)) + 0.5, x = X(5 * k + 0.5);
      if (xb > m.l && xb < m.l + iw) s += `<line class="dbp-forecast-gl" x1="${xb}" x2="${xb}" y1="${m.t + ih}" y2="${m.t + ih + 5}" style="stroke:var(--dbp-forecast-line-2)"/>`;
      if (k % every === 0 && x > m.l + 14 && x < m.l + iw - 14) s += `<text x="${x.toFixed(1)}" y="${m.t + ih + 17}" text-anchor="middle">${md(fri(k))}</text>`;
    }
  } else {
    const tk = niceStep((F.x1 - F.x0) / Math.max(3, iw / 70));
    for (let v = Math.ceil(F.x0 / tk) * tk; v < F.x1; v += tk) { const x = X(v); if (x > m.l + 8 && x < m.l + iw - 8) s += `<text x="${x.toFixed(1)}" y="${m.t + ih + 17}" text-anchor="middle">${v}</text>`; }
  }
  s += `<text class="dbp-forecast-cap" x="${m.l}" y="${CH - 5}">${when ? 'FINISH DAY · WORKING DAYS, FRIDAYS LABELLED' : `ITEMS FINISHED BY ${md(fri(S.target)).toUpperCase()}`}</text>`;
  /* percentile lines, converging while the futures pour in */
  if (tot >= 50) {
    const r = readF(F);
    [[r.q50, '50%'], [r.q85, '85%'], [r.q95, '95%']].forEach(([v, lab], i) => {
      const x = Math.round(when ? X(v + 1) : X(v)) + 0.5, y = m.t + 12 + i * 14;
      if (x < m.l || x > m.l + iw) return;
      const right = x < m.l + iw - 96;
      s += `<line class="dbp-forecast-pl" x1="${x}" x2="${x}" y1="${y - 6}" y2="${m.t + ih}"/><text class="dbp-forecast-plab" x="${right ? x + 5 : x - 5}" y="${y}" text-anchor="${right ? 'start' : 'end'}">${lab} · ${when ? md(dayT(v)) : `≥ ${v}`}</text>`;
    });
  }
  /* the draggable target */
  const mx = Math.round(when ? X(5 * S.target + 1) : X(S.backlog)) + 0.5, lab = when ? md(fri(S.target)) : `need ${S.backlog}`;
  const pw = lab.length * 6.9 + 16, pxl = clamp(mx - pw / 2, m.l - 24, m.l + iw + 24 - pw);
  s += `<g class="dbp-forecast-tgt"><line x1="${mx}" x2="${mx}" y1="${m.t - 12}" y2="${m.t + ih}"/><rect x="${pxl.toFixed(1)}" y="${m.t - 32}" width="${pw.toFixed(1)}" height="20" rx="10"/><text x="${(pxl + pw / 2).toFixed(1)}" y="${m.t - 18}" text-anchor="middle">${lab}</text><circle cx="${mx}" cy="${m.t + ih}" r="6"/></g>`;
  csvg.setAttribute('viewBox', `0 0 ${CW} ${CH}`);
  csvg.innerHTML = s;
};

/* ---------- KPIs, readout, counters ---------- */
const kpis = $('[data-kpis]'), read = $('[data-read]'), runs = $('[data-runs]'), runbar = $('[data-runbar]'), runsBox = runs.parentElement;
const kpi = (k, label, big, sub) => `<div class="dbp-forecast-kpi"${k ? ` data-k="${k}"` : ''}><span>${label}</span><b>${big}</b><small>${sub}</small></div>`;
const paintKpis = () => {
  if (!F) return;
  const r = readF(F), pct = Math.round(r.p * 100);
  if (S.view === 'when') {
    kpis.innerHTML = kpi('hit', `Chance to ship by ${wd(fri(S.target))}`, `${pct}%<small>of futures</small>`, `${fmt(r.hits)} of ${fmt(F.tot)} simulated`) +
      kpi('', '50% likely by', wd(dayT(r.q50)), `${r.q50} work days · a coin flip`) +
      kpi('', '85% likely by', wd(dayT(r.q85)), `${r.q85} work days · safe to commit`) +
      kpi('', '95% likely by', wd(dayT(r.q95)), `${r.q95} work days · near-certain`);
  } else {
    kpis.innerHTML = kpi('hit', `Chance of ${S.backlog}+ items by ${md(fri(S.target))}`, `${pct}%<small>of futures</small>`, `${fmt(r.hits)} of ${fmt(F.tot)} simulated`) +
      kpi('', '50% confident', `≥ ${r.q50}`, 'items · a coin flip') +
      kpi('', '85% confident', `≥ ${r.q85}`, 'items · safe to promise') +
      kpi('', '95% confident', `≥ ${r.q95}`, 'items · near-certain');
  }
  runs.textContent = fmt(F.tot);
  runbar.style.setProperty('--f', (F.tot / TRIALS).toFixed(4));
};
/* "how many fit by the date", for the when-view readout: a second, cheap simulation */
const fitBy = weeks => {
  const P = pool(), n = P.length, out = new Int32Array(TRIALS);
  for (let i = 0; i < TRIALS; i++) { st = S.seed * 1000003 + i * 7919; rnd(); let v = 0; for (let w = 0; w < weeks; w++) v += P[(rnd() * n) | 0]; out[i] = v; }
  out.sort(); return out[Math.ceil(0.15 * TRIALS) - 1];
};
const paintRead = () => {
  if (!F) return;
  const r = readF(F), pct = Math.round(r.p * 100), T = wd(fri(S.target));
  if (S.view === 'when') {
    const need = Math.round(S.backlog * (1 + S.growth / 100)), fit = fitBy(S.target);
    const lead = pct >= 85 ? `<em>${T}</em> is a safe commitment: <b>${pct}%</b> of futures make it.`
      : pct >= 50 ? `<em>${T}</em> is likely but not safe: <b>${pct}%</b> of futures make it. With 85% confidence the rewrite ships by <b>${wd(dayT(r.q85))}</b>, ${r.q85 - 5 * S.target} working day${r.q85 - 5 * S.target === 1 ? '' : 's'} later.`
      : `<em>${T}</em> is unlikely: only <b>${pct}%</b> of futures make it. The median future ships <b>${wd(dayT(r.q50))}</b>.`;
    read.innerHTML = `${lead} In 85% of futures the team finishes at least <b>${fit}</b> items by then, against about <b>${need}</b> needed once scope grows.`;
  } else {
    read.innerHTML = `By <em>${T}</em>, ${S.target} weeks out, 85% of futures finish at least <b>${r.q85}</b> items and half finish <b>${r.q50}</b> or more. A <b>${S.backlog}</b>-item scope is cleared in <b>${pct}%</b> of them.`;
  }
};
const syncChartAria = () => {
  if (S.view === 'when') {
    chart.setAttribute('aria-label', 'Target date. Arrow keys move it by a week.');
    chart.setAttribute('aria-valuemin', '2'); chart.setAttribute('aria-valuemax', '26'); chart.setAttribute('aria-valuenow', String(S.target));
    chart.setAttribute('aria-valuetext', `${wd(fri(S.target))}, ${F ? Math.round(readF(F).p * 100) : 0}% of futures done`);
  } else {
    chart.setAttribute('aria-label', 'Items needed. Arrow keys change it by one.');
    chart.setAttribute('aria-valuemin', '20'); chart.setAttribute('aria-valuemax', '160'); chart.setAttribute('aria-valuenow', String(S.backlog));
    chart.setAttribute('aria-valuetext', `${S.backlog} items, ${F ? Math.round(readF(F).p * 100) : 0}% of futures reach it`);
  }
};
const paintAll = settled => {
  paintChart(); paintKpis();
  if (!tip.hidden && S.hover != null) showTip(S.hover, hoverPx);
  if (settled) { paintRead(); syncChartAria(); kpis.setAttribute('aria-busy', 'false'); runsBox.removeAttribute('data-live'); }
};

/* ---------- animation: pour the futures in, or glide between results ---------- */
let raf = 0, last = 0, onScreen = true;
const FILL = 1400, GLIDE = 460;
const easeOut = t => 1 - Math.pow(1 - t, 4);
const loop = now => {
  if (!root.isConnected) return;
  const dt = Math.min(48, last ? now - last : 16); last = now;
  if (anim) {
    anim.t += dt;
    if (anim.kind === 'fill') {
      const k = Math.round(TRIALS * (1 - Math.pow(1 - Math.min(1, anim.t / FILL), 2.2)));
      for (let i = anim.k; i < k; i++) anim.ex[anim.out[i]]++;
      anim.k = k; F = { ...anim.to, dist: anim.ex, tot: k };
      if (anim.t >= FILL) { F = anim.to; anim = null; }
    } else {
      F = lerpF(anim.from, anim.to, easeOut(Math.min(1, anim.t / GLIDE)));
      if (anim.t >= GLIDE) { F = anim.to; anim = null; }
    }
    paintAll(!anim);
  }
  if (anim && onScreen && !document.hidden) raf = requestAnimationFrame(loop);
  else { raf = 0; last = 0; }
};
const kick = () => { if (!raf && anim && onScreen && !document.hidden) { last = 0; raf = requestAnimationFrame(loop); } };
const go = (mode, resim = true) => {
  if (resim || !R) R = simulate();
  const to = frameFor(R);
  if (reduce || mode === 'now') { anim = null; F = to; }
  else if (mode === 'fill' || !F) { anim = { kind: 'fill', t: 0, k: 0, out: R.out, ex: new Float64Array(R.full.length), to }; F = { ...to, dist: anim.ex, tot: 0 }; }
  else anim = { kind: 'glide', t: 0, from: F, to };
  if (anim) { kpis.setAttribute('aria-busy', 'true'); if (anim.kind === 'fill') runsBox.setAttribute('data-live', ''); }
  paintAll(!anim); kick();
};

/* ---------- throughput history strip ---------- */
const tbox = $('[data-thru]'), tsvg = $('[data-tsvg]'), ttip = $('[data-ttip]'), tnote = $('[data-tnote]');
const median = a => { const s = a.slice().sort((x, y) => x - y), h = s.length >> 1; return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2; };
let TG = null;
const buildThru = () => {
  const w = tbox.clientWidth, h = tbox.clientHeight; if (!w) return;
  const m = { l: 1, r: 1, t: 14, b: 16 }, n = THRU.length, bw = (w - m.l - m.r) / n, top = 12, ih = h - m.t - m.b;
  const y = v => m.t + ih * (1 - v / top);
  TG = { m, bw, y, w, h };
  let s = THRU.map((v, i) => `<rect data-i="${i}" x="${(m.l + i * bw + 1).toFixed(1)}" y="${y(v).toFixed(1)}" width="${Math.max(1, bw - 2).toFixed(1)}" height="${(y(0) - y(v)).toFixed(1)}" rx="1.5" style="--i:${i}"/>`).join('');
  s += `<line data-med x1="0" x2="0" y1="0" y2="0"/><text data-medl x="${w - m.r}" y="9" text-anchor="end"></text>`;
  s += `<text x="${m.l}" y="${h - 3}">${md(histWeek(0))}</text><text data-wl y="${h - 3}"></text><text x="${w - m.r}" y="${h - 3}" text-anchor="end">${md(histWeek(n - 1))}</text>`;
  tsvg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  tsvg.innerHTML = s;
  paintThru();
};
const paintThru = () => {
  if (!TG) return;
  const n = THRU.length, P = pool(), med = median(P), from = n - S.win, { m, bw, y, w } = TG;
  $$('rect', tsvg).forEach((r, i) => { r.toggleAttribute('data-in', i >= from); r.toggleAttribute('data-on', S.tHover === i); });
  const ln = $('[data-med]', tsvg), x1 = m.l + from * bw;
  ln.setAttribute('x1', x1.toFixed(1)); ln.setAttribute('x2', (w - m.r).toFixed(1)); ln.setAttribute('y1', y(med).toFixed(1)); ln.setAttribute('y2', y(med).toFixed(1));
  $('[data-medl]', tsvg).textContent = `median ${med}`;
  const wl = $('[data-wl]', tsvg);
  wl.textContent = from > 0 && from < n - 5 ? md(histWeek(from)) : '';
  wl.setAttribute('x', (x1 + 1).toFixed(1));
  const avg = P.reduce((a, b) => a + b, 0) / P.length;
  tnote.innerHTML = `Sampling the last <b>${S.win} weeks</b>: median <b>${med}</b> items a week, between <b>${Math.min(...P)}</b> and <b>${Math.max(...P)}</b>, averaging <b>${avg.toFixed(1)}</b>.`;
  tbox.setAttribute('aria-label', `Weekly throughput, ${md(histWeek(0))} to ${md(histWeek(n - 1))}. The last ${S.win} weeks are sampled; median ${med} items a week. Arrow keys read each week.`);
};
const thruTip = i => {
  S.tHover = i; paintThru();
  if (i == null || !TG) { ttip.hidden = true; return; }
  ttip.textContent = `Wk of ${md(histWeek(i))} · ${THRU[i]} item${THRU[i] === 1 ? '' : 's'}${i >= THRU.length - S.win ? '' : ' · not sampled'}`;
  ttip.hidden = false;
  const x = TG.m.l + (i + 0.5) * TG.bw, tw = ttip.offsetWidth;
  ttip.style.left = clamp(x, tw / 2, TG.w - tw / 2) + 'px';
};
tbox.addEventListener('pointermove', e => { if (!TG) return; const r = tbox.getBoundingClientRect(), i = clamp(Math.floor((e.clientX - r.left - TG.m.l) / TG.bw), 0, THRU.length - 1); if (i !== S.tHover) thruTip(i); });
tbox.addEventListener('pointerleave', () => thruTip(null));
tbox.addEventListener('blur', () => thruTip(null));
tbox.addEventListener('keydown', e => {
  const n = THRU.length, k = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
  if (k) { e.preventDefault(); thruTip(clamp((S.tHover ?? (k > 0 ? n - S.win - 1 : n)) + k, 0, n - 1)); }
  else if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); thruTip(e.key === 'Home' ? 0 : n - 1); }
  else if (e.key === 'Escape') thruTip(null);
});

/* ---------- chart pointer: hover reads a bucket, drag moves the target ---------- */
const bucketAt = px => { if (!F) return null; const v = Math.floor(scales().IX(px) / F.bw) * F.bw; return v >= Math.floor(F.x0 / F.bw) * F.bw && v < F.x1 ? v : null; };
const showTip = (v, px) => {
  if (v == null || !F || S.drag) { tip.hidden = true; return; }
  const when = S.view === 'when', bw = F.bw, c = sumRange(F.dist, v, v + bw), t = Math.max(1, F.tot);
  const cum = when ? sumRange(F.dist, 0, v + bw) : sumRange(F.dist, v, F.dist.length);
  tip.innerHTML = when
    ? `<b>Finishing ${wd(dayT(v))}</b><span>Futures finishing that day <em>${fmt(c)}</em></span><span>Share of all futures <em>${(c / t * 100).toFixed(1)}%</em></span><span>Done by then <em>${(cum / t * 100).toFixed(1)}%</em></span>`
    : `<b>${bw > 1 ? `${v}–${v + bw - 1}` : v} items by ${md(fri(S.target))}</b><span>Futures in this range <em>${fmt(c)}</em></span><span>Share of all futures <em>${(c / t * 100).toFixed(1)}%</em></span><span>At least ${v} items <em>${(cum / t * 100).toFixed(1)}%</em></span>`;
  tip.hidden = false;
  const tw = tip.offsetWidth;
  tip.style.top = '46px';
  tip.style.left = (px + 16 + tw > CW ? Math.max(4, px - 16 - tw) : px + 16) + 'px';
};
const setMarker = (v, from) => {
  if (S.view === 'when') {
    v = clamp(v, 2, 26); if (v === S.target) return;
    S.target = v; inputs.target.value = v; outs();
    go('glide', false);
  } else {
    v = clamp(v, 20, 160); if (v === S.backlog) return;
    S.backlog = v; inputs.backlog.value = v; outs();
    go('glide', false);
  }
  if (from !== 'key') hoverAt(null);
};
const valueAt = px => { const raw = scales().IX(px); return S.view === 'when' ? Math.round((raw - 1) / 5) : Math.round(raw); };
const hoverAt = px => { hoverPx = px; const v = px == null ? null : bucketAt(px); if (v !== S.hover) { S.hover = v; paintChart(); } showTip(v, px); };
chart.addEventListener('pointerdown', e => {
  if (e.button !== 0 || !F) return;
  const r = chart.getBoundingClientRect();
  S.drag = true; chart.setAttribute('data-drag', ''); chart.setPointerCapture(e.pointerId); tip.hidden = true;
  setMarker(valueAt(e.clientX - r.left), 'drag');
});
chart.addEventListener('pointermove', e => {
  const r = chart.getBoundingClientRect(), px = e.clientX - r.left;
  if (S.drag) setMarker(valueAt(px), 'drag'); else hoverAt(px);
});
const endDrag = e => { if (!S.drag) return; S.drag = false; chart.removeAttribute('data-drag'); if (chart.hasPointerCapture(e.pointerId)) chart.releasePointerCapture(e.pointerId); syncChartAria(); };
chart.addEventListener('pointerup', endDrag);
chart.addEventListener('pointercancel', endDrag);
chart.addEventListener('pointerleave', () => { if (!S.drag) { S.hover = null; paintChart(); tip.hidden = true; } });
chart.addEventListener('keydown', e => {
  const k = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1, PageUp: 4, PageDown: -4 }[e.key];
  const cur = marker();
  if (k) { e.preventDefault(); setMarker(cur + k, 'key'); }
  else if (e.key === 'Home') { e.preventDefault(); setMarker(S.view === 'when' ? 2 : 20, 'key'); }
  else if (e.key === 'End') { e.preventDefault(); setMarker(S.view === 'when' ? 26 : 160, 'key'); }
});

/* ---------- inputs ---------- */
const inputs = { backlog: $('[data-in="backlog"]'), growth: $('[data-in="growth"]'), target: $('[data-in="target"]') };
const outs = () => {
  $('[data-o="backlog"]').textContent = S.backlog;
  $('[data-o="growth"]').textContent = `${S.growth}%`;
  $('[data-o="target"]').textContent = wd(fri(S.target));
  inputs.target.setAttribute('aria-valuetext', `${wd(fri(S.target))}, ${S.target} weeks`);
  inputs.growth.setAttribute('aria-valuetext', `${S.growth} percent`);
  $('[data-eyebrow]').textContent = S.view === 'when' ? `Checkout rewrite · ${S.backlog} items left · from Mon Oct 5` : `Checkout rewrite · ${S.target} weeks of throughput`;
  $('[data-title]').textContent = S.view === 'when' ? 'When will the checkout rewrite ship?' : `How much lands by ${wd(fri(S.target))}?`;
  $('[data-ctitle]').textContent = S.view === 'when' ? 'Finish day across 10,000 futures' : `Items finished by ${md(fri(S.target))} across 10,000 futures`;
};
Object.entries(inputs).forEach(([k, el]) => el.addEventListener('input', () => {
  S[k] = +el.value; outs();
  /* the when-view re-simulates on scope, the how-many view on the date; the other input only moves the marker */
  const resim = S.view === 'when' ? k !== 'target' : k === 'target';
  go('glide', resim);
}));

const seg = $('[data-group="win"]'), segBtns = $$('[role="radio"]', seg);
const pickWin = (b, focus) => {
  segBtns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
  if (focus) b.focus();
  S.win = +b.dataset.v; paintThru(); go('fill');
};
segBtns.forEach(b => { b.tabIndex = b.getAttribute('aria-checked') === 'true' ? 0 : -1; });
seg.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pickWin(b); });
seg.addEventListener('keydown', e => {
  const k = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key]; if (!k) return;
  e.preventDefault(); const i = segBtns.findIndex(b => b.getAttribute('aria-checked') === 'true');
  pickWin(segBtns[(i + k + segBtns.length) % segBtns.length], true);
});

let spins = 0;
const reroll = $('[data-reroll]');
reroll.addEventListener('click', () => {
  S.seed++; spins++;
  const ic = $('svg', reroll); ic.style.rotate = `${spins * 360}deg`;
  go('fill');
});

/* ---------- views ---------- */
const navs = $$('.dbp-forecast-navbtn');
const setView = v => {
  if (v === S.view) return;
  S.view = v; S.hover = null; tip.hidden = true;
  navs.forEach(b => { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  inputs.growth.disabled = v === 'many';
  $('[data-growth]').title = v === 'many' ? 'Scope growth does not change how much the team finishes, only how much it needs' : '';
  outs(); F = null; go('fill');
};
navs.forEach(b => b.addEventListener('click', () => setView(b.dataset.view)));
$('.dbp-forecast-nav').addEventListener('keydown', e => {
  const k = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const i = navs.indexOf(e.target.closest('.dbp-forecast-navbtn')); if (i < 0) return;
  e.preventDefault(); const n = navs[(i + k + navs.length) % navs.length]; n.focus(); setView(n.dataset.view);
});

/* ---------- lifecycle ---------- */
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
}
document.addEventListener('visibilitychange', onVis);
const io = new IntersectionObserver(es => {
  if (!root.isConnected) { io.disconnect(); return; }
  onScreen = es[es.length - 1].isIntersecting; kick();
});
io.observe(root);
let lastSize = '';
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const key = `${chart.clientWidth}x${chart.clientHeight}|${tbox.clientWidth}`;
  if (key === lastSize) return;
  lastSize = key; buildThru(); paintChart();
});
ro.observe(chart); ro.observe(tbox);
setTimeout(() => tbox.setAttribute('data-ready', ''), 1400);

outs(); buildThru(); go('fill');

css:
@keyframes dbp-deps-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbp-deps-fade { from { opacity: 0; } }
@keyframes dbp-deps-spin { from { opacity: 0; transform: rotate(-24deg) scale(0.92); } }

.dbp-deps {
  /* re-theme with these four */
  --dbp-deps-paper: oklch(0.975 0.012 85);
  --dbp-deps-ink: oklch(0.25 0.025 50);
  --dbp-deps-accent: oklch(0.47 0.09 200);
  --dbp-deps-alert: oklch(0.58 0.2 28);
  /* derived */
  --dbp-deps-warn: color-mix(in oklch, var(--dbp-deps-alert), oklch(0.8 0.15 80) 75%);
  --dbp-deps-ok: color-mix(in oklch, var(--dbp-deps-accent), oklch(0.68 0.14 155) 70%);
  --dbp-deps-done: color-mix(in oklch, var(--dbp-deps-ink) 25%, var(--dbp-deps-paper));
  --dbp-deps-card: color-mix(in oklch, var(--dbp-deps-paper), white 55%);
  --dbp-deps-sunk: color-mix(in oklch, var(--dbp-deps-paper), var(--dbp-deps-ink) 5%);
  --dbp-deps-line: color-mix(in oklch, var(--dbp-deps-ink) 10%, transparent);
  --dbp-deps-line-2: color-mix(in oklch, var(--dbp-deps-ink) 20%, transparent);
  --dbp-deps-muted: color-mix(in oklch, var(--dbp-deps-ink) 62%, var(--dbp-deps-paper));
  --dbp-deps-faint: color-mix(in oklch, var(--dbp-deps-ink) 42%, var(--dbp-deps-paper));
  --dbp-deps-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbp-deps-mono: ui-monospace, Menlo, monospace;

  width: 100%;
  height: var(--dbp-deps-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbp-deps-paper);
  color: var(--dbp-deps-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  accent-color: var(--dbp-deps-accent);
  box-shadow: inset 0 0 0 1px var(--dbp-deps-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & select { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbp-deps-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4, & h5 { margin: 0; font-family: inherit; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbp-deps-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbp-deps-muted); }

