const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

/* ---------- teams and requests ----------
   A request runs from the team that needs it to the team that provides it. The
   chord, the matrix, the list and every count are built from REQ after the status
   filter, so changing one request's status re-flows all of them. */
const TEAMS = [
  ['id', 'Identity', 270, 'Selin Aydın'], ['pay', 'Payments', 330, 'Marek Novák'], ['search', 'Search', 235, 'Ana Lucía Prado'], ['book', 'Booking', 145, 'Femi Adeyemi'],
  ['mob', 'Mobile', 300, 'Jules Moreau'], ['web', 'Web', 95, 'Rosa Lindqvist'], ['data', 'Data platform', 195, 'Arjun Mehta'], ['notif', 'Notifications', 55, 'Lena Kowalczyk']
].map(([id, name, h, lead], i) => ({ id, name, h, lead, i }));
const T = {}; TEAMS.forEach(t => { T[t.id] = t; });
const STATUS = { blocked: ['Blocked', 'alert', 0], risk: ['At risk', 'warn', 1], track: ['On track', 'ok', 2], done: ['Done', 'done', 3] };
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const fdue = off => { const d = new Date(Date.UTC(2026, 9, 2 + off)); return `${MON[d.getUTCMonth()]} ${d.getUTCDate()}`; };
const REQ = [
  ['mob', 'id', 'Passkey sign-in SDK for iOS', 'blocked', 8, 7], ['mob', 'id', 'Refresh-token rotation endpoint', 'track', 3, 21],
  ['mob', 'pay', 'Apple Pay tokenisation API', 'risk', 6, 14], ['mob', 'pay', 'Saved cards list endpoint', 'done', 2, -5],
  ['mob', 'book', 'Seat-map availability feed', 'track', 5, 28], ['mob', 'notif', 'Push templates for gate changes', 'track', 3, 21],
  ['mob', 'search', 'Offline recent searches API', 'track', 4, 35],
  ['web', 'id', 'SSO for corporate accounts', 'risk', 10, 14], ['web', 'id', 'Session revocation webhook', 'done', 2, -9],
  ['web', 'search', 'Typeahead v2 response schema', 'track', 3, 7], ['web', 'pay', '3-D Secure 2 challenge flow', 'blocked', 7, 0],
  ['web', 'book', 'Hold-and-pay-later API', 'risk', 9, 28], ['web', 'notif', 'In-app inbox web component', 'track', 5, 42],
  ['book', 'pay', 'Split payments across travellers', 'blocked', 12, 14], ['book', 'pay', 'Refund status events', 'track', 4, 21],
  ['book', 'search', 'Fare-rule snippets in results', 'track', 3, 28], ['book', 'data', 'Booking events in the warehouse', 'done', 5, -12],
  ['book', 'id', 'Traveller profile merge API', 'risk', 8, 21], ['book', 'notif', 'Boarding pass delivery', 'done', 4, -3],
