    g.mid = a;
    for (let s = 1; s < n; s++) { const j = (i - s + n) % n; if (M[j][i]) { inn[`${j}>${i}`] = [a, a + M[j][i] * k]; a += M[j][i] * k; } }
    g.a1 = a; a += PAD; groups[t.id] = g;
